# AppUpdater - Copyright (c) 2026 Lyvvy-xyz. Licensed under the Business Source License 1.1.

param(
  [string]$Wv2AssemblyDir = (Join-Path $PSScriptRoot 'wv2')
)
$__UiHtml = @'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>AppUpdater</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root{
  --void:#0D0E10; --panel:#131417; --panel-2:#191B1F;
  --edge:#24262B; --edge-hi:#31343A;
  --ink:#ECEAE4; --dim:#A3A19A; --faint:#8A8881; --rule:#1B1D21;
  --signal:#5468FF; --signal-2:#8FA0FF; --select:#1F2440;
  --ok:#4CC38A; --warn:#E5A93A; --bad:#EF5A5A;
  --code-str:#D6C49A;
  /* Channel values of the accent and status colours, for their translucent tints. */
  --signal-rgb:84,104,255; --signal-2-rgb:143,160,255; --ok-rgb:76,195,138; --warn-rgb:229,169,58; --bad-rgb:239,90,90;
  --on-accent:#FFFFFF;
  --ok-tint-bd:rgba(var(--ok-rgb),.3); --ok-tint-bg:rgba(var(--ok-rgb),.07);
  --warn-tint-bd:rgba(var(--warn-rgb),.3); --warn-tint-bg:rgba(var(--warn-rgb),.07);
  --grad:var(--signal);
  --r:8px; --r-sm:6px;
  --ease:cubic-bezier(.2,.8,.2,1);
  --font-d:'Geist','Segoe UI',system-ui,sans-serif; --font-b:'Geist','Segoe UI',system-ui,sans-serif; --font-m:'Geist Mono','Cascadia Mono',Consolas,monospace;
}
*{margin:0;padding:0;box-sizing:border-box}
html,body{height:100%}
body{background:var(--void);color:var(--ink);font-family:var(--font-b);font-size:13.5px;line-height:1.5;overflow:hidden}
body::before{content:'';position:fixed;inset:0;pointer-events:none;
  background:radial-gradient(600px 400px at 12% -8%, rgba(var(--signal-rgb),.055), transparent 60%),
             radial-gradient(700px 500px at 105% 110%, rgba(var(--signal-2-rgb),.05), transparent 60%)}
::selection{background:rgba(var(--signal-rgb),.28)}
button{font:inherit;color:inherit;background:none;border:none;cursor:pointer}
input,textarea,select{font:inherit;color:inherit}

.app{display:grid;grid-template-columns:64px 1fr;grid-template-rows:calc(100vh - 6px);height:calc(100vh - 6px)}
.rail{border-right:1px solid var(--edge);background:rgba(13,14,26,.6);display:flex;flex-direction:column;align-items:center;padding:14px 0 20px;gap:6px;z-index:5}
.logo{width:36px;height:36px;border-radius:9px;background:var(--grad);display:grid;place-items:center;margin-bottom:14px;box-shadow:0 0 24px rgba(var(--signal-rgb),.35);cursor:pointer}
.logo svg{transition:none}
.logo.spin svg{animation:logospin .6s cubic-bezier(.3,.1,.3,1)}
@keyframes logospin{to{transform:rotate(360deg)}}
.nav-btn{width:40px;height:40px;border-radius:9px;display:grid;place-items:center;color:var(--dim);
  transition:background .18s var(--ease),color .18s var(--ease),transform .18s var(--ease);position:relative}
.nav-btn:hover{background:var(--panel-2);color:var(--ink);transform:translateY(-1px)}
  #win-minimize:hover{background:var(--panel-2);color:var(--ink)}
  #win-close:hover{background:#e5484d;color:#fff}
.nav-btn.on{background:var(--panel-2);color:var(--signal)}
.nav-btn.on::before{content:'';position:absolute;left:-13px;top:9px;bottom:9px;width:2.5px;border-radius:2px;background:var(--grad)}
.nav-btn svg{width:19px;height:19px}
.rail .spacer{flex:1}
.nav-tip{position:absolute;left:52px;top:50%;translate:0 -50%;background:var(--panel-2);border:1px solid var(--edge);
  padding:4px 10px;border-radius:6px;font-size:11.5px;white-space:nowrap;opacity:0;pointer-events:none;
  transition:opacity .15s var(--ease),translate .15s var(--ease);z-index:50}
.nav-btn:hover .nav-tip{opacity:1;translate:4px -50%}

.stage{display:flex;flex-direction:column;min-width:0;height:calc(100vh - 6px);min-height:0}
.rail{height:calc(100vh - 6px)}
.topbar{height:64px;border-bottom:1px solid var(--edge);display:flex;align-items:center;gap:22px;padding:0 26px;flex-shrink:0}
.crumb{font-family:var(--font-d);font-weight:600;font-size:15px;letter-spacing:.01em}

.pipe{display:flex;align-items:center;gap:0;margin-left:auto}
.pnode{display:flex;align-items:center}
.pnode[data-pipe-step]{cursor:pointer}
.card.pulse{animation:pulse 1s var(--ease)}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(var(--signal-rgb),.55)}100%{box-shadow:0 0 0 14px rgba(var(--signal-rgb),0)}}
@media (prefers-reduced-motion:reduce){.card.pulse{animation:none}}
.pdot{width:26px;height:26px;border-radius:50%;border:1.5px solid var(--edge-hi);display:grid;place-items:center;
  font-family:var(--font-m);font-size:10px;color:var(--faint);position:relative;background:var(--panel);
  transition:border-color .4s var(--ease),color .4s var(--ease),box-shadow .4s var(--ease)}
.pdot .tick{position:absolute;inset:0;display:grid;place-items:center;opacity:0;transform:scale(.4);transition:opacity .3s var(--ease),transform .35s var(--ease)}
.pdot .tick svg{width:11px;height:11px;stroke:var(--on-accent);stroke-width:3;fill:none}
.pnode.done .pdot{background:var(--grad);border-color:transparent;color:transparent;box-shadow:0 0 14px rgba(var(--signal-rgb),.35)}
.pnode.done .pdot .tick{opacity:1;transform:scale(1)}
.pnode.live .pdot{border-color:var(--signal);color:var(--signal);animation:livepulse 1.6s var(--ease) infinite}
@keyframes livepulse{0%,100%{box-shadow:0 0 0 0 rgba(var(--signal-rgb),.35)}50%{box-shadow:0 0 0 6px rgba(var(--signal-rgb),0)}}
.plabel{font-size:10px;color:var(--faint);letter-spacing:.1em;text-transform:uppercase;margin-left:7px;transition:color .4s var(--ease)}
.pnode.done .plabel,.pnode.live .plabel{color:var(--dim)}
.pnode.live .plabel{color:var(--signal)}
.pline{width:34px;height:1.5px;background:var(--edge-hi);margin:0 10px;position:relative;overflow:hidden}
.pline i{position:absolute;inset:0;background:var(--grad);transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pnode.done + .pline i{transform:scaleX(1)}
.pline.flow::after{content:'';position:absolute;top:-1.5px;width:10px;height:4.5px;border-radius:3px;background:var(--signal);
  filter:blur(.5px);box-shadow:0 0 8px var(--signal);animation:packet 1.1s linear infinite}
@keyframes packet{from{left:-12px}to{left:100%}}

#tour-overlay{position:fixed;inset:0;z-index:200;display:none}
#tour-spot{position:absolute;border-radius:10px;box-shadow:0 0 0 9999px rgba(4,4,10,.82);
  border:1.5px solid var(--signal);transition:top .35s var(--ease),left .35s var(--ease),width .35s var(--ease),height .35s var(--ease);pointer-events:none}
#tour-card{position:absolute;width:300px;background:var(--panel);border:1px solid var(--edge-hi);border-radius:12px;
  padding:18px;box-shadow:0 12px 40px rgba(0,0,0,.6);transition:top .35s var(--ease),left .35s var(--ease)}

body.reduce-motion *, body.reduce-motion *::before, body.reduce-motion *::after{
  animation-duration:.001ms!important;animation-delay:0s!important;animation-iteration-count:1!important;
  transition-duration:.001ms!important;transition-delay:0s!important;scroll-behavior:auto!important}

body.high-contrast{
  --ink:#FFFFFF; --dim:#C7C9DC; --faint:#8A8DB0;
  --edge:#4A4D70; --edge-hi:#7276A8; --panel:#0A0A14; --panel-2:#14152A}
body.high-contrast .card, body.high-contrast .field, body.high-contrast .btn{border-width:1.5px}

body.colorblind-safe{
  --ok:#0072B2; --warn:#E69F00; --bad:#D55E00;
  --ok-tint-bd:rgba(0,114,178,.3); --ok-tint-bg:rgba(0,114,178,.07);
  --warn-tint-bd:rgba(230,159,0,.3); --warn-tint-bg:rgba(230,159,0,.07);
}
body.colorblind-safe .badge.ok i, body.colorblind-safe .chip.g i{border-radius:50%}
body.colorblind-safe .badge.wn i, body.colorblind-safe .chip.w i{border-radius:1px;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
body.colorblind-safe .toast.err b i{border-radius:1px}

:focus-visible{outline:2px solid var(--signal)!important;outline-offset:2px}

.screens{flex:1;position:relative;overflow:hidden}
.screen{position:absolute;inset:0;padding:26px 28px 32px;overflow-y:auto;
  opacity:0;pointer-events:none;transform:translateY(10px);transition:opacity .28s var(--ease),transform .28s var(--ease)}
.screen.on{opacity:1;pointer-events:auto;transform:none}
.screen::-webkit-scrollbar{width:9px}
.screen::-webkit-scrollbar-thumb{background:var(--edge);border-radius:5px;border:2px solid var(--void)}
.screen.on .rise{animation:rise .5s var(--ease) both}
.screen.on .rise:nth-child(2){animation-delay:.05s}
.screen.on .rise:nth-child(3){animation-delay:.1s}
.screen.on .rise:nth-child(4){animation-delay:.15s}
@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}

.card{background:var(--panel);border:1px solid var(--edge);border-radius:var(--r);transition:border-color .2s var(--ease)}
.card:hover{border-color:var(--edge-hi)}
.build-cta{position:relative;border-color:rgba(var(--signal-rgb),.35);background:linear-gradient(180deg,rgba(var(--signal-rgb),.06),rgba(var(--signal-2-rgb),.03));
  transition:transform .18s var(--ease),border-color .18s var(--ease),box-shadow .18s var(--ease)}
.build-cta:hover{border-color:var(--signal);transform:translateY(-2px);box-shadow:0 10px 30px rgba(var(--signal-rgb),.18)}
.build-cta:hover .build-cta-arrow{transform:translateX(3px)}
.build-cta-arrow{transition:transform .18s var(--ease)}
.card-h{padding:14px 18px 0}
.eyebrow{font-family:var(--font-m);font-size:9.5px;letter-spacing:.16em;color:var(--faint);text-transform:uppercase}
.card-t{font-family:var(--font-d);font-weight:600;font-size:15px;margin-top:3px}
.card-b{padding:16px 18px 18px}
.lbl{font-size:11.5px;color:var(--dim);margin:0 0 5px;display:block}
.field{width:100%;background:var(--panel-2);border:1px solid var(--edge);border-radius:var(--r-sm);
  padding:9px 12px;font-size:12.5px;outline:none;transition:border-color .18s var(--ease),box-shadow .18s var(--ease)}
.field:hover{border-color:var(--edge-hi)}
.field:focus{border-color:var(--signal);box-shadow:0 0 0 3px rgba(var(--signal-rgb),.16),0 0 18px rgba(var(--signal-rgb),.10)}
.field.mono{font-family:var(--font-m);font-size:11.5px}
.hint{font-size:10.5px;color:var(--faint);margin-top:5px}
.row{display:grid;gap:14px}
.row.c2{grid-template-columns:1fr 1fr}
.mt{margin-top:14px}

.btn{display:inline-flex;align-items:center;gap:8px;padding:9px 16px;border-radius:var(--r-sm);
  background:var(--panel-2);border:1px solid var(--edge);color:var(--dim);font-size:12.5px;font-weight:500;transition:all .16s var(--ease)}
.btn:hover{color:var(--ink);border-color:var(--edge-hi);transform:translateY(-1px)}
.btn:active{transform:translateY(0) scale(.98)}
.btn.primary{background:var(--grad);border:none;color:var(--on-accent);font-weight:600;box-shadow:0 2px 14px rgba(var(--signal-rgb),.25)}
.btn.primary:hover{box-shadow:0 4px 22px rgba(var(--signal-rgb),.4);filter:brightness(1.06)}
.btn.big{padding:12px 26px;font-size:13.5px;border-radius:9px}
.btn.ghost{background:transparent}
.btn.danger{background:transparent;border-color:#4a1a1a;color:#cc6666}
.btn.sm{padding:6px 13px;font-size:11.5px}
.btn:disabled{opacity:.4;cursor:default;pointer-events:none}

.seg{position:relative;display:inline-flex;background:var(--panel-2);border:1px solid var(--edge);border-radius:9px;padding:3px;gap:2px}
.seg button{position:relative;z-index:1;padding:7px 16px;border-radius:6px;font-size:12px;font-weight:500;color:var(--dim);transition:color .2s var(--ease);white-space:nowrap}
.seg button.on{color:var(--ink)}
.seg .thumb{position:absolute;top:3px;bottom:3px;border-radius:6px;background:var(--void);border:1px solid var(--edge-hi);
  box-shadow:0 1px 6px rgba(0,0,0,.4);transition:left .22s var(--ease),width .22s var(--ease)}
.seg.accent .thumb{background:linear-gradient(135deg,rgba(var(--signal-rgb),.16),rgba(var(--signal-2-rgb),.16));border-color:rgba(var(--signal-rgb),.4)}
.seg.accent button.on{color:var(--signal)}

.drop{border:1.5px dashed var(--edge-hi);border-radius:var(--r);padding:30px 20px;text-align:center;transition:all .2s var(--ease);cursor:pointer;position:relative;overflow:hidden}
.drop:hover{border-color:var(--signal);background:rgba(var(--signal-rgb),.035)}
.drop:hover .drop-ico{transform:translateY(-3px);color:var(--signal)}
.drop-ico{color:var(--faint);transition:all .25s var(--ease);margin-bottom:8px}
.drop-ico svg{width:30px;height:30px}
.drop b{display:block;font-family:var(--font-d);font-weight:600;font-size:14px}
.drop span{font-size:11.5px;color:var(--dim)}

.chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}
.chip{display:inline-flex;align-items:center;gap:6px;background:var(--panel-2);border:1px solid var(--edge);
  border-radius:20px;padding:4px 11px;font-family:var(--font-m);font-size:10.5px;color:var(--dim);animation:chipin .4s var(--ease) both}
.chip:nth-child(2){animation-delay:.06s}.chip:nth-child(3){animation-delay:.12s}.chip:nth-child(4){animation-delay:.18s}
@keyframes chipin{from{opacity:0;transform:scale(.85)}to{opacity:1;transform:none}}
.chip i{width:6px;height:6px;border-radius:50%;background:var(--signal)}
.chip.g i{background:var(--ok)} .chip.w i{background:var(--warn)}
.chip.has-detail{cursor:pointer} .chip.has-detail:hover,.chip.has-detail:focus-visible{border-color:var(--signal);color:var(--ink);outline:none}
.chip-pop{position:fixed;z-index:60;max-width:330px;padding:10px 12px;border-radius:var(--r-sm);background:var(--panel);border:1px solid var(--edge);
  box-shadow:0 10px 30px rgba(0,0,0,.45);font-size:12px;line-height:1.5;color:var(--ink)}
.chip-pop .btn{margin-top:8px}

.tgl{position:relative;width:36px;height:20px;border-radius:20px;background:var(--panel-2);border:1px solid var(--edge);transition:all .2s var(--ease);flex-shrink:0}
.tgl::after{content:'';position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:var(--dim);transition:all .22s var(--ease)}
.tgl.on{background:rgba(var(--signal-rgb),.2);border-color:rgba(var(--signal-rgb),.5)}
.tgl.on::after{left:18px;background:var(--signal);box-shadow:0 0 8px rgba(var(--signal-rgb),.6)}
.tgl:disabled{opacity:.4;cursor:not-allowed}
.tglrow{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 0}
.tglrow + .tglrow{border-top:1px solid var(--edge)}
.tglrow b{font-weight:500;font-size:12.5px;display:block}
.tglrow small{color:var(--faint);font-size:10.5px}

.buildbar{border-top:1px solid var(--edge);background:rgba(13,14,26,.85);backdrop-filter:blur(10px);padding:14px 28px;display:flex;align-items:center;gap:18px;flex-shrink:0}
.summary{font-family:var(--font-m);font-size:11px;color:var(--dim);flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.summary b{color:var(--signal);font-weight:500}
.summary .sep{color:var(--faint);margin:0 7px}

.fleet{width:100%;border-collapse:collapse}
.fleet th{font-family:var(--font-m);font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--faint);text-align:left;padding:0 14px 10px;font-weight:400}
.fleet td{padding:13px 14px;border-top:1px solid var(--edge);font-size:12.5px}
.fleet tr.r{transition:background .15s var(--ease)}
.fleet tr.r:hover{background:rgba(var(--signal-rgb),.04)}
.fleet .mono{font-family:var(--font-m);font-size:11px;color:var(--dim)}
.badge{display:inline-flex;align-items:center;gap:6px;white-space:nowrap;font-size:10.5px;font-family:var(--font-m);padding:3px 10px;border-radius:20px;border:1px solid}
.badge.ok{color:var(--ok);border-color:var(--ok-tint-bd);background:var(--ok-tint-bg)}
.badge.wn{color:var(--warn);border-color:var(--warn-tint-bd);background:var(--warn-tint-bg)}
.badge i{width:5px;height:5px;border-radius:50%;background:currentColor}

.phase{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--edge);color:var(--faint);transition:color .3s var(--ease)}
.phase:last-child{border-bottom:none}
.phase .pi{width:20px;height:20px;border-radius:50%;border:1.5px solid var(--edge-hi);display:grid;place-items:center;flex-shrink:0;transition:all .3s var(--ease)}
.phase .pi svg{width:9px;height:9px;stroke:var(--on-accent);stroke-width:3.5;fill:none;opacity:0;transform:scale(.4);transition:all .25s var(--ease)}
.phase.doing{color:var(--ink)}
.phase.doing .pi{border-color:var(--signal)}
.phase.doing .pi::after{content:'';width:8px;height:8px;border-radius:50%;background:var(--signal);animation:livepulse 1.4s infinite}
.phase.did{color:var(--dim)}
.phase.did .pi{background:var(--grad);border-color:transparent}
.phase.did .pi svg{opacity:1;transform:scale(1)}
.log{background:#05050B;border:1px solid var(--edge);border-radius:var(--r-sm);font-family:var(--font-m);font-size:11px;line-height:1.75;padding:14px 16px;height:260px;overflow-y:auto}
.log div{opacity:0;animation:logline .3s var(--ease) forwards}
@keyframes logline{from{opacity:0;transform:translateX(-6px)}to{opacity:1;transform:none}}
.log .t{color:var(--faint);margin-right:10px}
.log .ok{color:var(--ok)} .log .in{color:var(--dim)} .log .ac{color:var(--signal)} .log .wr{color:var(--warn)}
.log::-webkit-scrollbar{width:8px}.log::-webkit-scrollbar-thumb{background:var(--edge);border-radius:4px}

.pbar{height:5px;border-radius:3px;background:var(--panel-2);overflow:hidden;position:relative}
.pbar i{display:block;height:100%;width:0;border-radius:3px;background:var(--grad);transition:width .5s var(--ease);position:relative;overflow:hidden}
.pbar i::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);animation:shimmer 1.4s linear infinite}
@keyframes shimmer{from{transform:translateX(-100%)}to{transform:translateX(100%)}}

.done-ring{width:76px;height:76px;margin:0 auto 18px;position:relative}
.done-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.done-ring .rg{fill:none;stroke:var(--edge);stroke-width:3}
.done-ring .rp{fill:none;stroke:url(#gradstroke);stroke-width:3;stroke-linecap:round;stroke-dasharray:213;stroke-dashoffset:213;animation:ring .8s var(--ease) .1s forwards}
@keyframes ring{to{stroke-dashoffset:0}}
.done-ring .chk{position:absolute;inset:0;display:grid;place-items:center}
.done-ring .chk svg{width:30px;height:30px;transform:none;stroke:var(--ok);stroke-width:2.5;fill:none;stroke-dasharray:30;stroke-dashoffset:30;animation:ring .45s var(--ease) .75s forwards}
.sheet{background:var(--panel-2);border:1px solid var(--edge);border-radius:var(--r-sm);font-family:var(--font-m);font-size:11px}
.sheet .srow{display:flex;align-items:center;gap:12px;padding:10px 14px;border-bottom:1px solid var(--edge)}
.sheet .srow:last-child{border-bottom:none}
.sheet .sk{color:var(--faint);width:110px;flex-shrink:0;font-size:10px;letter-spacing:.08em;text-transform:uppercase}
.sheet .sv{color:var(--ink);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sheet .sv.wrap{white-space:normal;line-height:1.45}
.copybtn{color:var(--faint);padding:4px;border-radius:5px;transition:all .15s var(--ease);flex-shrink:0}
.copybtn:hover{color:var(--signal);background:rgba(var(--signal-rgb),.1)}
.copybtn svg{width:13px;height:13px;display:block}

.toasts{position:fixed;bottom:22px;right:22px;display:flex;flex-direction:column;gap:10px;z-index:100}
.toast{background:var(--panel-2);border:1px solid var(--edge-hi);border-radius:9px;padding:12px 16px;min-width:280px;
  box-shadow:0 8px 32px rgba(0,0,0,.5);position:relative;overflow:hidden;animation:toastin .38s var(--ease)}
.toast.out{animation:toastout .3s var(--ease) forwards}
@keyframes toastin{from{opacity:0;transform:translateX(30px) scale(.96)}to{opacity:1;transform:none}}
@keyframes toastout{to{opacity:0;transform:translateX(30px) scale(.96)}}
.toast b{font-size:12.5px;font-weight:600;display:flex;align-items:center;gap:8px}
.toast b i{width:7px;height:7px;border-radius:50%;background:var(--ok);box-shadow:0 0 8px var(--ok)}
.toast.err b i{background:var(--bad);box-shadow:0 0 8px var(--bad)}
.toast p{font-size:11.5px;color:var(--dim);margin-top:3px}
.toast .life{position:absolute;bottom:0;left:0;height:2px;background:var(--grad);animation:life 4s linear forwards}
@keyframes life{from{width:100%}to{width:0}}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
#screen-build{padding-top:16px;padding-bottom:16px}
#screen-build .card-h{padding:8px 18px 0}
#screen-build .card-b{padding:9px 18px 11px}
#screen-build .hint{margin-top:4px}
#screen-build .tglrow{padding:7px 0}
#bp-disclosure{display:flex;align-items:center;gap:6px;margin-top:8px;padding-top:8px;border-top:1px solid var(--edge);cursor:pointer;user-select:none;background:none;border-left:none;border-right:none;border-bottom:none;width:100%;text-align:left;color:var(--ink);font:inherit}
#bp-disclosure svg{width:12px;height:12px;transition:transform .15s var(--ease);flex-shrink:0}
#bp-disclosure.open svg{transform:rotate(90deg)}
#bp-disclosure.tour-click-sim{animation:tourClickSim .42s var(--ease)}
@keyframes tourClickSim{0%{box-shadow:0 0 0 0 rgba(var(--signal-rgb),.55)}30%{transform:scale(.96);box-shadow:0 0 0 6px rgba(var(--signal-rgb),.28)}100%{transform:scale(1);box-shadow:0 0 0 0 rgba(var(--signal-rgb),0)}}

/* Graphite with one ultramarine accent: actions and the current item only; amber, green and red mean status. */
body{font-size:13px}
body::before{display:none}
.rail{background:var(--panel)}
.logo{background:var(--ink);box-shadow:none;border-radius:7px}
.nav-btn{border-radius:7px;position:relative}
.nav-btn:hover{transform:none}
.nav-btn.on{background:var(--select);color:var(--ink)}
.nav-btn.on::before{left:-11px;top:8px;bottom:8px;width:2px;border-radius:0;background:var(--signal)}
.nav-num{position:absolute;right:3px;bottom:1px;font:500 9px var(--font-m);color:var(--faint)}
.topbar{height:52px;gap:20px;padding:0 20px}
.crumb{font-size:13.5px;letter-spacing:-.01em}
.pdot{width:18px;height:18px;font:500 10px var(--font-m);border-width:1px}
.plabel{font:11.5px var(--font-m);letter-spacing:0;text-transform:none;color:var(--faint)}
.pnode.done .plabel,.pnode.live .plabel{color:var(--ink)}
.pline{width:22px;height:1px}
.card{box-shadow:none}
.eyebrow{letter-spacing:.06em}
.btn{border-radius:6px}
.btn.primary{background:var(--signal);color:var(--on-accent);box-shadow:none}
.btn.primary:hover{box-shadow:none;filter:brightness(1.08)}
.chip,.badge{border-radius:4px}
.tgl.on{background:var(--signal);border-color:var(--signal)}
.tgl.on::after{background:#fff}
.seg .thumb{background:var(--select);border-color:var(--signal)}
.buildbar{background:var(--panel);backdrop-filter:none;padding:12px 24px}
kbd{display:inline-flex;align-items:center;font:500 10.5px var(--font-m);color:var(--dim);padding:0 5px;border:1px solid var(--edge-hi);border-bottom-width:2px;border-radius:4px;background:var(--panel-2)}
.btn.primary kbd{color:#fff;border-color:rgba(0,0,0,.25);background:rgba(0,0,0,.2);margin-left:8px}
.statusbar{height:28px;flex-shrink:0;border-top:1px solid var(--edge);display:flex;align-items:center;gap:18px;padding:0 20px;font:11px var(--font-m);color:var(--faint)}
.statusbar .dot{color:var(--ok)} .statusbar .dot.off{color:var(--faint)} .statusbar .grow{flex:1}
/* Builder: a dense settings sheet on the left, the live manifest on the right. */
#screen-build{padding:0}
.builder{display:grid;grid-template-columns:minmax(560px,700px) minmax(0,1fr);min-height:100%}
.sheet-col{border-right:1px solid var(--edge);padding:18px 24px 24px;display:flex;flex-direction:column;gap:18px}
.bsec{display:flex;flex-direction:column}
.bsec-h{display:flex;align-items:center;gap:10px;margin-bottom:8px;min-height:28px}
.bsec-n{font:500 11px var(--font-m);color:var(--signal-2)}
.bsec-t{font-weight:600}
.bsec-rule{flex:1;height:1px;background:var(--edge)}
.brow{display:grid;grid-template-columns:150px minmax(0,1fr) 96px;align-items:center;gap:12px;min-height:40px;border-bottom:1px solid var(--rule)}
.brow:last-child{border-bottom:0}
.brow>label,.brow>.blbl{color:var(--dim)}
.brow .field{height:30px;padding:0 10px;font-size:12.5px}
.bsrc{font:11px var(--font-m);color:var(--faint);text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bnote{font-size:12px;color:var(--faint)}
#screen-build.printer .app-only{display:none}
.seg-sm button{padding:5px 12px;font-size:12px}
.linkbtn{background:none;border:0;padding:0;color:var(--signal-2);font:12px var(--font-b);cursor:pointer}
.linkbtn:hover{text-decoration:underline}
.filecard{display:flex;align-items:center;gap:14px;padding:12px 14px;border:1px solid var(--edge);border-radius:8px;background:var(--panel)}
.filecard-ext{width:38px;height:38px;border-radius:6px;border:1px solid var(--edge-hi);display:grid;place-items:center;font:500 10px var(--font-m);color:var(--dim)}
.filecard-name{font-weight:600}
.filecard-sub{font-size:11.5px;color:var(--dim)}
.drop{padding:22px 16px}
.detect{display:flex;align-items:center;border:1px solid var(--edge-hi);border-radius:6px;overflow:hidden;width:max-content}
.detect button{height:28px;padding:0 12px;border:0;background:transparent;color:var(--dim);font:12px var(--font-b);cursor:pointer}
.detect button.on{background:var(--select);color:var(--ink)}
.detect-ge{padding:0 4px 0 10px;border-left:1px solid var(--edge-hi);color:var(--dim);font-family:var(--font-m)}
.detect .field{border:0;background:transparent;height:28px;width:130px;padding:0 8px}
.detect.min .detect-ge,.detect.min .field{background:var(--select);color:var(--ink)}
.procs{font:12px var(--font-m);display:flex;gap:6px;flex-wrap:wrap}
.procs .proc{padding:2px 8px;border-radius:4px;background:var(--panel-2);border:1px solid var(--edge)}
.extras-sum{display:flex;gap:16px;font-size:12px;color:var(--dim)} .extras-sum b{color:var(--ink);font-weight:500}
.extras{padding:6px 0 10px 162px;border-bottom:1px solid var(--rule)}
.scripts{display:grid;grid-template-columns:110px minmax(0,1fr) auto;gap:6px 8px;align-items:center;margin-top:8px}
.scripts label{color:var(--dim);font-size:12px} .scripts .field{height:28px;font-size:12px}
.wrap-profile{padding-top:6px}
.manifest-col{padding:18px 24px 24px;display:flex;flex-direction:column;gap:10px;min-width:0}
.mhead{display:flex;align-items:baseline;gap:10px} .mhead span{font-size:11.5px;color:var(--faint)}
.manifest{border:1px solid var(--edge);border-radius:8px;background:var(--panel);padding:12px 0;font-size:12.5px;line-height:1.75;overflow-x:auto}
.mline{display:grid;grid-template-columns:44px 112px minmax(0,1fr);padding-right:16px}
.mline .n{color:#4A4C52;text-align:right;padding-right:16px} .mline .k{color:var(--dim)} .mline .v{color:var(--ink);overflow-wrap:anywhere}
.mline .v.str{color:var(--code-str)} .mline .v.num{color:var(--signal-2)} .mline .v.dim{color:var(--faint)}
.check{display:grid;grid-template-columns:16px minmax(0,1fr);gap:8px;padding:9px 12px;border:1px solid var(--edge);border-radius:7px;background:var(--panel);margin-bottom:6px;font-size:12.5px}
.check .g{font-size:11px;line-height:1.7} .check.red .g{color:var(--bad)} .check.amber .g{color:var(--warn)} .check.ok .g{color:var(--ok)}
.check b{font-weight:600} .check span.t{color:var(--dim)}
#cmdk{position:fixed;inset:0;z-index:400;background:rgba(0,0,0,.55);display:flex;align-items:flex-start;justify-content:center;padding-top:14vh}
#cmdk[hidden]{display:none}
#cmdk .box{width:min(620px,92vw);background:var(--panel);border:1px solid var(--edge-hi);border-radius:10px;box-shadow:0 24px 60px rgba(0,0,0,.6);overflow:hidden}
#cmdk input{width:100%;border:0;border-bottom:1px solid var(--edge);background:transparent;color:var(--ink);font:14px var(--font-b);padding:14px 16px;outline:none}
#cmdk ul{list-style:none;margin:0;padding:6px;max-height:50vh;overflow:auto}
#cmdk li{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:6px;cursor:pointer;color:var(--dim)}
#cmdk li .grp{font:10.5px var(--font-m);color:var(--faint);width:64px}
#cmdk li b{font-weight:500;color:var(--ink);flex:1}
#cmdk li.sel{background:var(--select)}
#cmdk .foot{display:flex;gap:14px;padding:8px 14px;border-top:1px solid var(--edge);font:11px var(--font-m);color:var(--faint)}
.cmd-btn{display:flex;align-items:center;gap:8px;height:30px;padding:0 10px;border-radius:6px;border:1px solid var(--edge);background:var(--panel);color:var(--dim);font:12px var(--font-b);cursor:pointer;margin-left:auto}
</style>
</head>
<body>
<svg width="0" height="0"><defs><linearGradient id="gradstroke" x1="0" y1="0" x2="1" y2="1">
<stop offset="0" stop-color="#5EA2FF"/><stop offset="1" stop-color="#8B7CFF"/></linearGradient></defs></svg>

<div class="app">
  <nav class="rail">
    <div class="logo" title="AppUpdater"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" style="stroke:var(--on-accent)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12a8 8 0 0 1 14-5.2M20 12a8 8 0 0 1-14 5.2"/><path d="M17.5 4.5v3h-3M6.5 19.5v-3h3"/></svg></div>
    <button class="nav-btn on" data-go="home"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 12l9-8 9 8M5 10v10h5v-6h4v6h5V10"/></svg><span class="nav-tip">Home</span></button>
    <button class="nav-btn" data-go="build"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><path d="M3.3 7l8.7 5 8.7-5M12 22V12"/></svg><span class="nav-tip">Package builder</span></button>
    <button class="nav-btn" data-go="fleet"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.3"/><path d="M13 5h8M13 8.5h8M3 15h18M3 18.5h12"/></svg><span class="nav-tip">App fleet</span></button>
    <button class="nav-btn" data-go="profiles"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.5"/><rect x="14" y="4" width="7" height="7" rx="1.5"/><rect x="3" y="15" width="7" height="7" rx="1.5"/><rect x="14" y="15" width="7" height="7" rx="1.5"/></svg><span class="nav-tip">Client profiles</span></button>
    <button class="nav-btn" data-go="history"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 3v5h5"/><path d="M3.05 13a9 9 0 1 0 2.13-7.83L3 8"/><path d="M12 7v5l4 2"/></svg><span class="nav-tip">History</span></button>
    <button class="nav-btn" data-go="worker"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg><span class="nav-tip">Worker &amp; settings</span></button>
    <div class="spacer"></div>
    <button class="nav-btn" data-go="accessibility" title="Accessibility"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="4" r="1.6" fill="currentColor" stroke="none"/><path d="M5 8.5c3.5 1 10.5 1 14 0M12 6v6l-3 8M12 12l3 8"/></svg><span class="nav-tip">Accessibility</span></button>
    <button class="nav-btn" data-go="docs" title="Docs &amp; help"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 1.5-2.5 1.8-2.5 3.5"/><circle cx="12" cy="17" r=".6" fill="currentColor" stroke="none"/></svg><span class="nav-tip">Docs &amp; help</span></button>
  </nav>

  <div class="stage">
    <div class="topbar" id="drag-region" style="cursor:move">
      <div class="crumb" id="crumb">AppUpdater</div>
      <div class="pipe" id="pipe" style="display:none"></div>
      <button type="button" class="cmd-btn" id="cmd-open">Search or run a command <kbd>Ctrl K</kbd></button>
      <div style="display:flex;align-items:center;gap:4px;margin-left:12px">
        <button id="win-minimize" title="Minimize" style="width:30px;height:26px;border-radius:6px;display:grid;place-items:center;color:var(--dim);background:none;border:none;cursor:pointer">
          <svg viewBox="0 0 12 12" width="11" height="11"><rect x="1" y="5.5" width="10" height="1.2" fill="currentColor"/></svg>
        </button>
        <button id="win-close" title="Close" style="width:30px;height:26px;border-radius:6px;display:grid;place-items:center;color:var(--dim);background:none;border:none;cursor:pointer">
          <svg viewBox="0 0 12 12" width="11" height="11" stroke="currentColor" stroke-width="1.3"><path d="M1.5 1.5l9 9M10.5 1.5l-9 9"/></svg>
        </button>
      </div>
    </div>

    <div class="screens" id="screens">

      <!-- ========== HOME ========== -->
      <section class="screen on" data-screen="home" id="screen-home">
        <div style="max-width:1240px;margin:0 auto;padding-bottom:20px">
          <div class="rise" style="margin:20px 0 16px">
            <div class="eyebrow">packaging console</div>
            <h1 style="font-family:var(--font-d);font-weight:700;font-size:28px;letter-spacing:-.01em;margin-top:4px">Good afternoon.</h1>
            <p style="color:var(--dim);margin-top:4px;font-size:13px" id="fleet-summary">Loading fleet&hellip;</p>
          </div>

          <div class="rise" id="home-stats" style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px">
            <div class="card" style="padding:11px 14px">
              <div class="eyebrow">apps tracked</div>
              <div style="font-family:var(--font-d);font-weight:700;font-size:22px;margin-top:3px" id="stat-total">0</div>
            </div>
            <div class="card" style="padding:11px 14px">
              <div class="eyebrow">deployed</div>
              <div style="font-family:var(--font-d);font-weight:700;font-size:22px;margin-top:3px;color:var(--ok)" id="stat-deployed">0</div>
            </div>
            <div class="card" style="padding:11px 14px">
              <div class="eyebrow">updates available</div>
              <div style="font-family:var(--font-d);font-weight:700;font-size:22px;margin-top:3px;color:var(--warn)" id="stat-updates">0</div>
            </div>
            <div class="card" style="padding:11px 14px">
              <div class="eyebrow">not yet deployed</div>
              <div style="font-family:var(--font-d);font-weight:700;font-size:22px;margin-top:3px;color:var(--signal)" id="stat-pending">0</div>
            </div>
          </div>

          <div class="card rise" id="getting-started-card" style="display:none;padding:14px 16px;margin-bottom:12px">
            <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
              <div><div class="eyebrow">getting started</div><div class="card-t" style="margin-top:2px">A few things to try</div></div>
              <div style="display:flex;gap:8px">
                <button class="btn primary sm" id="getting-started-tour">Take the guided tour</button>
                <button class="btn ghost sm" id="getting-started-dismiss">Dismiss</button>
              </div>
            </div>
            <div id="getting-started-list"></div>
          </div>

          <div class="card rise" id="release-banner" style="display:none;padding:12px 16px;margin-bottom:14px;border-color:rgba(var(--signal-rgb),.3);background:rgba(var(--signal-rgb),.06);align-items:center;gap:10px">
            <span style="font-family:var(--font-m);font-size:12px;color:var(--signal);flex:1" id="release-banner-text"></span>
            <button class="btn sm" id="release-banner-github">View</button>
            <button class="btn ghost sm" id="release-banner-dismiss">Dismiss</button>
          </div>

          <div class="card rise" id="worker-banner" style="padding:11px 16px;display:flex;align-items:center;gap:10px;margin-bottom:10px">
            <span style="width:8px;height:8px;border-radius:50%;background:var(--faint);flex-shrink:0" id="worker-dot"></span>
            <span style="font-family:var(--font-m);font-size:12px;color:var(--dim)" id="worker-banner-text">Checking worker&hellip;</span>
          </div>

          <!-- Shown instead of the banner above when no worker is connected yet.
               Deliberately muted/greyed (not a hard block) - building packages
               works fully standalone, so this is an invitation, not a gate. -->
          <div class="card rise" id="connect-card" style="display:none;padding:14px 16px;margin-bottom:12px;opacity:.72;transition:opacity .2s var(--ease)">
            <div style="display:flex;align-items:center;gap:14px">
              <div style="width:40px;height:40px;border-radius:10px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--faint)">
                <svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M4 12a8 8 0 0 1 14-5.2M20 12a8 8 0 0 1-14 5.2"/><path d="M17.5 4.5v3h-3M6.5 19.5v-3h3"/></svg>
              </div>
              <div style="flex:1">
                <div style="font-family:var(--font-d);font-weight:600;font-size:14.5px;color:var(--dim)">Not connected to Cloudflare</div>
                <div style="font-size:12px;color:var(--faint);margin-top:2px">Building packages works fine without this. Connecting adds: a live fleet view that updates as devices check in, automatic update checks so you're not rebuilding manually, and a password-protected status page you can check from anywhere.</div>
              </div>
              <button class="btn sm" id="connect-preview-btn">See what it does</button>
              <button class="btn primary sm" id="connect-btn">Connect</button>
              <button class="btn ghost sm" id="connect-card-dismiss" title="Hide this - bring it back any time from Worker &amp; settings">Dismiss</button>
            </div>

            <div id="connect-demo" style="display:none;margin-top:16px;padding-top:16px;border-top:1px solid var(--edge)">
              <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">
                <span style="width:7px;height:7px;border-radius:50%;background:var(--ok);animation:livepulse 1.6s infinite"></span>
                <span style="font-family:var(--font-m);font-size:10.5px;color:var(--dim)">preview - your fleet dashboard once connected</span>
              </div>
              <div style="background:var(--panel-2);border:1px solid var(--edge);border-radius:8px;padding:14px 16px;font-family:var(--font-m);font-size:11px">
                <div class="demo-row" style="display:flex;align-items:center;gap:10px;padding:6px 0;animation:rise .4s var(--ease) both">
                  <span class="badge ok" style="animation:livepulse 2s infinite"><i></i>online</span>
                  <span style="color:var(--ink);flex:1">VLC media player</span>
                  <span style="color:var(--faint)">3.0.20 &#8594; 3.0.21</span>
                </div>
                <div class="demo-row" style="display:flex;align-items:center;gap:10px;padding:6px 0;animation:rise .4s var(--ease) .08s both">
                  <span class="badge ok"><i></i>online</span>
                  <span style="color:var(--ink);flex:1">7-Zip</span>
                  <span style="color:var(--faint)">up to date</span>
                </div>
                <div class="demo-row" style="display:flex;align-items:center;gap:10px;padding:6px 0;animation:rise .4s var(--ease) .16s both">
                  <span class="badge wn"><i></i>checking</span>
                  <span style="color:var(--ink);flex:1">Notepad++</span>
                  <span style="color:var(--faint)">last seen 4m ago</span>
                </div>
              </div>
              <div class="hint" style="margin-top:10px">Live, updates automatically as devices check in - password-protected, only you can see it.</div>
            </div>
          </div>

          <div class="card rise build-cta" id="home-build-cta" style="cursor:pointer" data-go="build" role="button" tabindex="0">
            <div class="card-b" style="display:flex;align-items:center;gap:18px;padding:22px 24px">
              <div style="width:58px;height:58px;border-radius:14px;background:var(--grad);display:grid;place-items:center;flex-shrink:0;box-shadow:0 0 30px rgba(var(--signal-rgb),.45)">
                <svg viewBox="0 0 24 24" width="28" height="28" fill="none" style="stroke:var(--on-accent)" stroke-width="2"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>
              </div>
              <div>
                <div class="eyebrow">start here</div>
                <div style="font-family:var(--font-d);font-weight:700;font-size:19px;margin-top:2px">Build app package</div>
                <div style="color:var(--dim);font-size:12.5px;margin-top:3px">Drop an installer, pick a profile, ship it.</div>
              </div>
              <div class="build-cta-arrow" style="margin-left:auto;color:var(--signal);font-size:26px">&#8250;</div>
            </div>
          </div>

          <div class="rise" style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:12px">
            <div class="card">
              <div class="card-h" style="display:flex;align-items:baseline;justify-content:space-between">
                <div><div class="eyebrow">activity</div><div class="card-t">Recent history</div></div>
                <button class="btn ghost" data-go="history" style="font-size:11.5px">View all &#8250;</button>
              </div>
              <div class="card-b" style="padding-top:10px" id="home-recent-activity">
                <p class="hint" style="margin:0">Nothing yet - build, deploy, or remove an app to see activity here.</p>
              </div>
            </div>
            <div class="card" id="deploy-feedback" style="display:none;margin-bottom:16px">
              <div class="card-h"><div class="eyebrow">since last time</div><div class="card-t">Did these install correctly on devices?</div></div>
              <div class="card-b" style="padding-top:10px" id="deploy-feedback-list"></div>
            </div>
            <div class="card">
              <div class="card-h" style="display:flex;align-items:baseline;justify-content:space-between">
                <div><div class="eyebrow">fleet</div><div class="card-t">Tracked in local manifest</div></div>
                <button class="btn ghost" data-go="fleet" style="font-size:11.5px">View all &#8250;</button>
              </div>
              <div class="card-b" style="padding-top:10px">
                <table class="fleet" id="home-fleet-table"></table>
              </div>
            </div>
          </div>
        </div>
      </section>

      <!-- ========== BUILDER ========== -->
      <section class="screen" data-screen="build" id="screen-build">
        <div class="builder">
          <div class="sheet-col">
            <div class="bsec" id="sec-source">
              <div class="bsec-h"><span class="bsec-n">01</span><span class="bsec-t">Source</span><span class="bsec-rule"></span>
                <div class="seg seg-sm" id="segKind"><div class="thumb"></div><button class="on" data-val="app">App</button><button data-val="printer">Printer</button></div>
              </div>
              <div class="hint" id="kindHint" hidden></div>
              <div id="app-source-card">
                <div class="drop" id="drop">
                  <div class="drop-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg></div>
                  <b>Drop an installer here</b>
                  <span>or click to browse &middot; exe, msi, msix, appx, zip &middot; <kbd>Ctrl O</kbd></span>
                </div>
                <div id="inspect" style="display:none">
                  <div class="filecard">
                    <div class="filecard-ext" id="inspect-ext">EXE</div>
                    <div style="flex:1;min-width:0">
                      <div class="filecard-name" id="inspect-name">&nbsp;</div>
                      <div class="filecard-sub mono" id="inspect-sub">&nbsp;</div>
                    </div>
                    <button class="btn sm" id="reDrop">Change</button>
                  </div>
                  <div class="chips" id="inspect-chips"></div>
                </div>
              </div>
              <div id="printer-source-card" style="display:none">

                  <label class="lbl">Printer name</label>
                  <input class="field" id="f-printername" placeholder="Finance-3F-HP4200">
                  <label class="lbl" style="margin-top:10px">Driver</label>
                  <select class="field" id="f-driverid"><option value="">&mdash; none, use path below &mdash;</option></select>
                  <div style="margin-top:8px;display:none" id="driver-model-row">
                    <label class="lbl">Model</label>
                    <select class="field" id="f-drivermodel"></select>
                    <div class="hint">This driver package covers multiple printer models — pick the one being deployed.</div>
                  </div>
                  <label class="lbl" style="margin-top:10px">Driver name</label>
                  <input class="field" id="f-drivername" placeholder="HP Universal Printing PCL6 (auto-filled from library, or type it for a one-off path-based driver)">
                  <div style="display:flex;align-items:center;gap:6px;margin:10px 0 6px;flex-wrap:wrap">
                    <button type="button" class="btn ghost sm" id="driver-lib-add-toggle" style="padding-left:0">+ Add driver to library</button>
                    <button type="button" class="btn ghost sm" id="driver-lib-import-builtin">Import built-in driver families</button>
                  </div>
                  <div class="hint" id="builtin-import-status" style="margin-bottom:6px"></div>
                  <div id="driver-lib-add-panel" style="display:none;margin-bottom:10px;padding:10px;border:1px solid var(--edge);border-radius:var(--r-sm)">
                    <div class="row c2">
                      <div><label class="lbl">Driver ID</label><input class="field mono" id="dl-id" placeholder="hp-universal-pcl6-x64"></div>
                      <div><label class="lbl">Display name</label><input class="field" id="dl-displayname" placeholder="HP Universal Printing PCL6"></div>
                    </div>
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">Manufacturer</label><input class="field" id="dl-manufacturer" placeholder="HP Inc."></div>
                      <div><label class="lbl">Driver type</label><input class="field" id="dl-drivertype" placeholder="PCL6"></div>
                    </div>
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">Architecture</label><input class="field" id="dl-arch" placeholder="x64"></div>
                      <div><label class="lbl">Version</label><input class="field" id="dl-version" placeholder="61.270.0.0"></div>
                    </div>
                    <label class="lbl" style="margin-top:8px">Source (https:// URL, .zip, or folder path)</label>
                    <input class="field mono" id="dl-source" placeholder="https://... or C:\Drivers\hp-pcl6.zip">
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">INF relative path</label><input class="field mono" id="dl-inf" placeholder="hpcu270u.inf"></div>
                      <div><label class="lbl">Expected publisher</label><input class="field" id="dl-publisher" placeholder="HP Inc."></div>
                    </div>
                    <label class="lbl" style="margin-top:8px">Models (one per line, optional)</label>
                    <textarea class="field mono" id="dl-models" rows="3" placeholder="Brother HL-2290&#10;Brother HL-L2350DW&#10;Brother HL-L2385DW" style="resize:vertical"></textarea>
                    <div class="hint">Leave blank for a single-model driver. Fill in when one INF/driver package covers a whole product family.</div>
                    <div style="display:flex;gap:8px;margin-top:10px">
                      <button class="btn primary sm" id="dl-save">Add to library</button>
                      <button class="btn ghost sm" id="dl-cancel">Cancel</button>
                    </div>
                    <div class="hint" id="dl-status" style="margin-top:6px"></div>
                  </div>
                  <div class="hint" id="driver-source-hint">Pick a driver from the library above, or fill in a local driver path/INF below for a one-off build not worth importing.</div>
                  <div class="row c2" style="margin-top:10px">
                    <div><label class="lbl">Driver source path</label><input class="field mono" id="f-driversourcepath" placeholder="C:\Drivers\hp-pcl6 or .zip"></div>
                    <div><label class="lbl">Driver INF (relative)</label><input class="field mono" id="f-driverinf" placeholder="hpcu270u.inf"></div>
                  </div>
                  <div><label class="lbl">Expected driver publisher</label><input class="field" id="f-driverpublisher" placeholder="HP Inc. (optional but recommended)"></div>
                  <div class="row c2" style="margin-top:10px">
                    <div><label class="lbl">Port host address</label><input class="field mono" id="f-porthost" placeholder="10.20.4.55"></div>
                    <div><label class="lbl">Port number</label><input class="field mono" id="f-portnumber" placeholder="9100"></div>
                  </div>
                  <div><label class="lbl">Location</label><input class="field" id="f-printerlocation" placeholder="3rd Floor - Finance"></div>
                  <div class="hint">Detection checks the printer actually exists with this driver and port, not just that it once ran.</div>
                
              </div>
            </div>

            <div class="bsec" id="sec-identity">
              <div class="bsec-h"><span class="bsec-n">02</span><span class="bsec-t">Identity</span><span class="bsec-rule"></span></div>
              <div class="brow"><label for="f-displayname">Display name</label><input class="field" id="f-displayname"><span class="bsrc" id="src-displayname"></span></div>
              <div class="brow"><label for="f-appid">App ID</label><input class="field mono" id="f-appid"><span class="bsrc" id="src-appid"></span></div>
              <div class="brow app-only"><label for="f-registryname">Registry name</label><input class="field mono" id="f-registryname" title="Must match Add/Remove Programs exactly; a local test suggests the right name"><span class="bsrc" id="src-registry"></span></div>
              <div class="brow app-only" id="silent-row"><label for="f-silentargs">Silent switch</label><input class="field mono" id="f-silentargs" placeholder="e.g. /S or /quiet /norestart" title="{pkg} stands for the installer's folder, e.g. /s /f1&quot;{pkg}\setup.iss&quot;"><span class="bsrc" id="src-silent"></span></div>
              <div class="brow" id="detectversion-wrap"><span class="blbl">Detection</span>
                <div class="detect"><button type="button" id="detect-any">Any version</button><span class="detect-ge">&ge;</span><input class="field mono" id="f-detectversion" placeholder="minimum version" aria-label="Minimum version for detection"></div>
                <span class="bsrc" id="src-detect"></span></div>
            </div>

            <div class="bsec" id="sec-configure">
              <div class="bsec-h"><span class="bsec-n">03</span><span class="bsec-t">Configure</span><span class="bsec-rule"></span>
                <button type="button" class="linkbtn" id="mode-explainer-toggle">What do these mean?</button>
              </div>
              <div id="mode-explainer" style="display:none;margin-bottom:10px;padding:10px;border:1px solid var(--signal);border-radius:var(--r-sm);background:rgba(var(--signal-rgb),.08)">
                    <div style="font-size:12.5px;line-height:1.6" id="mode-explainer-text"></div>
                    <button type="button" class="btn ghost sm" id="mode-explainer-dismiss" style="margin-top:8px">Got it, stop guiding me</button>
                  </div>
              <div class="brow"><span class="blbl">Delivery</span>
                <div class="seg seg-sm" id="segMode"><div class="thumb"></div><button class="on" data-val="runtime">Runtime &middot; self-updating</button><button data-val="simple">Simple</button></div>
                <span class="bsrc" id="modeHint" hidden></span></div>
              <div class="brow" id="runtime-url-row"><label for="f-download-url">Download URL</label><input class="field mono" id="f-download-url" type="url" placeholder="https://vendor.example/installer.exe"><span class="bsrc">devices fetch updates</span></div>
              <div class="brow" id="close-apps-row"><span class="blbl">Close before install</span>
                <div class="procs" id="close-apps-hint">Detected process to close on install</div>
                <button class="tgl on" data-val="closeAppsOn" aria-label="Close blocking apps"></button></div>
              <div class="brow" id="defer-row"><span class="blbl">Let users postpone</span>
                <span class="bnote">Up to 3 times; turn off when another app depends on this one</span>
                <button class="tgl on" data-val="allowDefer" aria-label="Allow deferral"></button></div>
              <div class="brow app-only"><span class="blbl">Extras</span>
                <div class="extras-sum" id="extras-summary"></div>
                <button type="button" class="linkbtn" id="extras-toggle">Edit</button></div>
              <div class="extras" id="extras-panel" hidden>
                <div class="tglrow"><div><b>Bundle the whole folder</b><small id="bundle-hint">Include every file next to the installer (Simple packages only)</small></div><button class="tgl" data-val="BundleFolder"></button></div>
                <div id="scripts-wrap">
                  <div class="tglrow"><div><b>Remove older versions first</b><small>For apps that install side by side, such as Java. Needs a minimum version.</small></div><button class="tgl" data-val="RemoveOlderVersions"></button></div>
                  <div class="scripts">
                    <label for="f-prehook">Before install</label><input class="field mono" id="f-prehook" placeholder="script.ps1"><button class="btn sm" data-browse-script="f-prehook">Browse</button>
                    <label for="f-posthook">After install</label><input class="field mono" id="f-posthook" placeholder="script.ps1"><button class="btn sm" data-browse-script="f-posthook">Browse</button>
                    <label for="f-postuninstallhook">After uninstall</label><input class="field mono" id="f-postuninstallhook" placeholder="script.ps1"><button class="btn sm" data-browse-script="f-postuninstallhook">Browse</button>
                  </div>
                </div>
              </div>
            </div>

            <div class="bsec" id="sec-wrap">
              <div class="bsec-h"><span class="bsec-n">04</span><span class="bsec-t">Wrap</span><span class="bsec-rule"></span></div>
              <div class="brow"><span class="blbl">Output</span>
                <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
                  <div class="seg seg-sm accent" id="segTarget"><div class="thumb"></div><button class="on" data-val="intunewin">.intunewin</button><button data-val="psadt">PSADT</button></div>
                  <div style="margin-top:10px;display:none" id="psadt-version-row">
                    <label class="lbl">PSADT version</label>
                    <div class="seg" id="segPsadtVersion">
                      <div class="thumb"></div>
                      <button class="on" data-val="v3">v3</button>
                      <button data-val="v4">v4</button>
                      <button data-val="both">Both</button>
                    </div>
                    <div class="hint">v4 uses the module-based PSAppDeployToolkit with Fluent dialogs; v3 is the classic frontend. "Both" exports each.</div>
                  </div>
                </div>
                <span class="bsrc" id="targetHint" hidden></span></div>
              <div class="wrap-profile">
                <label class="lbl" style="margin-top:10px">Client profile</label>
                  <select class="field" id="f-profile"><option value="">Default (uses Settings organisation name)</option></select>
                  <div class="hint" id="profile-hint" style="margin-bottom:6px">Determines the branding used for this build - manage profiles from the nav rail.</div>
                  <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">
                    <button type="button" class="btn ghost sm" id="build-new-profile" style="padding-left:0">+ New profile</button>
                    <button type="button" class="btn ghost sm" id="build-override-toggle" style="display:none">Override for this build &#9662;</button>
                  </div>
                  <div id="build-override-panel" style="display:none;margin-bottom:10px;padding:10px;border:1px solid var(--edge);border-radius:var(--r-sm)">
                    <label class="lbl">Organisation name</label>
                    <input class="field" id="ov-orgname" style="margin-bottom:8px">
                    <label class="lbl">Logo image</label>
                    <div style="display:flex;gap:8px;margin-bottom:8px">
                      <input class="field mono" id="ov-logo" readonly style="flex:1;font-size:10.5px">
                      <button class="btn sm" id="ov-logo-browse">Browse&hellip;</button>
                    </div>
                    <label class="lbl">Banner image</label>
                    <div style="display:flex;gap:8px">
                      <input class="field mono" id="ov-banner" readonly style="flex:1;font-size:10.5px">
                      <button class="btn sm" id="ov-banner-browse">Browse&hellip;</button>
                    </div>
                    <div class="hint" style="margin-top:8px">Applies to this build only - you'll be asked whether to save it back to the profile afterward.</div>
                  </div>
              </div>
            </div>
          </div>

          <aside class="manifest-col" aria-label="Package manifest">
            <div class="mhead"><b>Manifest</b><span class="mono">what ships to Intune &middot; updates as you type</span></div>
            <div class="manifest mono" id="manifest"></div>
            <div class="mhead" style="margin-top:6px"><b>Checks</b><span class="mono" id="checks-state">pick an installer</span></div>
            <div id="checks-list"></div>
            <div style="display:none;align-items:center;gap:6px;margin-top:10px" id="bp-header">
                    <button type="button" id="bp-disclosure"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 6l6 6-6 6"/></svg><span class="lbl" style="margin:0" data-version-label>Preview branding</span></button>
                    <div class="seg" id="segBpSwap" style="display:none;transform:scale(.82);transform-origin:left center;margin-left:-6px">
                      <div class="thumb"></div>
                      <button class="on" data-val="v3">v3</button>
                      <button data-val="v4">v4</button>
                    </div>
                  </div>
            <div id="bp-panel" style="display:none;margin-top:8px;padding-top:12px;border-top:1px solid var(--edge)">
                    <div class="hint" style="margin-bottom:8px">This is what the real install dialog looks like - logo goes on Fluent (v4) dialogs, banner on Classic (v3) dialogs.</div>

                    <!-- v3 Classic: real proportions from the actual PSADT banner (900x125) - white
                         WinForms dialog, banner full-width at top, Segoe UI body text below. -->
                    <div id="bp-preview-v3" style="border-radius:6px;overflow:hidden;background:#F0F0F0;border:1px solid #ACACAC;box-shadow:0 6px 20px rgba(0,0,0,.35);font-family:'Segoe UI',var(--font-b)">
                      <div id="bp-v3-banner-wrap" style="width:100%;aspect-ratio:900/125;background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden;border-bottom:1px solid #ACACAC">
                        <img id="bp-v3-banner" style="width:100%;height:100%;object-fit:cover">
                      </div>
                      <div style="padding:12px 14px;background:#F0F0F0">
                        <div style="font-weight:600;font-size:12.5px;color:#1a1a1a" id="bp-v3-title">Welcome to the this app Setup</div>
                        <div style="font-size:10.5px;color:#444;margin-top:4px">Please close the following programs before continuing:</div>
                        <div style="background:#fff;border:1px solid #ACACAC;border-radius:2px;margin-top:6px;padding:5px 8px;font-size:10px;color:#333">Microsoft Word</div>
                        <div style="display:flex;gap:6px;margin-top:10px;justify-content:flex-end">
                          <div style="background:#E1E1E1;border:1px solid #ADADAD;border-radius:2px;padding:4px 12px;font-size:10.5px;color:#1a1a1a">Close &amp; Continue</div>
                        </div>
                      </div>
                    </div>

                    <!-- v4 Fluent: iNKORE.UI.WPF.Modern - rounded card, accent button (default
                         Windows accent #0078D7 unless FluentAccentColor is set), Title+SubTitle. -->
                    <div id="bp-preview-v4" style="display:none;border-radius:12px;overflow:hidden;background:#202020;border:1px solid #3a3a3a;box-shadow:0 6px 24px rgba(0,0,0,.4);font-family:var(--font-b)">
                      <div style="padding:20px 20px 16px;display:flex;gap:14px;align-items:flex-start">
                        <div id="bp-v4-icon-wrap" style="width:44px;height:44px;border-radius:10px;overflow:hidden;flex-shrink:0;background:#2d2d2d;display:grid;place-items:center">
                          <img id="bp-v4-icon" style="width:100%;height:100%;object-fit:cover">
                        </div>
                        <div style="min-width:0">
                          <div style="font-weight:600;font-size:14px;color:#fff" id="bp-v4-title">this app</div>
                          <div style="font-size:11px;color:#a0a0a0;margin-top:2px" id="bp-v4-subtitle">Please close the following applications to continue.</div>
                        </div>
                      </div>
                      <div style="padding:0 20px 18px">
                        <div style="background:#2d2d2d;border-radius:6px;padding:8px 12px;font-size:11px;color:#ddd">Microsoft Word</div>
                        <div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end">
                          <div id="bp-v4-accent-btn" style="background:#0078D7;border-radius:5px;padding:6px 16px;font-size:11.5px;color:#fff;font-weight:600">Close apps &amp; install</div>
                        </div>
                      </div>
                    </div>

                    <div class="hint" id="bp-no-assets-hint" style="display:none;margin-top:8px">Real PSADT assets aren't cached on this machine yet - build a PSADT package once and this preview will use the actual banner/icon.</div>
                  </div>
          </aside>
        </div>
      </section>

      <!-- ========== PROGRESS ========== -->
      <section class="screen" data-screen="progress" id="screen-progress">
        <div style="max-width:760px;margin:0 auto">
          <div class="rise" style="margin:20px 0 22px;text-align:center">
            <div class="eyebrow">building</div>
            <h2 style="font-family:var(--font-d);font-weight:600;font-size:21px;margin-top:4px" id="progress-title">Package</h2>
            <div class="pbar" style="max-width:420px;margin:16px auto 0"><i id="progress-bar"></i></div>
          </div>
          <div id="progress-error" class="rise" style="display:none;margin-bottom:16px;padding:14px 16px;border-radius:var(--r);background:rgba(var(--bad-rgb),.08);border:1px solid rgba(var(--bad-rgb),.35)">
            <div style="font-weight:600;font-size:13.5px;color:var(--bad)" id="progress-error-title">Build failed</div>
            <div id="progress-error-msg" style="font-size:12.5px;color:var(--dim);margin-top:4px;line-height:1.5"></div>
            <button class="btn ghost sm" id="progress-error-back" style="margin-top:10px">Back to Build</button>
          </div>
          <div style="display:grid;grid-template-columns:260px 1fr;gap:16px" class="rise">
            <div class="card"><div class="card-b" style="padding-top:12px" id="step-list"></div></div>
            <div class="log" id="log"></div>
          </div>
        </div>
      </section>

      <!-- ========== DONE ========== -->
      <section class="screen" data-screen="done" id="screen-done">
        <div style="max-width:640px;margin:0 auto;text-align:center;padding-top:24px">
          <div class="done-ring rise">
            <svg viewBox="0 0 76 76"><circle class="rg" cx="38" cy="38" r="34"/><circle class="rp" cx="38" cy="38" r="34"/></svg>
            <div class="chk"><svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg></div>
          </div>
          <h2 class="rise" style="font-family:var(--font-d);font-weight:600;font-size:22px">Package ready</h2>
          <p class="rise" style="color:var(--dim);font-size:12.5px;margin-top:4px" id="done-path">&nbsp;</p>
          <div class="sheet rise" style="margin-top:22px;text-align:left" id="done-sheet"></div>
          <div class="rise" style="display:flex;gap:10px;justify-content:center;margin-top:22px">
            <button class="btn primary" id="done-test">Test on this machine</button>
            <button class="btn" id="done-deployed">Mark deployed</button>
            <button class="btn" data-go="fleet">View fleet</button>
            <button class="btn ghost" data-go="home">Done</button>
          </div>
        </div>
      </section>

      <!-- ========== FLEET ========== -->
      <section class="screen" data-screen="fleet" id="screen-fleet">
        <div style="max-width:1240px;margin:0 auto">
          <div class="rise" style="margin:10px 0 18px;display:flex;align-items:center;gap:14px">
            <h2 style="font-family:var(--font-d);font-weight:600;font-size:20px">App fleet</h2>
            <span id="fleet-demo-badge" style="display:none;font-family:var(--font-m);font-size:10.5px;color:var(--warn);border:1px solid rgba(var(--warn-rgb),.35);background:rgba(var(--warn-rgb),.08);padding:3px 9px;border-radius:20px">example data - tour only</span>
            <input class="field" id="fleet-filter" placeholder="Filter apps&hellip;" style="max-width:240px;padding:7px 12px">
            <button class="btn primary" style="margin-left:auto" data-go="build">New package</button>
          </div>
          <div class="card rise"><div class="card-b" style="padding-top:6px">
            <div id="fleet-bulk-bar" style="display:none;align-items:center;gap:12px;padding:8px 4px;margin-bottom:6px;border-bottom:1px solid var(--edge)">
              <span id="fleet-bulk-count" style="font-size:12px;color:var(--dim)"></span>
              <button class="btn sm primary" id="fleet-bulk-mark-deployed">Mark deployed</button>
              <button class="btn sm ghost" id="fleet-bulk-clear">Clear selection</button>
            </div>
            <table class="fleet" id="fleet-table"></table>
          </div></div>
        </div>

        <!-- Local sanity check - runs the REAL detect/install/uninstall
             scripts (or PSADT's own test invocation) on this machine, no
             Intune needed. Separate from "Preview". -->
        <div id="test-modal" style="display:none;position:fixed;inset:0;background:rgba(5,5,10,.65);z-index:90;align-items:center;justify-content:center">
          <div class="card" style="width:560px;max-height:80vh;display:flex;flex-direction:column;padding:0">
            <div style="padding:18px 22px 0"><div class="eyebrow">local sanity check</div><div class="card-t" id="test-modal-title" style="margin-top:4px">Test locally</div></div>
            <div style="padding:12px 22px">
              <p class="hint" style="margin:0 0 10px">Decrypts the real <b>.intunewin</b> file if one exists and tests that (not just loose scripts) - it will actually install (and optionally uninstall) the app on <b style="color:var(--warn)">this machine</b>. No Intune required.</p>
              <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--dim);cursor:pointer;margin-bottom:6px">
                <input type="checkbox" id="test-simulate-system" checked> Simulate Intune deployment (run as SYSTEM, silent)
              </label>
              <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--dim);cursor:pointer">
                <input type="checkbox" id="test-also-uninstall"> Also test uninstall afterwards
              </label>
            </div>
            <div class="log" id="test-log" style="margin:0 22px;flex:1;min-height:180px;max-height:320px"></div>
            <div style="display:flex;justify-content:flex-end;gap:10px;padding:16px 22px">
              <button class="btn" id="test-modal-close">Close</button>
              <button class="btn primary" id="test-modal-start">Start test</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ========== WORKER & SETTINGS ========== -->
      <section class="screen" data-screen="worker" id="screen-worker">
        <div style="max-width:760px;margin:0 auto;padding-bottom:24px">
          <h2 class="rise" style="font-family:var(--font-d);font-weight:600;font-size:20px;margin:8px 0 14px">Worker &amp; settings</h2>

          <!-- Worker stays its own card - it has real distinct actions, not just toggles -->
          <div class="card rise" id="worker-connect-card" style="margin-bottom:12px;padding:16px 20px">
            <div style="display:flex;align-items:center;gap:14px;margin-bottom:12px">
              <div style="width:38px;height:38px;border-radius:10px;background:var(--grad);display:grid;place-items:center;flex-shrink:0;box-shadow:0 0 18px rgba(var(--signal-rgb),.3)">
                <svg viewBox="0 0 24 24" width="18" height="18" fill="none" style="stroke:var(--on-accent)" stroke-width="2"><path d="M4 12a8 8 0 0 1 14-5.2M20 12a8 8 0 0 1-14 5.2"/><path d="M17.5 4.5v3h-3M6.5 19.5v-3h3"/></svg>
              </div>
              <div>
                <div class="card-t" style="margin:0">Cloudflare worker</div>
                <div id="worker-status" style="margin-top:2px;color:var(--dim);font-size:12px">Loading&hellip;</div>
              </div>
            </div>
            <div id="worker-actions-connected" style="display:none;gap:10px">
              <button class="btn" id="btn-open-status">Open /status dashboard</button>
              <button class="btn" id="btn-worker-options">More worker options&hellip;</button>
              <button class="btn danger" id="btn-disconnect">Disconnect</button>
            </div>
            <div id="worker-actions-disconnected" style="display:none">
              <button class="btn primary" id="btn-worker-connect">Connect to Cloudflare</button>
            </div>
            <p class="hint" id="worker-actions-hint" style="margin-top:10px;display:none">
              "More worker options" covers re-deploy, custom domain, password reset, MFA and token rotation -
              still the existing dialog for now while those get ported into the shell individually.
            </p>
          </div>

          <!-- One consolidated preferences card instead of 4 near-identical
               stacked boxes - everything below saves itself the instant you
               change it (no separate Save button; a small "Saved" flash
               confirms it, the same way most modern settings screens work). -->
          <div class="card rise" style="margin-bottom:14px">
            <div style="padding:18px 22px 4px;display:flex;align-items:center;justify-content:space-between">
              <div class="card-t" style="margin:0">Preferences</div>
              <span id="settings-saved-flash" style="font-size:11px;color:var(--ok);opacity:0;transition:opacity .3s">Saved</span>
            </div>

            <div style="padding:14px 22px">
              <label class="lbl">Default organisation name</label>
              <small style="color:var(--faint);font-size:10.5px;display:block;margin-bottom:6px">Used whenever a build has no client profile selected - backed by a Client Profile, managed from the nav rail.</small>
              <select class="field" id="f-orgname-settings" style="max-width:320px"><option value="">Not set</option></select>
              <div id="f-orgname-not-set-hint" style="display:none;margin-top:6px">
                <span class="hint" style="margin:0">Not set - </span>
                <button type="button" class="btn ghost sm" id="f-orgname-guide-btn" style="padding:0;display:inline;font-size:11px;color:var(--signal)">set up a client profile instead &#8250;</button>
              </div>
            </div>

            <div style="padding:0 22px">
              <div class="tglrow"><div><b>Online lookups</b><small>New releases on GitHub, installer switches from Microsoft's winget catalogue and CISA's list of actively exploited vulnerabilities. Off = no outbound call is ever made. Recommended off for air-gapped machines.</small></div><button class="tgl on" id="tgl-release-check"></button></div>
              <div class="tglrow"><div><b>NIST vulnerability check</b><small>Before each build, asks NIST's National Vulnerability Database which CVEs affect the exact version being packaged. Sends the app's name and version to NIST. Warnings only; needs online lookups.</small></div><button class="tgl" id="tgl-nvd"></button></div>
              <div class="tglrow"><div><b>Show Cloudflare connection promo</b><small>The "Not connected to Cloudflare" card on Home and the fleet empty-state tip. Off if you dismissed it, or if you're offline-only by design.</small></div><button class="tgl on" id="tgl-cf-advert"></button></div>
              <div class="tglrow"><div><b>Show getting-started checklist</b><small>The "A few things to try" card on Home. Off if you dismissed it or it's not needed anymore.</small></div><button class="tgl on" id="tgl-getting-started"></button></div>
            </div>

            <div style="padding:14px 22px 20px;border-top:1px solid var(--edge);margin-top:4px">
              <label class="lbl" style="margin-bottom:8px;display:block">Folders &amp; log</label>
              <div style="display:flex;gap:10px">
                <button class="btn sm" id="btn-open-output">Output</button>
                <button class="btn sm" id="btn-open-cache">Toolkit cache</button>
                <button class="btn sm" id="btn-open-log">Log</button>
                <button class="btn sm" id="btn-open-github" style="margin-left:auto">GitHub releases</button>
              </div>
              <div id="settings-release" style="font-size:11px;color:var(--dim);margin-top:10px">&nbsp;</div>
            </div>
          </div>

          <!-- Recovery kept visually distinct - these are the two genuinely
               destructive/consequential actions on this screen. -->
          <div class="card rise" style="border-color:rgba(var(--warn-rgb),.25)">
            <div class="card-b">
              <div style="display:flex;align-items:center;gap:8px"><span class="eyebrow" style="color:var(--warn)">recovery</span></div>
              <p class="hint" style="margin:8px 0 12px">A passphrase-protected backup of your config, token, client profiles and manifest. Restores only on THIS machine - for a new machine, reconnect to the Worker and re-run setup.</p>
              <div style="display:flex;gap:10px">
                <button class="btn primary" id="btn-export-recovery">Export recovery bundle&hellip;</button>
                <button class="btn" id="btn-import-recovery">Import bundle&hellip;</button>
              </div>
            </div>
          </div>

          <div id="settings-version" style="text-align:center;margin-top:16px;font-size:11px;color:var(--faint)">&nbsp;</div>
        </div>
      </section>

      <!-- ========== CLIENT PROFILES ========== -->
      <section class="screen" data-screen="profiles" id="screen-profiles">
        <div style="max-width:1240px;margin:0 auto">
          <div class="rise" style="margin:10px 0 14px;display:flex;align-items:center;gap:14px">
            <h2 style="font-family:var(--font-d);font-weight:600;font-size:20px">Client profiles</h2>
            <p class="hint" style="margin:0">Branding + defaults applied to every build for a client.</p>
          </div>
          <div id="profiles-strip" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px"></div>

          <div id="profile-editor" style="max-width:1240px;margin:0 auto">
          <div class="card rise" style="display:flex;overflow:hidden">
            <div style="width:320px;flex-shrink:0;padding:20px;overflow-y:auto;border-right:1px solid var(--edge)">
              <div class="eyebrow" style="margin-bottom:10px" id="pf-editing-label">new profile</div>
              <label class="lbl">Name</label>
              <input class="field" id="pf-name" style="margin-bottom:10px">
              <label class="lbl">Organisation override</label>
              <input class="field" id="pf-orgname" style="margin-bottom:10px">
              <label class="lbl">Default output target</label>
              <div class="seg" id="pf-target-seg" style="margin-bottom:10px">
                <div class="thumb"></div>
                <button class="on" data-val="intunewin">.intunewin</button>
                <button data-val="psadt">PSADT</button>
              </div>
              <label class="lbl">Logo image</label>
              <div style="display:flex;gap:8px;margin-bottom:10px">
                <input class="field mono" id="pf-logo" readonly style="flex:1;font-size:10.5px">
                <button class="btn sm" id="pf-logo-browse">Browse&hellip;</button>
              </div>
              <label class="lbl">Banner image</label>
              <div style="display:flex;gap:8px;margin-bottom:14px">
                <input class="field mono" id="pf-banner" readonly style="flex:1;font-size:10.5px">
                <button class="btn sm" id="pf-banner-browse">Browse&hellip;</button>
              </div>
              <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:14px">
                <button class="btn danger" id="pf-delete" style="display:none;margin-right:auto">Delete</button>
                <button class="btn" id="pf-cancel">Cancel</button>
                <button class="btn primary" id="pf-save">Save profile</button>
              </div>
            </div>

            <div style="flex:1;padding:20px;overflow-y:auto;background:var(--void);min-width:0">
              <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">
                <div class="eyebrow" style="margin:0">preview - what a real build with this profile looks like</div>
                <div class="seg" id="segPfSwap" style="transform:scale(.82);transform-origin:left center;margin-left:-6px">
                  <div class="thumb"></div>
                  <button class="on" data-val="v3">v3 classic</button>
                  <button data-val="v4">v4 fluent</button>
                </div>
              </div>
              <p class="hint" style="margin-bottom:12px">Click the logo, banner, or text below to edit that field directly - or use the fields on the left.</p>

              <div id="pf-preview-v3" style="border-radius:6px;overflow:hidden;background:#F0F0F0;border:1px solid #ACACAC;box-shadow:0 6px 20px rgba(0,0,0,.35);font-family:'Segoe UI',var(--font-b);max-width:380px">
                <div id="pf-v3-banner-wrap" class="pf-click-target" data-pf-click="pf-banner-browse" title="Click to set the banner image" style="width:100%;aspect-ratio:900/125;background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden;border-bottom:1px solid #ACACAC;cursor:pointer">
                  <img id="pf-v3-banner" style="width:100%;height:100%;object-fit:cover;display:none">
                  <span id="pf-v3-banner-placeholder" style="font-size:10px;color:#888">Click to set a banner (900&times;125 recommended)</span>
                </div>
                <div style="padding:12px 14px;background:#F0F0F0">
                  <div class="pf-click-target" data-pf-click="pf-name" title="Click to edit the app name" style="font-weight:600;font-size:12.5px;color:#1a1a1a;cursor:pointer" id="pf-v3-title">Welcome to the Example App Setup</div>
                  <div style="font-size:10.5px;color:#444;margin-top:4px">Please close the following programs before continuing:</div>
                  <div style="background:#fff;border:1px solid #ACACAC;border-radius:2px;margin-top:6px;padding:5px 8px;font-size:10px;color:#333">Microsoft Word</div>
                  <div style="display:flex;gap:6px;margin-top:10px;justify-content:flex-end">
                    <div style="background:#E1E1E1;border:1px solid #ADADAD;border-radius:2px;padding:4px 12px;font-size:10.5px;color:#1a1a1a">Close &amp; Continue</div>
                  </div>
                </div>
              </div>

              <div id="pf-preview-v4" style="display:none;border-radius:12px;overflow:hidden;background:#202020;border:1px solid #3a3a3a;box-shadow:0 6px 24px rgba(0,0,0,.4);font-family:var(--font-b);max-width:380px">
                <div style="padding:20px 20px 16px;display:flex;gap:14px;align-items:flex-start">
                  <div id="pf-v4-icon-wrap" class="pf-click-target" data-pf-click="pf-logo-browse" title="Click to set the logo image" style="width:44px;height:44px;border-radius:10px;overflow:hidden;flex-shrink:0;background:#2d2d2d;display:grid;place-items:center;cursor:pointer">
                    <img id="pf-v4-icon" style="width:100%;height:100%;object-fit:cover;display:none">
                    <span id="pf-v4-icon-placeholder" style="font-size:8px;color:#999;text-align:center">logo</span>
                  </div>
                  <div style="min-width:0">
                    <div class="pf-click-target" data-pf-click="pf-name" title="Click to edit the app name" style="font-weight:600;font-size:14px;color:#fff;cursor:pointer" id="pf-v4-title">Example App</div>
                    <div class="pf-click-target" data-pf-click="pf-orgname" title="Click to edit the organisation name" style="font-size:11px;color:#a0a0a0;margin-top:2px;cursor:pointer" id="pf-v4-subtitle">Acme Corp - please close the following applications to continue.</div>
                  </div>
                </div>
                <div style="padding:0 20px 18px">
                  <div style="background:#2d2d2d;border-radius:6px;padding:8px 12px;font-size:11px;color:#ddd">Microsoft Word</div>
                  <div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end">
                    <div style="background:#0078D7;border-radius:5px;padding:6px 16px;font-size:11.5px;color:#fff;font-weight:600">Close apps &amp; install</div>
                  </div>
                </div>
              </div>
              <p class="hint" style="margin-top:10px" id="pf-no-assets-hint">Real PSADT stock assets aren't cached on this machine yet - build a PSADT package once and this preview will use the actual banner/icon as fallback.</p>
            </div>
          </div>
          </div>
        </div>
      </section>

      <!-- ========== HISTORY ========== -->
      <section class="screen" data-screen="history" id="screen-history">
        <div style="max-width:1240px;margin:0 auto">
          <div class="rise" style="margin:10px 0 18px;display:flex;align-items:center;gap:14px">
            <h2 style="font-family:var(--font-d);font-weight:600;font-size:20px">History</h2>
            <span id="history-demo-badge" style="display:none;font-family:var(--font-m);font-size:10.5px;color:var(--warn);border:1px solid rgba(var(--warn-rgb),.35);background:rgba(var(--warn-rgb),.08);padding:3px 9px;border-radius:20px">example data - tour only</span>
            <p class="hint" style="margin:0">Every build, deploy-mark, and removal recorded on this machine, most recent first.</p>
          </div>
          <div class="card rise"><div class="card-b" style="padding-top:6px">
            <table class="fleet" id="history-table"></table>
            <div id="history-empty" style="display:none;text-align:center;padding:44px 20px">
              <svg viewBox="0 0 24 24" width="34" height="34" fill="none" stroke="var(--faint)" stroke-width="1.5" style="margin-bottom:14px">
                <path d="M3 3v5h5"/><path d="M3.05 13a9 9 0 1 0 2.13-7.83L3 8"/><path d="M12 7v5l4 2"/>
              </svg>
              <div style="font-family:var(--font-d);font-weight:600;font-size:15px;margin-bottom:6px">No history yet</div>
              <p class="hint" style="max-width:380px;margin:0 auto 18px">Every build, deploy-mark, and removal you perform on this machine will show up here automatically, most recent first.</p>
              <button class="btn primary sm" data-go="build">Build your first package</button>
            </div>
          </div></div>
        </div>
      </section>

      <!-- ========== ACCESSIBILITY ========== -->
      <section class="screen" data-screen="accessibility" id="screen-accessibility">
        <div style="max-width:640px;margin:0 auto">
          <h2 class="rise" style="font-family:var(--font-d);font-weight:600;font-size:20px;margin:10px 0 18px">Accessibility</h2>
          <div class="card rise">
            <div class="card-b">
              <div class="tglrow"><div><b>Reduce motion</b><small>Disables window/page animations and transitions app-wide. Off by default.</small></div><button class="tgl" id="tgl-reduce-motion"></button></div>
              <div class="tglrow"><div><b>High contrast</b><small>Stronger edges and text contrast throughout the app. Off by default.</small></div><button class="tgl" id="tgl-high-contrast"></button></div>
              <div class="tglrow"><div><b>Colour-blind safe palette</b><small>Swaps status colours (green/amber/red) for a palette distinguishable across all common colour vision types, plus icon shapes so status is never colour-only. Off by default.</small></div><button class="tgl" id="tgl-colorblind"></button></div>
            </div>
          </div>
        </div>
      </section>

      <!-- ========== DOCS & HELP ========== -->
      <section class="screen" data-screen="docs" id="screen-docs">
        <div style="max-width:760px;margin:0 auto;padding-bottom:36px">

          <div class="rise" style="margin:20px 0 18px">
            <div class="eyebrow">reference</div>
            <h1 style="font-family:var(--font-d);font-weight:700;font-size:24px;letter-spacing:-.01em;margin-top:4px">How AppUpdater works</h1>
            <p style="color:var(--dim);margin-top:4px;font-size:13.5px;max-width:520px">A quick walkthrough of every screen, plus where to find the source and file issues.</p>
          </div>

          <div class="card rise" style="margin-bottom:12px;display:flex;align-items:center;gap:14px;padding:14px 18px">
            <div style="width:38px;height:38px;border-radius:10px;background:var(--grad);display:grid;place-items:center;flex-shrink:0;box-shadow:0 0 20px rgba(var(--signal-rgb),.3)">
              <svg viewBox="0 0 24 24" width="18" height="18" fill="none" style="stroke:var(--on-accent)" stroke-width="1.8"><path d="M12 1a11 11 0 0 0-3.48 21.44c.55.1.75-.24.75-.53v-1.85c-3.06.67-3.7-1.47-3.7-1.47-.5-1.27-1.22-1.6-1.22-1.6-1-.68.08-.67.08-.67 1.1.08 1.68 1.13 1.68 1.13.98 1.68 2.57 1.2 3.2.92.1-.71.38-1.2.7-1.48-2.44-.28-5.02-1.22-5.02-5.42 0-1.2.43-2.18 1.12-2.94-.11-.28-.49-1.4.1-2.9 0 0 .93-.3 3.03 1.12a10.4 10.4 0 0 1 5.52 0c2.1-1.42 3.03-1.12 3.03-1.12.6 1.5.22 2.62.1 2.9.7.76 1.12 1.74 1.12 2.94 0 4.21-2.58 5.13-5.04 5.4.39.35.75 1.02.75 2.06v3.05c0 .3.2.64.76.53A11 11 0 0 0 12 1z"/></svg>
            </div>
            <div style="flex:1">
              <div style="font-family:var(--font-d);font-weight:600;font-size:14.5px">Source &amp; issues</div>
              <div style="font-size:12px;color:var(--dim);margin-top:2px">github.com/Lyvvy-xyz/Appupdater</div>
            </div>
            <button class="btn" id="docs-github-link">Open GitHub</button>
          </div>

          <div class="card rise" style="margin-bottom:12px;padding:14px 18px">
            <div style="display:flex;align-items:center;gap:14px;margin-bottom:12px">
              <div style="width:38px;height:38px;border-radius:10px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
                <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 1.5-2.5 1.8-2.5 3.5"/><circle cx="12" cy="17" r=".6" fill="currentColor" stroke="none"/></svg>
              </div>
              <div style="flex:1">
                <div style="font-family:var(--font-d);font-weight:600;font-size:14.5px">Guided walkthrough</div>
                <div style="font-size:12px;color:var(--dim);margin-top:2px">Replay the tour that highlights each screen and explains what it does.</div>
              </div>
              <button class="btn primary" id="docs-replay-tour">Replay tour</button>
            </div>
            <div class="tglrow" style="border-top:1px solid var(--edge);padding-top:10px">
              <div><b style="font-size:12.5px">Show Fleet &amp; Worker/settings pages</b><small style="font-size:10.5px">If you chose "Not now" for Cloudflare during the tour without keeping them visible, this brings them back.</small></div>
              <button class="tgl on" id="tgl-cf-nav"></button>
            </div>
            <div class="tglrow" style="border-top:1px solid var(--edge);padding-top:10px">
              <div><b style="font-size:12.5px">Reset app for first launch</b><small style="font-size:10.5px">Clears the first-launch flags - close and reopen AppUpdater to see the guide exactly as a new install would.</small></div>
              <button class="btn danger sm" id="docs-reset-onboarding">Reset</button>
            </div>
          </div>

          <div class="rise" style="margin:20px 0 12px"><div class="eyebrow">screen by screen</div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 12l9-8 9 8M5 10v10h5v-6h4v6h5V10"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Home</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Your fleet at a glance, and whether the Cloudflare worker is connected. "Build app package" starts a new package; the table below shows the last few tracked apps.</p>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>
            </div>
            <div style="flex:1">
              <div class="card-t" style="margin-top:2px">Build</div>
              <div style="display:grid;gap:8px;margin-top:10px">
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">01</span><span style="font-size:13px;color:var(--dim)">Drop or browse to an installer (.exe/.msi) - version, publisher and silent args are detected automatically.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">02</span><span style="font-size:13px;color:var(--dim)">Confirm identity fields - registry name must match Add/Remove Programs exactly for detection to work.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">03</span><span style="font-size:13px;color:var(--dim)">Choose Runtime (auto-updates itself) or Simple, and an output target - .intunewin, or PSADT v3/v4/both.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">04</span><span style="font-size:13px;color:var(--dim)">Review behaviour toggles, then Build.</span></div>
              </div>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">App fleet</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Every app tracked in your local manifest. "Rebuild" re-opens the builder pre-filled for that app; "Mark deployed" records that you've pushed it live (tracked locally by the shell, separate from the manifest itself).</p>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.5"/><rect x="14" y="4" width="7" height="7" rx="1.5"/><rect x="3" y="15" width="7" height="7" rx="1.5"/><rect x="14" y="15" width="7" height="7" rx="1.5"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Client profiles</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">A profile bundles a client's organisation name, logo/banner, and default output target so every build for that client is branded consistently. Pick one on the Build screen before building.</p>
            </div>
          </div></div>

          <div class="card rise"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Worker &amp; settings</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Connect to Cloudflare for auto-updates and a live status dashboard, or stay fully offline - packaging always works standalone. Recovery bundles back up your config/profiles/manifest with a passphrase; they restore only on the machine that made them.</p>
            </div>
          </div></div>

        </div>
      </section>

    </div>
    <div class="buildbar" id="buildbar" style="display:none">
      <div class="summary" id="build-summary">Select an installer to begin.</div>
      <button class="btn ghost" data-go="home">Cancel</button>
      <button class="btn primary big" id="btn-build" disabled>Build package<kbd>Ctrl &#8629;</kbd></button>
    </div>
    <div class="statusbar" id="statusbar"><span id="sb-winget"></span><span id="sb-cisa"></span><span id="sb-nvd"></span><span class="grow"></span><span id="sb-mode"></span><span id="sb-version"></span></div>
  </div>
</div>
<div class="toasts" id="toasts"></div>
<div class="chip-pop" id="chip-pop" hidden role="dialog" aria-live="polite"><div id="chip-pop-text"></div><button type="button" class="btn sm" id="chip-pop-link" hidden>Open</button></div>

<div id="tour-overlay">
  <div id="tour-spot"></div>
  <div id="tour-card">
    <div class="eyebrow" id="tour-step-count"></div>
    <div style="font-family:var(--font-d);font-weight:600;font-size:15px;margin:6px 0 8px" id="tour-title"></div>
    <p style="font-size:12.5px;color:var(--dim);margin-bottom:14px;line-height:1.5" id="tour-text"></p>
    <div id="tour-cf-choice" style="display:none;margin-bottom:14px">
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <button class="btn primary sm" id="tour-cf-yes" style="flex:1">Set up now</button>
        <button class="btn sm" id="tour-cf-no" style="flex:1">Not now</button>
      </div>
      <label style="display:flex;align-items:center;gap:8px;font-size:11.5px;color:var(--dim);cursor:pointer">
        <input type="checkbox" id="tour-cf-keep-visible"> Keep these pages visible anyway
      </label>
    </div>
    <div style="display:flex;align-items:center;gap:8px" id="tour-nav-buttons">
      <button class="btn ghost sm" id="tour-skip">Skip tour</button>
      <div style="flex:1"></div>
      <button class="btn sm" id="tour-back">Back</button>
      <button class="btn primary sm" id="tour-next">Next</button>
    </div>
  </div>
</div>

<script>
  const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
  const bridge = window.chrome && window.chrome.webview;
  function escapeHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  function send(action, payload) {
    if (bridge) bridge.postMessage({ action, payload });
    else console.warn('WebView2 bridge unavailable — running outside host?', action, payload);
  }
  window.addEventListener('error', e => {
    try { send('client-error', { message: e.message, stack: (e.error && e.error.stack) || '', source: e.filename + ':' + e.lineno }); } catch (_) {}
  });
  window.addEventListener('unhandledrejection', e => {
    try { send('client-error', { message: 'Unhandled promise rejection: ' + (e.reason && e.reason.message || e.reason), stack: (e.reason && e.reason.stack) || '' }); } catch (_) {}
  });

  function toast(title, msg, isErr) {
    const t = document.createElement('div');
    t.className = 'toast' + (isErr ? ' err' : '');
    t.innerHTML = `<b><i></i>${escapeHtml(title)}</b><p>${escapeHtml(msg)}</p><span class="life"></span>`;
    $('#toasts').appendChild(t);
    setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), 320); }, 4000);
  }

  function segInit(seg, onChange) {
    const th = seg.querySelector('.thumb'), btns = [...seg.querySelectorAll('button')];
    function place(b) { th.style.left = b.offsetLeft + 'px'; th.style.width = b.offsetWidth + 'px'; }
    btns.forEach(b => b.addEventListener('click', () => {
      btns.forEach(x => x.classList.remove('on')); b.classList.add('on'); place(b);
      onChange && onChange(b.dataset.val);
    }));
    requestAnimationFrame(() => place(seg.querySelector('button.on') || btns[0]));
    new ResizeObserver(() => place(seg.querySelector('button.on') || btns[0])).observe(seg);
  }

  function pipeNames() {
    // The progress bar names the file each step produces.
    const id = ($('#f-appid') && $('#f-appid').value.trim()) || 'App';
    const source = form.Kind === 'printer' ? 'printer' : (window._selectedInstaller ? window._selectedInstaller.split(/[\\/]/).pop() : 'installer');
    const psadt = form.SimplePkgTarget === 'psadt';
    const detect = form.Kind === 'printer' ? 'Detect-Printer.ps1' : form.Mode === 'runtime' ? `Detect-${id}.ps1` : 'detect.ps1';
    const install = form.Kind === 'printer' ? 'Install-Printer.ps1' : psadt ? 'Deploy-Application.ps1' : form.Mode === 'runtime' ? `Deploy-${id}.ps1` : 'install.ps1';
    return [source, detect, install, psadt ? `${id}-PSADT` : `${id}.intunewin`, 'Intune'];
  }
  function renderPipe(activeIdx, doneUpTo, flowIdx) {
    const pipe = $('#pipe');
    if (activeIdx == null) { pipe.style.display = 'none'; return; }
    pipe.style.display = 'flex';
    const pipeLabels = pipeNames();
    pipe.innerHTML = pipeLabels.map((label, i) => {
      const st = i < doneUpTo ? 'done' : i === activeIdx ? 'live' : '';
      const flow = flowIdx === i ? ' flow' : '';
      const line = i < pipeLabels.length - 1 ? `<div class="pline${flow}"><i></i></div>` : '';
      return `<div class="pnode ${st}" data-pipe-step="${i}" role="button" tabindex="0"><div class="pdot">${i + 1}<span class="tick"><svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg></span></div><span class="plabel">${escapeHtml(label)}</span></div>${line}`;
    }).join('');
  }

  // On the builder the progress bar is the way through the form: it shows which steps are complete and jumps to a step.
  const pipeCards = () => ['#sec-source', '#sec-identity', '#sec-configure', '#sec-wrap', '#btn-build'];
  function builderProgress() {
    if (!$('#screen-build').classList.contains('on')) return;
    const done = [form.Kind === 'printer' ? !!$('#f-printername').value.trim() : inspected,
      !!($('#f-displayname').value.trim() && $('#f-appid').value.trim() && (form.Kind === 'printer' || $('#f-registryname').value.trim())),
      form.Kind === 'printer' || !!$('#f-silentargs').value.trim() || /\.(msi|msix|msixbundle|appx|appxbundle|zip)$/i.test(window._selectedInstaller || ''),
      true];
    const reached = done.findIndex(d => !d);
    const count = reached === -1 ? 4 : reached;
    renderPipe(Math.min(count, 4), count);
  }
  document.getElementById('pipe').addEventListener('click', e => {
    const node = e.target.closest('[data-pipe-step]');
    if (!node || !$('#screen-build').classList.contains('on')) return;
    const target = $(pipeCards()[Number(node.dataset.pipeStep)]);
    const card = target && (target.closest('.bsec') || target.closest('.card') || target);
    if (!card) return;
    card.scrollIntoView({ behavior: 'smooth', block: 'center' });
    card.classList.remove('pulse'); void card.offsetWidth; card.classList.add('pulse');
  });
  document.getElementById('drag-region').addEventListener('mousedown', (e) => {
    if (e.target.closest('#win-minimize, #win-close') || e.target.closest('#pipe')) return;
    if (e.button !== 0) return;
    send('drag-window', {});
  });
  document.getElementById('win-minimize').addEventListener('click', () => send('minimize-window', {}));
  document.getElementById('win-close').addEventListener('click', () => send('close-window', {}));
  document.querySelector('.logo').addEventListener('click', function(){
    this.classList.remove('spin'); void this.offsetWidth; this.classList.add('spin');
  });

  const screens = ['home', 'build', 'progress', 'done', 'fleet', 'profiles', 'history', 'worker', 'accessibility', 'docs'];
  const crumbs = { home: 'AppUpdater', build: 'Package builder', progress: 'Building', done: 'Package ready', fleet: 'App fleet', profiles: 'Client profiles', history: 'History', worker: 'Worker & settings', accessibility: 'Accessibility', docs: 'Docs & help' };
  function goTo(id) {
    screens.forEach(s => $('#screen-' + s).classList.toggle('on', s === id));
    $$('.nav-btn[data-go]').forEach(b => b.classList.toggle('on', b.dataset.go === id || (['build','progress','done'].includes(id) && b.dataset.go === 'build')));
    $('#crumb').textContent = crumbs[id] || 'AppUpdater';
    $('#buildbar').style.display = (id === 'build') ? 'flex' : 'none';
    if (id === 'build') {
      builderProgress();
      if (!window._tourActive && !window._modeExplainerSeen && !window._modeExplainerShownThisSession) {
        window._modeExplainerShownThisSession = true;
        updateModeExplainerText();
        $('#mode-explainer').style.display = 'block';
      }
    }
    else if (id === 'progress') renderPipe(2, 2, 2);
    else if (id === 'done') renderPipe(4, 5);
    else renderPipe(null);
    if (id === 'fleet') send('get-fleet', {});
    if (id === 'profiles') { send('get-profiles', {}); if (!window._profileEditorInit) { window._profileEditorInit = true; openProfileEditor(null); } }
    if (id === 'history') send('get-history', {});
    if (id === 'worker') { send('get-config', {}); send('get-settings', {}); send('get-fleet', {}); }
  }
  document.addEventListener('click', e => { const g = e.target.closest('[data-go]'); if (g) goTo(g.dataset.go); });
  document.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
      const g = e.target.closest('[data-go][role="button"]');
      if (g) { e.preventDefault(); goTo(g.dataset.go); return; }
    }
    if (e.key === 'Escape') {
      const testModal = $('#test-modal');
      if (testModal && testModal.style.display !== 'none') { testModal.style.display = 'none'; return; }
      const drAdd = $('#driver-lib-add-panel');
      if (drAdd && drAdd.style.display === 'block') { drAdd.style.display = 'none'; return; }
      const ovPanel = $('#build-override-panel');
      if (ovPanel && ovPanel.style.display === 'block') { ovPanel.style.display = 'none'; window._overridePanelOpened = false; return; }
      const explainer = $('#mode-explainer');
      if (explainer && explainer.style.display === 'block') { explainer.style.display = 'none'; return; }
    }
  });

  const form = { Kind: 'app', Mode: 'runtime', SimplePkgTarget: 'intunewin', PSADTVersion: 'v3', ProfileName: '', closeAppsOn: true, allowDefer: true, ProcessesToKill: '' };
  let inspected = false;

  segInit($('#segKind'), v => {
    form.Kind = v;
    $('#screen-build').classList.toggle('printer', v === 'printer');
    $('#app-source-card').style.display = v === 'app' ? 'block' : 'none';
    $('#printer-source-card').style.display = v === 'printer' ? 'block' : 'none';
    $('#kindHint').textContent = v === 'app'
      ? 'Standard installer package - drop an exe, msi, msix/appx or portable-app zip below.'
      : 'Deploys a printer/driver via native Windows printer cmdlets - no installer needed.';
    $('#btn-build').disabled = v === 'printer' ? !$('#f-printername').value.trim() : !inspected;
    if (v === 'printer' && !window._driverLibraryRequested) {
      window._driverLibraryRequested = true;
      send('get-driver-library', {});
    }
    updateSummary();
  });

  function renderDriverLibrary(drivers) {
    window._driverLibrary = drivers || [];
    const sel = $('#f-driverid');
    const prev = sel.value;
    sel.innerHTML = '<option value="">&mdash; none, use path below &mdash;</option>' + window._driverLibrary.map(d => {
      const noFiles = !d.HasFiles ? ' - driver files not yet supplied' : '';
      return `<option value="${escapeHtml(d.DriverID)}">${escapeHtml(d.DisplayName)}${d.Manufacturer ? ' Â· ' + escapeHtml(d.Manufacturer) : ''}${d.Architecture ? ' (' + escapeHtml(d.Architecture) + ')' : ''}${noFiles}</option>`;
    }).join('');
    if (window._driverLibrary.some(d => d.DriverID === prev)) sel.value = prev;
    updateDriverModelRow();
  }
  function updateDriverModelRow() {
    const d = (window._driverLibrary || []).find(x => x.DriverID === $('#f-driverid').value);
    const row = $('#driver-model-row');
    const modelSel = $('#f-drivermodel');
    if (d && Array.isArray(d.Models) && d.Models.length > 1) {
      modelSel.innerHTML = d.Models.map(m => `<option value="${escapeHtml(m)}">${escapeHtml(m)}</option>`).join('');
      row.style.display = 'block';
      $('#f-drivername').value = modelSel.value || d.DisplayName || '';
    } else {
      row.style.display = 'none';
      modelSel.innerHTML = '';
    }
  }
  $('#f-driverid').addEventListener('change', (e) => {
    const d = (window._driverLibrary || []).find(x => x.DriverID === e.target.value);
    updateDriverModelRow();
    if (d && !(Array.isArray(d.Models) && d.Models.length > 1)) $('#f-drivername').value = d.DisplayName || '';
  });
  $('#f-drivermodel').addEventListener('change', (e) => {
    $('#f-drivername').value = e.target.value;
  });
  $('#driver-lib-add-toggle').addEventListener('click', () => {
    const panel = $('#driver-lib-add-panel');
    panel.style.display = panel.style.display === 'block' ? 'none' : 'block';
    $('#dl-status').textContent = '';
  });
  $('#driver-lib-import-builtin').addEventListener('click', () => {
    $('#driver-lib-import-builtin').disabled = true;
    $('#builtin-import-status').textContent = 'Importing built-in driver families...';
    send('import-builtin-driver-families', {});
  });
  $('#dl-cancel').addEventListener('click', () => { $('#driver-lib-add-panel').style.display = 'none'; });
  $('#dl-save').addEventListener('click', () => {
    const driverId = $('#dl-id').value.trim();
    const displayName = $('#dl-displayname').value.trim();
    const source = $('#dl-source').value.trim();
    const inf = $('#dl-inf').value.trim();
    if (!driverId || !displayName || !source || !inf) {
      $('#dl-status').textContent = 'Driver ID, Display name, Source, and INF relative path are all required.';
      return;
    }
    $('#dl-save').disabled = true;
    $('#dl-status').textContent = 'Importing - downloading/verifying, this may take a moment...';
    send('add-driver-to-library', {
      driverId, displayName, sourcePath: source, infRelativePath: inf,
      manufacturer: $('#dl-manufacturer').value.trim(),
      driverType: $('#dl-drivertype').value.trim(),
      architecture: $('#dl-arch').value.trim(),
      expectedPublisher: $('#dl-publisher').value.trim(),
      version: $('#dl-version').value.trim(),
      models: $('#dl-models').value.split('\n').map(m => m.trim()).filter(m => m)
    });
  });
  ['f-printername', 'f-drivername', 'f-porthost'].forEach(id => {
    $('#' + id).addEventListener('input', () => {
      if (form.Kind === 'printer') $('#btn-build').disabled = !$('#f-printername').value.trim();
    });
  });

  $('#mode-explainer-toggle').addEventListener('click', () => {
    const el = $('#mode-explainer');
    el.style.display = el.style.display === 'block' ? 'none' : 'block';
  });
  $('#mode-explainer-dismiss').addEventListener('click', () => {
    $('#mode-explainer').style.display = 'none';
    if (!window._modeExplainerSeen) {
      window._modeExplainerSeen = true;
      send('mark-mode-explainer-seen', {});
    }
  });
  function updateModeExplainerText() {
    const modeText = form.Mode === 'runtime'
      ? '<b>AppUpdater Runtime</b> (selected) installs the app plus a small background task that keeps checking for new versions and updates it automatically - "set it and forget it".'
      : '<b>Simple Package</b> (selected) just installs the app once, nothing extra - use this when something else (e.g. Intune\'s own update detection) will handle updates instead.';
    const targetText = form.SimplePkgTarget === 'psadt'
      ? '<b>PSADT package</b> (selected) wraps the install with PSAppDeployToolkit, adding a branded "please close these apps" prompt and the option to let users defer.'
      : '<b>.intunewin</b> (selected) packages straight for Intune Win32 upload as-is, with no extra install-time prompts.';
    $('#mode-explainer-text').innerHTML = modeText + '<br><br>' + targetText;
  }
  function guideToModeExplainer() {
    updateModeExplainerText();
    if (!window._tourActive && !window._modeExplainerSeen) {
      window._modeExplainerShownThisSession = true;
      $('#mode-explainer').style.display = 'block';
    }
  }
  segInit($('#segMode'), v => {
    form.Mode = v;
    $('#modeHint').textContent = v === 'runtime'
      ? 'Installs auto-update task, scripts and desktop shortcut on every device.'
      : 'Installs the app directly with no AppUpdater runtime or auto-update task.';
    updateSummary();
    guideToModeExplainer();
  });
  segInit($('#segTarget'), v => {
    form.SimplePkgTarget = v;
    $('#targetHint').textContent = v === 'intunewin'
      ? 'Package for Intune Win32 app upload.'
      : 'Wrap with PSAppDeployToolkit for enterprise close-apps prompts.';
    $('#psadt-version-row').style.display = v === 'psadt' ? 'block' : 'none';
    $('#bp-header').style.display = v === 'psadt' ? 'flex' : 'none';
    $('#bp-panel').style.display = (v === 'psadt' && window._bpExpanded) ? 'block' : 'none';
    if (v === 'psadt') updateBuildBrandingPreview();
    updateSummary();
    guideToModeExplainer();
  });
  segInit($('#segPsadtVersion'), v => { form.PSADTVersion = v; updateBuildBrandingPreview(); });
  segInit($('#segBpSwap'), v => { window._bpSwapVersion = v; updateBuildBrandingPreview(); });
  $('#bp-disclosure').addEventListener('click', () => {
    window._bpExpanded = !window._bpExpanded;
    $('#bp-disclosure').classList.toggle('open', window._bpExpanded);
    $('#bp-panel').style.display = window._bpExpanded ? 'block' : 'none';
    if (window._bpExpanded) updateBuildBrandingPreview();
  });

  $('#f-profile').addEventListener('change', (e) => {
    form.ProfileName = e.target.value;
    $('#build-override-toggle').style.display = form.ProfileName ? 'inline-flex' : 'none';
    $('#build-override-panel').style.display = 'none';
    window._overridePanelOpened = false;
    updateSummary();
    refreshBuildProfileImage();
  });
  $('#build-new-profile').addEventListener('click', () => {
    window._returnToBuildAfterProfile = true;
    goTo('profiles');
    openProfileEditor(null);
  });
  $('#build-override-toggle').addEventListener('click', () => {
    const panel = $('#build-override-panel');
    const opening = panel.style.display !== 'block';
    panel.style.display = opening ? 'block' : 'none';
    if (opening) {
      const p = (window._profiles || []).find(pp => pp.Name === form.ProfileName);
      $('#ov-orgname').value = (p && p.OrgName) || '';
      $('#ov-logo').value = (p && p.LogoImagePath) || '';
      $('#ov-banner').value = (p && p.BannerImagePath) || '';
      window._overridePanelOpened = true;
    } else {
      window._overridePanelOpened = false;
    }
  });
  $('#ov-logo-browse').addEventListener('click', () => send('browse-image', { field: 'ov-logo' }));
  $('#ov-banner-browse').addEventListener('click', () => send('browse-image', { field: 'ov-banner' }));
  $('#ov-orgname').addEventListener('input', updateBuildBrandingPreview);
  function refreshBuildProfileImage() {
    const p = (window._profiles || []).find(p => p.Name === form.ProfileName);
    if (p && p.LogoImagePath) send('get-image-preview', { field: 'bp-logo', path: p.LogoImagePath });
    else setImagePreview('bp-logo', null);
    if (p && p.BannerImagePath) send('get-image-preview', { field: 'bp-banner', path: p.BannerImagePath });
    else setImagePreview('bp-banner', null);
    updateBuildBrandingPreview();
  }
  function resolveBuildOrgName() {
    const p = (window._profiles || []).find(p => p.Name === form.ProfileName);
    const overrideOrg = window._overridePanelOpened ? $('#ov-orgname').value.trim() : '';
    return (overrideOrg || (p && p.OrgName) || window._defaultOrgName || '').trim();
  }
  function updateBuildBrandingPreview() {
    const appName = $('#f-displayname').value.trim() || 'this app';
    const org = resolveBuildOrgName();
    const showSwap = form.PSADTVersion === 'both';
    $('#segBpSwap').style.display = showSwap ? 'inline-flex' : 'none';
    const shown = showSwap ? (window._bpSwapVersion || 'v3') : (form.PSADTVersion === 'v4' ? 'v4' : 'v3');
    $('[data-version-label]').textContent = `Preview branding (PSADT ${shown})`;
    $('#bp-preview-v3').style.display = shown === 'v3' ? 'block' : 'none';
    $('#bp-preview-v4').style.display = shown === 'v4' ? 'block' : 'none';

    const stock = window._psadtStockAssets;
    $('#bp-no-assets-hint').style.display = stock ? 'none' : 'block';
    const bannerSrc = window._bpBannerDataUrl || (stock && stock.banner) || '';
    const iconSrc = window._bpLogoDataUrl || (stock && stock.icon) || '';
    $('#bp-v3-banner').src = bannerSrc;
    $('#bp-v3-banner-wrap').style.opacity = bannerSrc ? '1' : '.15';
    $('#bp-v4-icon').src = iconSrc;
    $('#bp-v4-icon-wrap').style.opacity = iconSrc ? '1' : '.4';

    $('#bp-v3-title').textContent = `Welcome to the ${appName} Setup`;
    $('#bp-v4-title').textContent = org ? `${appName}` : appName;
    $('#bp-v4-subtitle').textContent = org ? `${org} - please close the following applications to continue.` : 'Please close the following applications to continue.';
  }
  $('#f-displayname').addEventListener('input', updateBuildBrandingPreview);

  // Build-form toggles only; the settings toggles have their own handlers and would otherwise flip twice per click.
  $$('.tgl[data-val]').forEach(btn => btn.addEventListener('click', () => {
    const key = btn.dataset.val;
    form[key] = !form[key];
    btn.classList.toggle('on', form[key]);
  }));

  ['f-displayname','f-appid','f-registryname','f-silentargs','f-printername'].forEach(id => $('#' + id).addEventListener('input', updateSummary));

  $('#drop').addEventListener('click', () => send('browse-installer', {}));
  $('#reDrop').addEventListener('click', e => { e.stopPropagation(); resetInstaller(); });

  function resetInstaller() {
    inspected = false; window._selectedInstaller = null;
    $('#inspect').style.display = 'none'; $('#drop').style.display = 'block';
    $('#btn-build').disabled = true;
    builderProgress();
    updateSummary();
  }

  function updateSummary() {
    builderProgress();
    // Only the rows that apply to this mode and output are shown. Runtime detection checks the agent, and MSIX
    // detection reads the package version itself.
    const app = form.Kind !== 'printer', simple = form.Mode === 'simple', runtime = form.Mode === 'runtime', psadt = form.SimplePkgTarget === 'psadt';
    $('#detectversion-wrap').style.display = app && simple && window._installerType !== 'MSIX' ? 'grid' : 'none';
    $('#scripts-wrap').style.display = simple && !['MSIX', 'Zip'].includes(window._installerType) ? 'block' : 'none';
    $('#runtime-url-row').style.display = app && runtime ? 'grid' : 'none';
    $('#close-apps-row').style.display = app && (psadt || runtime) ? 'grid' : 'none';
    $('#defer-row').style.display = app && psadt ? 'grid' : 'none';
    const minVersion = $('#f-detectversion').value.trim();
    $('#detect-any').classList.toggle('on', !minVersion);
    $('.detect').classList.toggle('min', !!minVersion);
    const scripts = ['f-prehook', 'f-posthook', 'f-postuninstallhook'].filter(id => $('#' + id).value.trim()).length;
    $('#extras-summary').innerHTML = `<span>Whole folder <b>${form.BundleFolder ? 'on' : 'off'}</b></span><span>Scripts <b>${scripts || 'none'}</b></span>` +
      (simple ? `<span>Remove older <b>${form.RemoveOlderVersions ? 'on' : 'off'}</b></span>` : '');
    const src = window._src || {};
    for (const [id, key] of [['src-displayname', 'displayname'], ['src-appid', 'appid'], ['src-registry', 'registry'], ['src-silent', 'silent'], ['src-detect', 'detect']]) $('#' + id).textContent = src[key] || '';
    const procs = (form.ProcessesToKill || '').split(/[,;]/).map(p => p.trim()).filter(Boolean);
    $('#close-apps-hint').innerHTML = procs.length ? procs.map(p => `<span class="proc">${escapeHtml(p.replace(/\.exe$/i, ''))}.exe</span>`).join('') : '<span class="bnote">none detected</span>';
    renderManifest();
    renderChecksSummary();
  }
  function manifestLines() {
    // What the build will produce, in the order Intune uses it.
    const id = $('#f-appid').value.trim() || '-', name = $('#f-displayname').value.trim() || '-';
    const psadt = form.SimplePkgTarget === 'psadt', runtime = form.Mode === 'runtime';
    if (form.Kind === 'printer') {
      return [['package', `${id}  \u00b7  ${name}`], ['printer', $('#f-printername').value.trim() || '-', 'str'],
        ['driver', $('#f-drivername').value.trim() || $('#f-driverid').value || '-'], ['port', `${$('#f-porthost').value.trim() || '-'}:${$('#f-portnumber').value.trim() || '9100'}`, 'num'],
        ['install', 'Install-Printer.ps1 via the AppUpdater agent'], ['detect', 'printer exists with this driver and port', 'str'], ['output', `${id}/${id}.intunewin`, 'str']];
    }
    const file = window._selectedInstaller ? window._selectedInstaller.split(/[\\/]/).pop() : '-';
    const sw = $('#f-silentargs').value.trim(), reg = $('#f-registryname').value.trim() || '-', min = $('#f-detectversion').value.trim();
    const isMsi = /\.msi$/i.test(file), isMsix = window._installerType === 'MSIX', isZip = window._installerType === 'Zip';
    const lines = [['package', `${id}  \u00b7  ${name}${window._selectedVersion ? ' ' + window._selectedVersion : ''}`], ['source', file, 'str']];
    if (runtime) lines.push(['agent', `downloads ${$('#f-download-url').value.trim() || '[download URL]'}`, 'str'], ['  checks', 'on a schedule, installs newer versions', 'dim']);
    if (isMsix) lines.push(['install', 'Add-AppxProvisionedPackage, all users']);
    else if (isZip) lines.push(['install', `unpack to Program Files\\${id}, shortcut, ARP entry`]);
    else if (isMsi) lines.push(['install', `msiexec /i ${file} ${sw ? sw + ' ' : ''}/qn /norestart`]);
    else lines.push(['install', `${psadt ? 'Deploy-Application.ps1' : 'install.ps1'}  \u2192  ${file} ${sw || '[silent switch]'}`]);
    if (!runtime && !isMsi && !isMsix && !isZip) lines.push(['  waits', `until "${reg}" registers`, 'dim']);
    lines.push(runtime ? ['detect', `AppUpdater agent for ${id}`, 'str'] : isMsix ? ['detect', `provisioned package ${reg}`, 'str'] : ['detect', `ARP "${reg}"`, 'str']);
    if (!runtime && !isMsix) lines.push(['  version', min ? `\u2265 ${min}` : 'any', min ? 'num' : 'dim']);
    if (!runtime) lines.push(['uninstall', isMsi ? 'msiexec /x {product code}' : isMsix ? 'Remove-AppxProvisionedPackage' : 'QuietUninstallString, else the engine\'s switch']);
    const procs = (form.closeAppsOn && (psadt || runtime)) ? (form.ProcessesToKill || '').trim() : '';
    if (procs) lines.push(['closes', procs]);
    if (psadt) lines.push(['prompts', `PSADT ${form.PSADTVersion}${form.allowDefer ? ', users may postpone 3 times' : ', no postponing'}`]);
    lines.push(['runs as', window._perUser ? 'User (per-user installer)' : 'System']);
    const scripts = [['before', 'f-prehook'], ['after', 'f-posthook'], ['after removal', 'f-postuninstallhook']].filter(x => $('#' + x[1]).value.trim());
    if (scripts.length) lines.push(['scripts', scripts.map(x => x[0]).join(', ')]);
    if (form.RemoveOlderVersions && !runtime) lines.push(['removes', 'older side-by-side versions first']);
    const ver = (window._selectedVersion || '').replace(/[^A-Za-z0-9._-]/g, '_');
    lines.push(['output', psadt ? `${id}-Simple-PSADT-${form.PSADTVersion}${ver && !runtime ? '-' + ver : ''}/` : runtime ? `${id}/Deploy-${id}.intunewin` : `${id}-Simple${ver ? '-' + ver : ''}/${id}-Simple.intunewin`, 'str']);
    if (!runtime) lines.push(['epm', 'EPM-rules.csv  (installer hash and signer)', 'dim']);
    const prof = $('#f-profile').value;
    if (prof) lines.push(['profile', prof]);
    return lines;
  }
  function renderManifest() {
    const el = $('#manifest');
    if (!el) return;
    if (form.Kind !== 'printer' && !inspected) { el.innerHTML = '<div class="mline"><span class="n">1</span><span class="k">source</span><span class="v dim">pick an installer to see what will ship</span></div>'; return; }
    el.innerHTML = manifestLines().map((l, i) => `<div class="mline"><span class="n">${i + 1}</span><span class="k">${escapeHtml(l[0])}</span><span class="v ${l[2] || ''}">${escapeHtml(l[1])}</span></div>`).join('');
  }
  function renderChecksSummary() {
    const f = window._preview || null;
    let text;
    if (form.Kind === 'printer') text = 'Printer packages have no installer to check.';
    else if (!inspected) text = 'Select an installer to begin.';
    else if (!f) text = 'Checking the installer...';
    else {
      const red = f.filter(x => x.level === 'red').length, amber = f.filter(x => x.level === 'amber').length;
      text = !f.length ? 'All checks pass.' : [red && `${red} blocking`, amber && `${amber} to review`].filter(Boolean).join(' \u00b7 ') + (red ? ' \u00b7 the build will stop until you override' : ' \u00b7 nothing blocks this build');
    }
    $('#build-summary').textContent = text;
    $('#checks-state').textContent = form.Kind === 'printer' ? 'not used for printers' : !inspected ? 'pick an installer' : !f ? 'running' : f.length ? `${f.length} found` : 'all pass';
    const glyph = { red: '\u2715', amber: '\u25B2' };
    $('#checks-list').innerHTML = (f || []).map(x => `<div class="check ${x.level}"><span class="g" aria-hidden="true">${glyph[x.level] || '\u25CF'}</span><span>${escapeHtml(x.message)}</span></div>`).join('') ||
      (f && inspected ? '<div class="check ok"><span class="g" aria-hidden="true">\u2713</span><span>Signature, winget hash and version checks found nothing to review.</span></div>' : '');
  }
  function requestPreview() {
    // The same checks the build runs, worked out as soon as the installer is known.
    if (form.Kind === 'printer' || !inspected || !window._selectedInstaller) return;
    window._preview = null;
    renderChecksSummary();
    send('preflight-preview', { AppID: $('#f-appid').value.trim(), DisplayName: $('#f-displayname').value.trim(), InstallerPath: window._selectedInstaller,
      Version: window._selectedVersion || '', DetectVersion: $('#f-detectversion').value.trim(), Identity: window._identity || {}, Winget: window._wingetMatch || null });
  }
  function markSource(key, value) { window._src = Object.assign(window._src || {}, { [key]: value }); }
  $('#detect-any').addEventListener('click', () => { $('#f-detectversion').value = ''; markSource('detect', ''); updateSummary(); });
  $('#f-detectversion').addEventListener('input', () => { markSource('detect', 'edited'); updateSummary(); });
  $('#extras-toggle').addEventListener('click', () => { const p = $('#extras-panel'); p.hidden = !p.hidden; $('#extras-toggle').textContent = p.hidden ? 'Edit' : 'Done'; });
  for (const [id, key] of [['f-displayname', 'displayname'], ['f-appid', 'appid'], ['f-registryname', 'registry'], ['f-silentargs', 'silent']]) {
    $('#' + id).addEventListener('input', () => { markSource(key, 'edited'); updateSummary(); });
  }
  ['f-download-url', 'f-prehook', 'f-posthook', 'f-postuninstallhook', 'f-printername', 'f-drivername', 'f-porthost', 'f-portnumber'].forEach(id => $('#' + id).addEventListener('input', updateSummary));
  $('#f-profile').addEventListener('change', updateSummary);

  $('#progress-error-back').addEventListener('click', () => goTo('build'));
  $('#btn-build').addEventListener('click', () => {
    if (form.Kind === 'printer') {
      if (!$('#f-printername').value.trim()) { toast('Missing printer name', 'Fill in the printer name first'); return; }
      const driverId = $('#f-driverid').value.trim();
      if (driverId) {
        const libEntry = (window._driverLibrary || []).find(x => x.DriverID === driverId);
        if (libEntry && !libEntry.HasFiles) {
          toast('Driver files not yet supplied', `"${libEntry.DisplayName}" is metadata only - add the real driver package via "+ Add driver to library" first, or pick a different driver.`);
          return;
        }
      } else if (!$('#f-driversourcepath').value.trim() || !$('#f-driverinf').value.trim()) {
        toast('Missing driver', 'Pick a driver from the library, or fill in a driver source path and INF below');
        return;
      }
    } else if (!inspected) {
      toast('No installer', 'Drop or browse to an installer first'); return;
    } else if (!$('#f-silentargs').value.trim() && !/\.(msi|msix|msixbundle|appx|appxbundle|zip)$/i.test(window._selectedInstaller || '')) {
      toast('Silent switch needed', 'AppUpdater does not recognise this installer. Enter its silent install switch first.', true); return;
    }
    if (form.Kind !== 'printer') {
      const simpleOnly = form.Mode !== 'simple';
      if (/\.(msix|msixbundle|appx|appxbundle|zip)$/i.test(window._selectedInstaller || '') && (simpleOnly || form.SimplePkgTarget !== 'intunewin')) {
        toast('Simple .intunewin only', 'MSIX and zip packages build as a Simple Package with the .intunewin target.', true); return;
      }
      if (/\.zip$/i.test(window._selectedInstaller || '') && !window._entryExe) {
        toast('No program in the zip', 'AppUpdater found no program to run inside this zip.', true); return;
      }
      const minVersion = $('#f-detectversion').value.trim();
      if (!simpleOnly && minVersion && !/\d/.test(minVersion)) { toast('Minimum version', 'Enter a version number such as 8.6.9, or leave it empty.', true); return; }
      if (!simpleOnly && form.RemoveOlderVersions && !minVersion) { toast('Minimum version needed', 'Removing older versions needs the minimum version for detection. Run a local test to read it.', true); return; }
      if (simpleOnly && form.BundleFolder) { toast('Folder bundling is Simple only', 'Switch off "Bundle the whole folder" or choose Simple Package.', true); return; }
      if (simpleOnly && $('#f-silentargs').value.includes('{pkg}')) { toast('{pkg} is Simple only', 'Runtime packages download the installer on their own, so {pkg} has no folder to point at.', true); return; }
    }
    goTo('progress');
    $('#log').innerHTML = '';
    $('#progress-bar').style.width = '0%';
    $('#progress-title').textContent = $('#f-displayname').value || $('#f-printername').value || 'Package';
    $('#step-list').innerHTML = '';
    $('#progress-error').style.display = 'none';
    const payload = {
      AppID: $('#f-appid').value,
      DisplayName: $('#f-displayname').value,
      PackageKind: form.Kind === 'printer' ? 'Printer' : 'App',
      Mode: form.Mode,
      SimplePkgTarget: form.SimplePkgTarget,
      PSADTVersion: form.PSADTVersion,
      DownloadURL: $('#f-download-url').value.trim(),
      Version: window._selectedVersion || '',
      ProfileName: form.ProfileName,
      OverrideOrgName: window._overridePanelOpened ? $('#ov-orgname').value.trim() : '',
      OverrideLogoImagePath: window._overridePanelOpened ? $('#ov-logo').value.trim() : '',
      OverrideBannerImagePath: window._overridePanelOpened ? $('#ov-banner').value.trim() : ''
    };
    if (form.Kind === 'printer') {
      Object.assign(payload, {
        AppID: payload.AppID || $('#f-printername').value.trim().replace(/[^A-Za-z0-9._-]/g, ''),
        DisplayName: payload.DisplayName || $('#f-printername').value.trim(),
        PrinterName: $('#f-printername').value.trim(),
        DriverName: $('#f-drivername').value.trim(),
        DriverID: $('#f-driverid').value.trim(),
        DriverSourcePath: $('#f-driversourcepath').value.trim(),
        DriverInfRelativePath: $('#f-driverinf').value.trim(),
        ExpectedDriverPublisher: $('#f-driverpublisher').value.trim(),
        Location: $('#f-printerlocation').value.trim(),
        PortHostAddress: $('#f-porthost').value.trim(),
        PortNumber: $('#f-portnumber').value.trim()
      });
    } else {
      Object.assign(payload, {
        RegistryName: $('#f-registryname').value,
        InstallerPath: window._selectedInstaller,
        SilentArgs: $('#f-silentargs').value.trim(),
        Identity: window._identity || {},
        PreInstallHookPath: $('#f-prehook').value.trim(),
        PostInstallHookPath: $('#f-posthook').value.trim(),
        PostUninstallHookPath: $('#f-postuninstallhook').value.trim(),
        RemoveOlderVersions: !!form.RemoveOlderVersions,
        Winget: window._wingetMatch || null,
        DetectVersion: form.Mode === 'simple' && window._installerType !== 'MSIX' ? $('#f-detectversion').value.trim() : '',
        BundleFolder: !!form.BundleFolder,
        EntryExe: window._entryExe || '',
        PerUser: !!window._perUser,
        ProcessesToKill: form.closeAppsOn ? form.ProcessesToKill : '',
        AllowDefer: !!form.allowDefer,
        ExpectedPublisher: ''
      });
    }
    window._lastBuildPayload = payload;
    send('build-package', payload);
  });

  if (bridge) {
    bridge.addEventListener('message', (e) => {
      const { type, payload } = e.data;
      switch (type) {
        case 'browse-installer-result':
          if (payload.ok) {
            window._selectedVersion = payload.detected && payload.detected.version || '';
            window._selectedInstaller = payload.path;
            inspected = true;
            const base = payload.path.split(/[\\/]/).pop();
            const stem = base.replace(/\.(exe|msi|msix|msixbundle|appx|appxbundle|zip)$/i, '');
            const ext = (base.match(/\.(exe|msi|msix|msixbundle|appx|appxbundle|zip)$/i) || ['', 'exe'])[1].replace(/bundle$/i, '').toUpperCase();
            $('#drop').style.display = 'none';
            $('#inspect').style.display = 'block';
            $('#inspect-ext').textContent = ext;
            $('#inspect-name').textContent = base;
            $('#inspect-sub').textContent = payload.detected ? payload.detected.summary || '' : 'Inspecting…';
            $('#inspect-chips').innerHTML = (payload.detected && payload.detected.chips || []).map(chipHtml).join('');
            if (!$('#f-appid').value) $('#f-appid').value = (payload.detected && payload.detected.appId) || stem.replace(/[^A-Za-z0-9._-]/g, '');
            if (!$('#f-displayname').value) $('#f-displayname').value = (payload.detected && payload.detected.displayName) || stem;
            const registryWasEmpty = !$('#f-registryname').value;
            if (registryWasEmpty) $('#f-registryname').value = (payload.detected && payload.detected.registryName) || $('#f-displayname').value;
            $('#f-silentargs').value = (payload.detected && payload.detected.silentArgs) || '';
            window._autoSilentArgs = $('#f-silentargs').value;
            window._src = { displayname: 'installer', appid: 'installer', registry: 'installer', silent: $('#f-silentargs').value ? 'installer' : '', detect: '' };
            window._preview = null;
            window._entryExe = (payload.detected && payload.detected.entryExe) || '';
            window._perUser = !!(payload.detected && payload.detected.installerType === 'Squirrel');
            // null never equals a field value, so a name the user typed is never replaced later.
            window._autoRegistryName = registryWasEmpty ? $('#f-registryname').value : null;
            window._installerType = (payload.detected && payload.detected.installerType) || '';
            const det = payload.detected || {};
            window._knownAppliedFor = null;
            window._wingetMatch = null;
            window._identity = { name: det.displayName || '', publisher: det.publisher || '', upgradeCode: det.upgradeCode || '', installerVersion: det.version || '', wingetId: '' };
            // A minimum version belongs to one installer, unless a test suggestion set it for the installer being picked again.
            if (!window._keepDetectVersion) $('#f-detectversion').value = '';
            window._keepDetectVersion = false;
            window._knownBundle = false;
            form.BundleFolder = false;
            const bundleToggle = document.querySelector('.tgl[data-val="BundleFolder"]');
            bundleToggle.classList.remove('on');
            bundleToggle.disabled = true;
            $('#bundle-hint').textContent = 'Counting the files next to the installer...';
            form.ProcessesToKill = (payload.detected && payload.detected.processesToKill) || '';
            $('#close-apps-hint').textContent = form.ProcessesToKill || 'No blocking process detected';
            $('#btn-build').disabled = false;
            builderProgress();
            updateSummary();
            if (det.known) applyKnownApp(det.known);
            else if (!payload.detected) toast('Installer picked', 'Fill in the identity fields to continue');
          }
          break;
        case 'installer-winget-result': {
          if (payload.path !== window._selectedInstaller) break;
          const folder = payload.folder;
          const bundleOk = folder && !folder.isRoot && !folder.tooMany;
          document.querySelector('.tgl[data-val="BundleFolder"]').disabled = !bundleOk;
          $('#bundle-hint').textContent = !folder ? 'Include every file next to the installer (Simple packages only)'
            : folder.isRoot ? 'Not available: the installer is at the root of a drive'
            : folder.tooMany ? 'Not available: the folder holds more than 20,000 files'
            : `Include all ${folder.files} file(s), ${(folder.bytes / 1048576).toFixed(1)} MB, next to the installer (Simple packages only)`;
          const m = payload.match;
          const chips = [];
          if (m) {
            // Only replace values the user has not edited since inspection.
            if (m.Id && window._identity) window._identity.wingetId = m.Id;
            window._wingetMatch = { Id: m.Id, Version: m.Version, Match: m.Match, VersionMatch: !!m.VersionMatch, Latest: m.Latest || '', Files: m.Files || [] };
            if (m.SilentArgs && $('#f-silentargs').value === window._autoSilentArgs) { $('#f-silentargs').value = window._autoSilentArgs = m.SilentArgs; markSource('silent', 'winget'); }
            if (m.ArpName && window._installerType !== 'MSIX' && $('#f-registryname').value === window._autoRegistryName) { $('#f-registryname').value = window._autoRegistryName = m.ArpName; markSource('registry', 'winget'); updateSummary(); }
            const how = m.Match === 'hash' ? 'the exact file' : m.Match === 'productcode' ? 'the same product code' : (m.VersionMatch ? 'name and version' : 'name; its newest version is listed');
            const repoPath = `manifests/${m.Id.charAt(0).toLowerCase()}/${m.Id.split('.').join('/')}`;
            chips.push({ label: 'winget', tone: m.Match === 'name' ? '' : 'g', detail: `Matched ${m.Id} ${m.Version} in Microsoft's winget catalogue by ${how}. Its silent switch and registry name are used where you have not changed them.`, link: `https://github.com/microsoft/winget-pkgs/tree/master/${repoPath}`, linkLabel: 'Open in winget-pkgs' });
            if (m.Scope === 'user') { window._perUser = true; chips.push({ label: 'Per-user', tone: 'w', detail: 'winget lists this installer as per-user. Deploy it in Intune with install behaviour User.' }); }
            if (!m.SilentArgs && !$('#f-silentargs').value) chips.push({ label: 'No silent switch', tone: 'w', detail: 'Neither the installer nor winget gives a silent switch. Enter one below before building.' });
          } else if (payload.note) {
            const off = /lookups are off/.test(payload.note);
            chips.push({ label: off ? 'winget off' : /downloading/.test(payload.note) ? 'winget loading' : /not in the winget/.test(payload.note) ? 'Not in winget' : 'winget error',
                         detail: payload.note.charAt(0).toUpperCase() + payload.note.slice(1) + '.', link: off ? 'settings' : '', linkLabel: off ? 'Open settings' : '' });
          }
          $('#inspect-chips').insertAdjacentHTML('beforeend', chips.map(chipHtml).join(''));
          if (bundleOk && window._knownBundle) setToggle('BundleFolder', true);
          requestPreview();
          if (payload.known) applyKnownApp(payload.known);
          break;
        }
        case 'history-data':
          window._realHistoryEvents = payload.events || [];
          renderHistory(payload.events);
          renderRecentActivity(payload.events);
          break;
        case 'fleet-data':
          window._gotFleetData = true;
          window._workerUrl = payload.workerUrl;
          renderFleet(payload.apps);
          renderDeployFeedback(payload.feedbackDue);
          resetWorkerOptionsButtons();
          break;
        case 'driver-library-data':
          renderDriverLibrary(payload.drivers);
          break;
        case 'driver-added':
          $('#dl-save').disabled = false;
          if (payload.ok) {
            $('#dl-status').textContent = '';
            $('#driver-lib-add-panel').style.display = 'none';
            ['dl-id','dl-displayname','dl-manufacturer','dl-drivertype','dl-arch','dl-version','dl-source','dl-inf','dl-publisher','dl-models']
              .forEach(id => { $('#' + id).value = ''; });
            send('get-driver-library', {});
            toast('Driver added', (payload.entry && payload.entry.DisplayName) + ' is now in the library');
          } else {
            $('#dl-status').textContent = payload.message || 'Import failed.';
          }
          break;
        case 'builtin-families-imported':
          $('#driver-lib-import-builtin').disabled = false;
          $('#builtin-import-status').textContent = payload.ok
            ? `Done - ${payload.added} added, ${payload.updated} already present (${payload.total} total). Driver files still need supplying via "+ Add driver to library" before a build can use them.`
            : (payload.message || 'Import failed.');
          break;
        case 'config-data':
          window._defaultOrgName = payload.orgName || '';
          renderOrgNameSettingsSelect();
          updateBuildBrandingPreview();
          updateSummary();
          resetWorkerOptionsButtons();
          break;
        case 'build-progress': {
          const [stepNum] = String(payload.step).split('/').map(Number);
          const total = 5;
          $('#progress-bar').style.width = `${Math.min(100, (stepNum / total) * 100)}%`;
          renderStepList(payload.step, payload.label);
          logLine(payload.label, 'ac');
          break;
        }
        case 'winget-prepared': {
          if (!payload.ok || payload.nothing) { logTestLine(payload.message || 'Nothing to contribute.', payload.ok ? 'in' : 'wr'); break; }
          logTestLine(payload.summary, 'ac');
          const box = document.createElement('div');
          box.style.cssText = 'margin:8px 0;padding:10px;border:1px solid var(--edge);border-radius:var(--r-sm)';
          box.innerHTML = `<pre style="white-space:pre-wrap;font-size:11px;margin:0 0 8px">${escapeHtml(payload.preview)}</pre>
            <div class="hint" style="margin:0 0 6px">Submitted as a pull request to microsoft/winget-pkgs from your GitHub account, where Microsoft's checks and reviewers take over. A GitHub token with public_repo scope is needed once; wingetcreate keeps it, AppUpdater does not.</div>
            <div style="display:flex;gap:6px"><input class="field mono" type="password" id="winget-token" placeholder="GitHub token - only the first time"><button class="btn primary sm" id="winget-submit">Submit pull request</button></div>`;
          appendToTestLog(box);
          $('#winget-submit').addEventListener('click', () => {
            $('#winget-submit').disabled = true;
            logTestLine('Submitting with wingetcreate...', 'ac');
            send('winget-submit', { id: payload.id, token: $('#winget-token').value.trim() });
            $('#winget-token').value = '';
          });
          break;
        }
        case 'winget-submitted': {
          logTestLine(payload.message || (payload.ok ? 'Submitted.' : 'Submission failed.'), payload.ok ? 'ok' : 'wr');
          if (payload.prUrl) {
            const open = document.createElement('button');
            open.className = 'btn primary sm'; open.textContent = 'Open the pull request';
            open.addEventListener('click', () => send('open-pr', { url: payload.prUrl }));
            appendToTestLog(open);
          } else if (payload.needsToken && $('#winget-submit')) { $('#winget-submit').disabled = false; }
          break;
        }
        case 'preflight-preview-result':
          if (payload.path === window._selectedInstaller) { window._preview = payload.ok === false ? [] : (payload.findings || []); renderChecksSummary(); }
          break;
        case 'status-data': {
          const age = h => h == null ? null : h < 1 ? 'under 1 h old' : h < 48 ? `${Math.round(h)} h old` : `${Math.round(h / 24)} days old`;
          $('#sb-winget').innerHTML = payload.lookups ? (payload.wingetAge == null ? '<span class="dot off">\u25CF</span> winget index not downloaded yet' : `<span class="dot">\u25CF</span> winget index ${age(payload.wingetAge)}`) : '<span class="dot off">\u25CF</span> online lookups off';
          $('#sb-cisa').textContent = payload.lookups && payload.kevAge != null ? `CISA list ${age(payload.kevAge)}` : '';
          $('#sb-nvd').textContent = payload.lookups && payload.nvd ? 'NVD on' : '';
          $('#sb-mode').textContent = payload.connected ? 'Cloudflare connected' : 'Offline \u00b7 local manifest';
          $('#sb-version').textContent = payload.version ? 'v' + payload.version : '';
          break;
        }
        case 'browse-script-result':
          if (payload.ok && /^f-(prehook|posthook|postuninstallhook)$/.test(payload.field)) $('#' + payload.field).value = payload.path;
          break;
        case 'preflight-blocked': {
          const list = (payload.findings || []).map(f => `<li style="margin:4px 0;color:${f.level === 'red' ? 'var(--bad)' : 'var(--warn)'}">${escapeHtml(f.message)}</li>`).join('');
          $('#step-list').innerHTML = `<div class="phase doing"><span class="pi"><svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg></span>Pre-deploy checks &middot; stopped</div>`;
          $('#progress-error-title').textContent = 'Build stopped by pre-deploy checks';
          $('#progress-error-msg').innerHTML = `<div>Pre-deploy checks found a problem with this installer. Check where it came from before deploying it.</div><ul style="margin:8px 0 0 18px;padding:0">${list}</ul>
            <button class="btn danger sm" id="preflight-override" style="margin-top:10px">Build anyway</button>`;
          $('#progress-error').style.display = 'block';
          $('#preflight-override').addEventListener('click', () => {
            if (!window._lastBuildPayload) return;
            $('#progress-error').style.display = 'none';
            send('build-package', Object.assign({}, window._lastBuildPayload, { OverrideRed: true }));
          });
          break;
        }
        case 'build-log':
          logLine(payload.line, 'in');
          break;
        case 'build-done':
          window._lastBuiltAppId = $('#f-appid').value;
          $('#done-deployed').disabled = false;
          $('#progress-bar').style.width = '100%';
          $('#done-path').textContent = payload.path || '';
          renderDoneSheet(payload);
          goTo('done');
          toast('Package ready', 'Built — check the output folder or view it in the fleet');
          if (payload.warning) toast('Worker sync pending', payload.warning, true);
          if (window._overridePanelOpened && form.ProfileName) {
            const ovP = (window._profiles || []).find(pp => pp.Name === form.ProfileName);
            if (ovP) {
              const newOrg = $('#ov-orgname').value.trim();
              const newLogo = $('#ov-logo').value.trim();
              const newBanner = $('#ov-banner').value.trim();
              const changed = newOrg !== (ovP.OrgName || '') || newLogo !== (ovP.LogoImagePath || '') || newBanner !== (ovP.BannerImagePath || '');
              if (changed && confirm('Save these overridden fields to the "' + ovP.Name + '" profile for future builds?')) {
                send('save-profile', { Name: ovP.Name, OrgName: newOrg, LogoImagePath: newLogo, BannerImagePath: newBanner, DefaultTarget: ovP.DefaultTarget || 'intunewin' });
              }
            }
            window._overridePanelOpened = false;
          }
          resetInstaller();
          break;
        case 'error':
          toast('Something went wrong', payload.message, true);
          resetWorkerOptionsButtons();
          if ($('#screen-progress').classList.contains('on')) {
            $('#progress-error-title').textContent = 'Build failed';
            $('#progress-error-msg').textContent = payload.message || 'Unknown error.';
            $('#progress-error').style.display = 'block';
          }
          break;
        case 'profiles-data':
          window._profiles = payload.profiles || [];
          window._lastUsedProfile = payload.lastUsed;
          renderProfiles(payload.profiles || [], payload.lastUsed);
          renderOrgNameSettingsSelect();
          if (payload.saveOk === false) toast('Save failed', 'Could not write profiles.json', true);
          else if (payload.saveOk === true) {
            toast('Profile saved', '');
            if (window._returnToBuildAfterProfile) {
              window._returnToBuildAfterProfile = false;
              const savedName = window._lastSavedProfileName;
              goTo('build');
              if (savedName) {
                form.ProfileName = savedName;
                $('#f-profile').value = savedName;
                $('#build-override-toggle').style.display = 'inline-flex';
                refreshBuildProfileImage();
                updateSummary();
              }
            }
          }
          renderGettingStarted();
          break;
        case 'browse-image-result':
          if (payload.ok) {
            $('#' + payload.field).value = payload.path;
            setImagePreview(payload.field, payload.dataUrl);
            if (payload.field === 'ov-logo') { window._bpLogoDataUrl = payload.dataUrl; updateBuildBrandingPreview(); }
            else if (payload.field === 'ov-banner') { window._bpBannerDataUrl = payload.dataUrl; updateBuildBrandingPreview(); }
          }
          break;
        case 'image-preview-result':
          if (payload.field === 'bp-logo') { window._bpLogoDataUrl = payload.dataUrl; updateBuildBrandingPreview(); }
          else if (payload.field === 'bp-banner') { window._bpBannerDataUrl = payload.dataUrl; updateBuildBrandingPreview(); }
          else if (payload.field === 'pf-logo') { window._pfLogoDataUrl = payload.dataUrl; updateProfilePreview(); }
          else if (payload.field === 'pf-banner') { window._pfBannerDataUrl = payload.dataUrl; updateProfilePreview(); }
          else setImagePreview(payload.field, payload.dataUrl);
          break;
        case 'psadt-stock-assets':
          window._psadtStockAssets = payload.ok ? { banner: payload.banner, icon: payload.icon } : null;
          updateProfilePreview();
          updateBuildBrandingPreview();
          break;
        case 'settings-data':
          window._defaultOrgName = payload.orgName || '';
          renderOrgNameSettingsSelect();
          window._modeExplainerSeen = !!payload.modeExplainerSeen;
          updateBuildBrandingPreview();
          updateSummary();
          $('#tgl-reduce-motion').classList.toggle('on', !!payload.reduceMotion);
          document.body.classList.toggle('reduce-motion', !!payload.reduceMotion);
          $('#tgl-high-contrast').classList.toggle('on', !!payload.highContrast);
          document.body.classList.toggle('high-contrast', !!payload.highContrast);
          $('#tgl-colorblind').classList.toggle('on', !!payload.colorblindSafe);
          document.body.classList.toggle('colorblind-safe', !!payload.colorblindSafe);
          $('#tgl-release-check').classList.toggle('on', !!payload.releaseCheckEnabled);
          $('#tgl-nvd').classList.toggle('on', !!payload.nvdEnabled);
          $('#tgl-cf-advert').classList.toggle('on', payload.showCloudflareAdvert !== false);
          window._showCfAdvert = payload.showCloudflareAdvert !== false;
          $('#tgl-getting-started').classList.toggle('on', payload.showGettingStarted !== false);
          window._showGettingStarted = payload.showGettingStarted !== false;
          $('#tgl-cf-nav').classList.toggle('on', payload.showCloudflareNav !== false);
          window._showCfNav = payload.showCloudflareNav !== false;
          applyCfNavVisibility();
          renderFleet(lastFleet);
          renderGettingStarted();
          if (!payload.onboardingSeen && !window._tourAutoStarted) {
            window._tourAutoStarted = true;
            setTimeout(startTour, 600);
          }
          $('#settings-version').textContent = 'AppUpdater v' + payload.version + ' - BUSL-1.1';
          $('#settings-release').textContent = payload.releaseInfo || '';
          
          if (payload.newerAvailable && !sessionStorage.getItem('releaseBannerDismissed')) {
            $('#release-banner-text').textContent = 'v' + payload.latestVersion + ' is available on GitHub';
            $('#release-banner').style.display = 'flex';
          }
          break;
        case 'settings-saved':
          if (!payload.ok) toast('Save failed', 'Could not write the config file.', true);
          send('get-status', {});
          break;
        case 'recovery-export-result':
          toast(payload.ok ? 'Bundle exported' : 'Export failed', payload.ok ? payload.path : 'Bundle could not be written.', !payload.ok);
          break;
        case 'recovery-import-result':
          toast(payload.ok ? 'Restored' : 'Restore failed', payload.ok ? 'Restart AppUpdater for everything to reload cleanly.' : payload.message, !payload.ok);
          break;
        case 'remove-from-fleet-result':
          if (payload.cancelled) { /* user cancelled the delete-choice dialog, nothing to report */ }
          else if (payload.ok) toast('Removed', payload.everything ? 'Manifest entry and local machine artifacts removed.' : 'Manifest entry removed.');
          else toast('Remove failed', payload.message || 'Could not update the manifest.', true);
          break;
        case 'test-log':
          if (payload.line) logTestLine(payload.line);
          if (payload.done) logTestLine(payload.ok ? '\u2713 Done' : '\u2717 Failed', payload.ok ? 'ok' : 'wr');
          if (payload.done && payload.suggestedRegistryName) {
            addTestFix(`Use "${payload.suggestedRegistryName}" as the registry name`, () => {
              $('#f-registryname').value = payload.suggestedRegistryName;
              markSource('registry', 'local test');
              window._autoRegistryName = null;
              toast('Registry name updated', inspected ? 'Build again to package with the detected name.' : 'Pick the installer again, then build.');
            });
          }
          if (payload.done && payload.ok && payload.wingetOffer) {
            const contribute = document.createElement('button');
            contribute.className = 'btn sm';
            contribute.textContent = 'Contribute what this test verified to winget';
            contribute.addEventListener('click', () => { contribute.disabled = true; logTestLine('Checking what winget is missing...', 'ac'); send('winget-prepare', { id: currentTestId }); });
            appendToTestLog(contribute);
          }
          if (payload.done && payload.suggestedDetectVersion) {
            addTestFix(`Require version ${payload.suggestedDetectVersion} or newer`, () => {
              $('#f-detectversion').value = payload.suggestedDetectVersion;
              markSource('detect', 'local test');
              window._keepDetectVersion = !inspected;
              toast('Minimum version set', inspected ? 'Build again so detection requires this version.' : 'Pick the installer again, then build.');
            });
          }
          break;
      }
    });
  }

  function renderDeployFeedback(due) {
    // Asked once per launch; "Later" asks again next time.
    window._feedbackAnswered = window._feedbackAnswered || new Set();
    const items = (Array.isArray(due) ? due : []).filter(d => !window._feedbackAnswered.has(d.id));
    $('#deploy-feedback').style.display = items.length ? 'block' : 'none';
    $('#deploy-feedback-list').innerHTML = items.map(d => `
      <div style="display:flex;align-items:center;gap:8px;padding:6px 0">
        <span style="flex:1"><b style="font-weight:600">${escapeHtml(d.name)}</b> <span class="mono">${escapeHtml(d.version || '')}</span></span>
        <button class="btn sm" data-feedback="${escapeHtml(d.id)}" data-outcome="ok">Yes</button>
        <button class="btn sm danger" data-feedback="${escapeHtml(d.id)}" data-outcome="failed">No</button>
        <button class="btn ghost sm" data-feedback="${escapeHtml(d.id)}" data-outcome="later">Later</button>
      </div>`).join('');
    $('#deploy-feedback-list').querySelectorAll('[data-feedback]').forEach(b => b.addEventListener('click', () => {
      window._feedbackAnswered.add(b.dataset.feedback);
      if (b.dataset.outcome !== 'later') send('deploy-feedback', { id: b.dataset.feedback, outcome: b.dataset.outcome });
      if (b.dataset.outcome === 'failed') toast('Noted', 'The next package of this app will show a warning before it is built.');
      renderDeployFeedback(items);
    }));
  }
  function chipHtml(c) {
    const detail = c.detail ? ` data-detail="${escapeHtml(c.detail)}" data-link="${escapeHtml(c.link || '')}" data-link-label="${escapeHtml(c.linkLabel || '')}" tabindex="0" role="button"` : '';
    return `<span class="chip ${escapeHtml(c.tone || '')}${c.detail ? ' has-detail' : ''}"${detail}><i></i>${escapeHtml(c.label)}</span>`;
  }
  function showChipDetail(chip) {
    const pop = $('#chip-pop');
    if (pop.dataset.for === chip.textContent && !pop.hidden) { pop.hidden = true; return; }
    pop.dataset.for = chip.textContent;
    $('#chip-pop-text').textContent = chip.dataset.detail;
    const link = $('#chip-pop-link');
    link.hidden = !chip.dataset.link;
    link.textContent = chip.dataset.linkLabel || 'Open';
    link.dataset.link = chip.dataset.link;
    const r = chip.getBoundingClientRect();
    pop.style.left = Math.max(8, Math.min(r.left, window.innerWidth - 340)) + 'px';
    pop.style.top = (r.bottom + 6) + 'px';
    pop.hidden = false;
  }
  document.addEventListener('click', e => {
    const chip = e.target.closest('.chip.has-detail');
    if (chip) { showChipDetail(chip); return; }
    if (!e.target.closest('#chip-pop')) $('#chip-pop').hidden = true;
  });
  document.addEventListener('keydown', e => {
    const chip = e.target.closest && e.target.closest('.chip.has-detail');
    if (chip && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); showChipDetail(chip); }
    if (e.key === 'Escape') $('#chip-pop').hidden = true;
  });
  $('#chip-pop-link').addEventListener('click', () => {
    const link = $('#chip-pop-link').dataset.link;
    $('#chip-pop').hidden = true;
    if (link === 'settings') goTo('worker'); else if (link) send('open-link', { url: link });
  });
  $('#done-test').addEventListener('click', () => {
    // Finishing a build leads straight to testing it.
    goTo('fleet');
    send('get-fleet', {});
    openTestModal(window._lastBuiltAppId);
  });
  $('#done-deployed').addEventListener('click', () => {
    send('mark-deployed', { id: window._lastBuiltAppId });
    $('#done-deployed').disabled = true;
    toast('Marked deployed', 'AppUpdater will ask on a later launch whether it installed correctly.');
  });
  function setToggle(key, on) {
    form[key] = !!on;
    const t = document.querySelector(`.tgl[data-val="${key}"]`);
    if (t) t.classList.toggle('on', form[key]);
  }
  function pickSeg(id, val) {
    const b = val && document.querySelector(`#${id} button[data-val="${val}"]`);
    if (b && !b.classList.contains('on')) b.click();
  }
  function applyKnownApp(k) {
    // Restores the settings of the last build of this app, once per picked installer.
    if (!k || window._knownAppliedFor === window._selectedInstaller) return;
    window._knownAppliedFor = window._selectedInstaller;
    const s = k.settings || {};
    $('#f-appid').value = k.appId;
    if (s.DisplayName) $('#f-displayname').value = s.DisplayName;
    if (s.RegistryName) {
      // Registry names often carry the version ("7-Zip 24.08 (x64)"); the new installer registers its own.
      const oldV = [k.lastVersion, k.lastInstallerVersion].find(v => v && s.RegistryName.includes(v));
      $('#f-registryname').value = oldV && window._selectedVersion ? s.RegistryName.split(oldV).join(window._selectedVersion) : s.RegistryName;
      window._autoRegistryName = null;
    }
    if (s.SilentArgs) { $('#f-silentargs').value = s.SilentArgs; window._autoSilentArgs = null; }
    window._src = Object.assign(window._src || {}, { appid: 'last build', displayname: s.DisplayName ? 'last build' : (window._src || {}).displayname,
      registry: s.RegistryName ? 'last build' : (window._src || {}).registry, silent: s.SilentArgs ? 'last build' : (window._src || {}).silent });
    if (s.DownloadURL && $('#f-download-url')) $('#f-download-url').value = s.DownloadURL;
    pickSeg('segMode', s.Mode);
    pickSeg('segTarget', s.SimplePkgTarget);
    if (s.PSADTVersion) pickSeg('segPsadtVersion', s.PSADTVersion);
    const prof = $('#f-profile');
    if (s.ProfileName !== undefined && prof && [...prof.options].some(o => o.value === s.ProfileName) && prof.value !== s.ProfileName) {
      prof.value = s.ProfileName; prof.dispatchEvent(new Event('change'));
    }
    if (s.ProcessesToKill) { form.ProcessesToKill = s.ProcessesToKill; $('#close-apps-hint').textContent = s.ProcessesToKill; }
    setToggle('closeAppsOn', !!s.ProcessesToKill || !form.ProcessesToKill);
    setToggle('allowDefer', s.AllowDefer !== false);
    window._knownBundle = !!s.BundleFolder;
    setToggle('RemoveOlderVersions', !!s.RemoveOlderVersions);
    for (const [field, key] of [['f-prehook', 'PreInstallHookPath'], ['f-posthook', 'PostInstallHookPath'], ['f-postuninstallhook', 'PostUninstallHookPath']]) {
      if (s[key]) $('#' + field).value = s[key];
    }
    if (s.PerUser) window._perUser = true;
    // The same version scheme as last time means the new installer's version is what the app will register.
    if (!$('#f-detectversion').value && k.lastDetectVersion && k.lastDetectVersion === k.lastInstallerVersion && window._selectedVersion) {
      $('#f-detectversion').value = window._selectedVersion;
    }
    const when = k.lastBuiltAt ? new Date(k.lastBuiltAt).toLocaleDateString() : '';
    const same = k.lastVersion && k.lastVersion === window._selectedVersion;
    $('#inspect-chips').insertAdjacentHTML('beforeend', chipHtml({ label: same ? 'Same version' : 'Known app', tone: same ? 'w' : 'g',
      detail: `Packaged before${k.lastVersion ? ' as ' + k.lastVersion : ''}${when ? ' on ' + when : ''}; its settings are filled in.${same ? ' This installer is the same version as that package.' : ''}` }));
    updateSummary();
  }

  function addTestFix(label, apply) {
    // Loads the tested app into the build form, then applies the suggestion.
    const fix = document.createElement('button');
    fix.className = 'btn primary sm';
    fix.textContent = label;
    const testedApp = lastFleet.find(a => a.id === currentTestId);
    fix.addEventListener('click', () => {
      $('#test-modal').style.display = 'none';
      goTo('build');
      if (testedApp && $('#f-appid').value !== testedApp.id) {
        resetInstaller();
        $('#f-appid').value = testedApp.id;
        $('#f-displayname').value = testedApp.name;
      }
      apply();
      updateSummary();
    });
    appendToTestLog(fix);
  }

  function renderProfiles(profiles, lastUsed) {
    const grid = $('#profiles-strip');
    const sel = $('#f-profile');
    sel.innerHTML = '<option value="">Default (uses Settings organisation name)</option>' +
      profiles.map(function(p){ return '<option value="' + escapeHtml(p.Name) + '">' + escapeHtml(p.Name) + '</option>'; }).join('');
    grid.innerHTML = profiles.map(function(p){
      var active = p.Name === editingProfile ? ' style="border-color:var(--signal);color:var(--signal)"' : '';
      return '<button class="btn sm" data-edit-profile="' + escapeHtml(p.Name) + '"' + active + '>' + escapeHtml(p.Name) +
        (p.Name === lastUsed ? ' <span style="color:var(--faint);font-size:10px">&middot; last used</span>' : '') + '</button>';
    }).join('') +
      '<button class="btn sm primary" id="new-profile-card">+ New profile</button>';
  }
  function renderOrgNameSettingsSelect() {
    const sel = $('#f-orgname-settings');
    if (!sel) return;
    const current = window._defaultOrgName || '';
    const profiles = window._profiles || [];
    let html = '<option value="">Not set</option>' +
      profiles.map(function(p){ return '<option value="' + escapeHtml(p.OrgName) + '">' + escapeHtml(p.Name) + ' (' + escapeHtml(p.OrgName || 'no org name set') + ')</option>'; }).join('');
    if (current && !profiles.some(function(p){ return p.OrgName === current; })) {
      html += '<option value="' + escapeHtml(current) + '">' + escapeHtml(current) + ' (custom)</option>';
    }
    sel.innerHTML = html;
    sel.value = current;
    $('#f-orgname-not-set-hint').style.display = current ? 'none' : 'block';
  }

  var editingProfile = null;
  function setImagePreview(field, dataUrl) {
    var img = $('#' + field + '-preview'), placeholder = $('#' + field + '-placeholder');
    if (!img) return;
    if (dataUrl) { img.src = dataUrl; img.style.display = 'block'; if (placeholder) placeholder.style.display = 'none'; }
    else { img.style.display = 'none'; img.removeAttribute('src'); if (placeholder) placeholder.style.display = ''; }
  }
  function openProfileEditor(p) {
    editingProfile = p ? p.Name : null;
    $('#pf-editing-label').textContent = p ? 'editing: ' + p.Name : 'new profile';
    $('#pf-delete').style.display = p ? 'inline-flex' : 'none';
    $('#pf-name').value = p ? p.Name : '';
    $('#pf-name').disabled = !!p;
    $('#pf-orgname').value = p ? p.OrgName || '' : '';
    $('#pf-logo').value = p ? p.LogoImagePath || '' : '';
    $('#pf-banner').value = p ? p.BannerImagePath || '' : '';
    var target = p ? p.DefaultTarget || 'intunewin' : 'intunewin';
    $$('#pf-target-seg button').forEach(function(b){ b.classList.toggle('on', b.dataset.val === target); });
    window._pfLogoDataUrl = null;
    window._pfBannerDataUrl = null;
    if (p && p.LogoImagePath) send('get-image-preview', { field: 'pf-logo', path: p.LogoImagePath });
    if (p && p.BannerImagePath) send('get-image-preview', { field: 'pf-banner', path: p.BannerImagePath });
    updateProfilePreview();
    renderProfiles(window._profiles || [], window._lastUsedProfile);
  }
  function updateProfilePreview() {
    const name = $('#pf-name').value.trim() || 'Example App';
    const org = $('#pf-orgname').value.trim() || 'Acme Corp';
    const shown = window._pfSwapVersion || 'v3';
    $('#pf-preview-v3').style.display = shown === 'v3' ? 'block' : 'none';
