function Import-BuiltInDriverFamilies {
  $data = Get-DriverLibrary
  # Existing order first, then new families, so reruns produce no diff.
  $builtInById = @{}
  foreach ($f in $script:BuiltInPrinterDriverFamilies) { $builtInById[$f.DriverID] = $f }

  $merged = [System.Collections.Generic.List[hashtable]]::new()
  $seen = @{}
  $updated = 0
  foreach ($d in @($data.Drivers)) {
    $seen[$d.DriverID] = $true
    $f = $builtInById[$d.DriverID]
    if ($f) {
      $updated++
      $merged.Add(@{
        DriverID = $f.DriverID; DisplayName = $f.DisplayName; Manufacturer = $f.Manufacturer
        DriverType = $d.DriverType; Architecture = $d.Architecture
        InfRelativePath = $f.InfRelativePath
        ExpectedPublisher = $d.ExpectedPublisher; Version = $d.Version
        DateAdded = $d.DateAdded; SourceURL = $d.SourceURL
        Models = $f.Models
      })
    } else {
      $merged.Add($d)
    }
  }

  $added = 0
  foreach ($f in $script:BuiltInPrinterDriverFamilies) {
    if ($seen[$f.DriverID]) { continue }
    $added++
    $merged.Add(@{
      DriverID = $f.DriverID; DisplayName = $f.DisplayName; Manufacturer = $f.Manufacturer
      DriverType = ''; Architecture = ''
      InfRelativePath = $f.InfRelativePath
      ExpectedPublisher = ''; Version = ''
      DateAdded = (Get-Date -Format 'yyyy-MM-dd'); SourceURL = ''
      Models = $f.Models
    })
  }

  $data.Drivers = @($merged)
  if (-not (Write-DriverLibrary -Data $data)) { throw 'Failed to write driverLibrary.json' }
  return @{ Added = $added; Updated = $updated; Total = $merged.Count }
}

function Get-ImageDataUrl {
  param([string]$Path)
  if (-not $Path -or -not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
  try {
    $ext = [System.IO.Path]::GetExtension($Path).ToLowerInvariant()
    $mime = switch ($ext) {
      '.png'  { 'image/png' }
      '.jpg'  { 'image/jpeg' }
      '.jpeg' { 'image/jpeg' }
      '.svg'  { 'image/svg+xml' }
      default { $null }
    }
    if (-not $mime) { return $null }
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -gt 5MB) { return $null }
    return "data:$mime;base64,$([Convert]::ToBase64String($bytes))"
  } catch { return $null }
}

function Set-DeployStatus {
  param([string]$AppID, [string]$AppName, [string]$Target, [string]$ProfileName, [string]$OutputDir, [switch]$MarkDeployed)
  $store = Get-DeployStatusStore
  Get-DeployHistory | Out-Null
  if (-not $store.ContainsKey($AppID)) { $store[$AppID] = @{} }
  if ($MarkDeployed) {
    $store[$AppID]['deployedAt'] = (Get-Date -Format 'o')
  } else {
    $store[$AppID]['builtAt'] = (Get-Date -Format 'o')
    $store[$AppID]['name'] = $AppName
    $store[$AppID]['target'] = $Target
    $store[$AppID]['profile'] = $ProfileName
    $store[$AppID]['outputDir'] = $OutputDir
    $store[$AppID]['deployedAt'] = $null
  }
  Save-DeployStatusStore -Store $store
  Add-DeployHistoryEvent -AppID $AppID -AppName $AppName -Event $(if ($MarkDeployed) { 'deployed' } else { 'built' }) -Target $store[$AppID]['target'] -ProfileName $store[$AppID]['profile']
}

function Get-FleetPayload {
  param([hashtable]$Config)
  $manifestResult = Get-LocalManifest -XmlFile $ManifestPath
  $deployStore = Get-DeployStatusStore
  # @(...) around the whole if/else so an empty result serializes as [] rather than {}.
  $fleet = @(if ($manifestResult.Ok) {
    @($manifestResult.Apps | ForEach-Object {
      $id = $_.ID
      $ds = if ($deployStore.ContainsKey($id)) { $deployStore[$id] } else { $null }
      $status = if (-not $ds) { 'unknown' }
                elseif ($ds.deployedAt) { 'deployed' }
                else { 'built - not deployed' }
      @{
        id = $id; name = $_.DisplayName; version = $_.Version
        type = if ($ds -and $ds.target) { $ds.target } else { 'runtime' }
        profile = if ($ds) { $ds.profile } else { '' }
        status = $status
        builtAt = if ($ds) { $ds.builtAt } else { '' }
        outputDir = if ($ds) { $ds.outputDir } else { '' }
      }
    })
  } else {
    Write-AppLog "get-fleet: $($manifestResult.Reason)" WARN
    @()
  })
  $manifestIds = @{}
  foreach ($app in $fleet) { $manifestIds[$app.id] = $true }
  foreach ($id in $deployStore.Keys) {
    if (-not $manifestIds.ContainsKey($id)) {
      $ds = $deployStore[$id]
      $fleet += @{
        id = $id; name = $(if ($ds.name) { $ds.name } else { $id }); version = ''
        type = $ds.target; profile = $ds.profile; builtAt = $ds.builtAt; outputDir = $ds.outputDir
        status = $(if ($ds.deployedAt) { 'deployed' } else { 'built - not deployed' })
      }
    }
  }
  $memory = try { Get-AppMemory } catch { @{} }
  $feedbackDue = @(foreach ($id in $deployStore.Keys) {
    $ds = $deployStore[$id]; $mem = $memory[$id]
    if (-not $ds.deployedAt -or -not $mem -or -not $script:SessionStartedAt) { continue }
    $last = @($mem.builds)[-1]
    $deployedAt = [datetime]::MinValue
    if (-not $last -or $last.deployOutcome -or -not [datetime]::TryParse([string]$ds.deployedAt, [ref]$deployedAt)) { continue }
    if ($deployedAt -lt $script:SessionStartedAt) { @{ id = $id; name = $(if ($ds.name) { $ds.name } else { $id }); version = [string]$last.version } }
  })
  $indexPath = if ($WingetCacheDir) { Join-Path $WingetCacheDir 'index.db' } else { '' }
  $useWinget = $indexPath -and -not $Config.DisableReleaseCheck -and (Test-Path -LiteralPath $indexPath)
  foreach ($app in $fleet) {
    $mem = $memory[$app.id]
    if (-not $mem) { continue }
    $last = @($mem.builds)[-1]
    if (-not $app.version -and $last) { $app.version = [string]$last.version }
    if ($useWinget -and $mem.keys.wingetId) {
      try {
        $latest = Get-WingetLatestVersion -Id ([string]$mem.keys.wingetId) -IndexPath $indexPath
        $have = ConvertTo-LooseVersion $app.version
        if ($latest -and $have -and (ConvertTo-LooseVersion $latest) -gt $have) { $app.newerVersion = $latest; $app.wingetId = [string]$mem.keys.wingetId }
      } catch { Write-AppLog "winget version check for $($app.id) failed: $($_.Exception.Message)" WARN }
    }
  }
  @{ apps = @($fleet); workerUrl = $Config.WorkerURL; feedbackDue = $feedbackDue }
}

function Set-DeployOutcome {
  # Records whether the last package of an app installed correctly; a failure becomes a pre-deploy warning next time.
  param([string]$AppID, [ValidateSet('ok', 'failed')][string]$Outcome)
  $store = Get-AppMemory
  $app = $store[$AppID]
  if (-not $app -or -not @($app.builds).Count) { return }
  $builds = @($app.builds)
  $builds[-1].deployOutcome = $Outcome
  $builds[-1].deployOutcomeAt = (Get-Date -Format 'o')
  $app.builds = $builds
  Write-AtomicText -Path $AppMemoryFile -Text ($store | ConvertTo-Json -Depth 8)
}

function Set-AppMemoryTestResult {
  # Keeps what a passing local test saw in Add/Remove Programs; returns whether the app has a winget package to contribute to.
  param([string]$AppID, [hashtable]$Registered)
  $store = Get-AppMemory
  $app = $store[$AppID]
  if (-not $app -or -not @($app.builds).Count) { return $false }
  $builds = @($app.builds)
  $builds[-1].registered = $Registered
  $builds[-1].testedAt = (Get-Date -Format 'o')
  $app.builds = $builds
  Write-AtomicText -Path $AppMemoryFile -Text ($store | ConvertTo-Json -Depth 8)
  return [bool]$app.keys.wingetId
}

function Start-BackgroundAction {
  # Runs $Script with the engine functions it needs off the UI thread, then sends $_result to the page as $Event.
  param($Wv, [string[]]$Roots, [hashtable]$Variables, [string]$Script, [string]$Event, [scriptblock]$OnDone, [int]$TimeoutSeconds = 900)
  $result = [hashtable]::Synchronized(@{})
  $rs = [runspacefactory]::CreateRunspace(); $rs.Open()
  foreach ($key in $Variables.Keys) { $rs.SessionStateProxy.SetVariable($key, $Variables[$key]) }
  $rs.SessionStateProxy.SetVariable('_result', $result)
  $ps = [powershell]::Create(); $ps.Runspace = $rs
  $body = (Get-BuildFunctionSource -Roots $Roots) + "`nfunction Write-AppLog { param([string]`$Message, [string]`$Level) }`ntry {`n$Script`n} catch { `$_result.ok = `$false; `$_result.message = `$_.Exception.Message }"
  [void]$ps.AddScript($body)
  $handle = $ps.BeginInvoke()
  $started = [Diagnostics.Stopwatch]::StartNew()
  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(300)
  $timer.Add_Tick({
    if (-not $handle.IsCompleted -and $started.Elapsed.TotalSeconds -lt $TimeoutSeconds) { return }
    $timer.Stop()
    if (-not $handle.IsCompleted) { $result.ok = $false; $result.message = 'Timed out.'; $ps.BeginStop($null, $null) | Out-Null }
    else { try { $ps.EndInvoke($handle) | Out-Null } catch { $result.ok = $false; $result.message = $_.Exception.Message }; $ps.Dispose(); $rs.Dispose() }
    if ($OnDone) { & $OnDone $result }
    Send-ToPage $Wv $Event ([hashtable]$result)
  }.GetNewClosure())
  $timer.Start()
}

function Get-WingetLatestVersion {
  param([string]$Id, [string]$IndexPath)
  $rows = Invoke-WingetQuery -IndexPath $IndexPath -Arguments @($Id) -Sql 'select v.version from manifest m join ids i on i.rowid = m.id join versions v on v.rowid = m.version where i.id = ?1'
  $best = $null; $bestText = ''
  foreach ($row in @($rows)) {
    $v = ConvertTo-LooseVersion ([string]$row[0])
    if ($v -and (-not $best -or $v -gt $best)) { $best = $v; $bestText = [string]$row[0] }
  }
  return $bestText
}

$window = New-Object System.Windows.Window
$window.Title           = 'AppUpdater'
$workArea = [System.Windows.SystemParameters]::WorkArea
$window.Width           = [Math]::Min(1280, $workArea.Width - 40)
$window.Height          = [Math]::Min(800, $workArea.Height - 40)
$window.MinWidth        = 860
$window.MinHeight       = 640
$window.WindowStyle     = 'None'
$window.ResizeMode      = 'CanResize'
$window.AllowsTransparency = $false
$window.Background      = [System.Windows.Media.Brushes]::Black
$window.WindowStartupLocation = 'CenterScreen'

# GlassFrameThickness=0 removes a white strip WPF draws on borderless windows.
$chrome = New-Object System.Windows.Shell.WindowChrome
$chrome.CaptionHeight = 0
$chrome.GlassFrameThickness = New-Object System.Windows.Thickness(0)
$chrome.ResizeBorderThickness = New-Object System.Windows.Thickness(5)
[System.Windows.Shell.WindowChrome]::SetWindowChrome($window, $chrome)

Add-Type -Name Win32Drag -Namespace AppUpdater -MemberDefinition @'
[DllImport("user32.dll")] public static extern bool ReleaseCapture();
[DllImport("user32.dll")] public static extern int SendMessage(IntPtr hWnd, int msg, int wParam, int lParam);
'@

$wv = New-Object Microsoft.Web.WebView2.Wpf.WebView2
$window.Content = $wv
[System.Windows.Shell.WindowChrome]::SetIsHitTestVisibleInChrome($wv, $true)

$window.Add_Loaded({
try {
  function Wait-UiTask($Task) {
    $frame = New-Object System.Windows.Threading.DispatcherFrame
    $clock = [Diagnostics.Stopwatch]::StartNew()
    $waitTimer = New-Object System.Windows.Threading.DispatcherTimer
    $waitTimer.Interval = [TimeSpan]::FromMilliseconds(50)
    $waitTimer.Add_Tick({ if ($Task.IsCompleted -or $clock.Elapsed.TotalSeconds -ge 60) { $frame.Continue = $false } }.GetNewClosure())
    try {
      $waitTimer.Start()
      if (-not $Task.IsCompleted) { [System.Windows.Threading.Dispatcher]::PushFrame($frame) }
      if (-not $Task.IsCompleted) { throw 'WebView2 initialization timed out after 60 seconds.' }
      $Task.GetAwaiter().GetResult() | Out-Null
    } finally { $waitTimer.Stop() }
  }

  # APPUPDATER_DEBUG_PORT enables the remote debugging port.
  $envOptions = [Microsoft.Web.WebView2.Core.CoreWebView2EnvironmentOptions]::new()
  if ($env:APPUPDATER_DEBUG_PORT) {
    $envOptions.AdditionalBrowserArguments = "--remote-debugging-port=$($env:APPUPDATER_DEBUG_PORT)"
  }
  $envTask = [Microsoft.Web.WebView2.Core.CoreWebView2Environment]::CreateAsync(
    $null, (Join-Path $env:LOCALAPPDATA 'AppUpdater\WebView2'), $envOptions
  )
  Wait-UiTask $envTask
  $env = $envTask.Result

  $initTask = $wv.EnsureCoreWebView2Async($env)
  Wait-UiTask $initTask
  $wv.CoreWebView2.Settings.AreDevToolsEnabled = $false
  $wv.CoreWebView2.Settings.AreDefaultContextMenusEnabled = $false

  $wv.CoreWebView2.Add_WebMessageReceived({
    param($s, $e)
    try {
      $msg = $e.WebMessageAsJson | ConvertFrom-Json -ErrorAction Stop
      if (-not $msg -or $msg.action -isnot [string] -or $msg.action -notmatch '^[a-z][a-z0-9-]{0,63}$') {
        throw 'Invalid application message.'
      }
      switch ($msg.action) {
            'browse-installer' {
              # APPUPDATER_TEST_INSTALLER stands in for the file dialog, which CDP cannot drive.
              # Only while it is set may the page name another file, so one test run can pick several.
              $pickedPath = $null
              $testPick = if ($env:APPUPDATER_TEST_INSTALLER) { @([string]$msg.payload.testPath, $env:APPUPDATER_TEST_INSTALLER) } else { @() }
              foreach ($candidate in $testPick) { if (-not $pickedPath -and $candidate -and (Test-Path -LiteralPath $candidate -PathType Leaf)) { $pickedPath = $candidate } }
              if (-not $pickedPath) {
                $ofd = New-Object Microsoft.Win32.OpenFileDialog
                $ofd.Filter = 'Installers and packages (*.exe;*.msi;*.msix;*.msixbundle;*.appx;*.appxbundle;*.zip)|*.exe;*.msi;*.msix;*.msixbundle;*.appx;*.appxbundle;*.zip|All files (*.*)|*.*'
                if ($ofd.ShowDialog($window)) { $pickedPath = $ofd.FileName }
              }
              if ($pickedPath) {
                $d = Invoke-InstallerInspector -InstallerPath $pickedPath
                # Tags stay a word or two; the explanation opens when the tag is clicked.
                $names = @{ InnoSetup = 'Inno Setup'; WiXBurn = 'WiX Burn'; '7ZipSFX' = '7-Zip SFX'; AdvancedInstaller = 'Advanced Installer'; SetupFactory = 'Setup Factory' }
                $chips = @()
                if ($d.InstallerType -eq 'Unknown') { $chips += @{ label = 'Unknown installer'; tone = 'w'; detail = 'AppUpdater does not recognise this installer, so it cannot guess a silent switch. Enter one below (check the vendor documentation or run the installer with /?).' } }
                elseif ($d.InstallerType) { $chips += @{ label = $(if ($names[$d.InstallerType]) { $names[$d.InstallerType] } else { $d.InstallerType }); tone = 'g'; detail = $(if ($d.SilentArgs) { "Installer family detected from the file. Its silent switch is filled in below: $($d.SilentArgs)" } else { 'Package type detected from the file. It installs without a silent switch.' }) } }
                if ($d.InstallerType -eq 'InstallShield') { $chips += @{ label = 'Needs setup.iss'; tone = 'w'; detail = 'InstallScript setups only run silently with a recorded response file. Record one with setup.exe /r, put it next to the installer, turn on "Bundle the whole folder" and use /s /f1"{pkg}\setup.iss".' } }
                if ($d.InstallerType -eq 'Squirrel') { $chips += @{ label = 'Per-user'; tone = 'w'; detail = 'This installer only installs for the signed-in user. Deploy it in Intune with install behaviour User; as SYSTEM it only reaches the SYSTEM profile.' } }
                if ($d.InstallerType -eq 'Zip') { $chips += $(if ($d.EntryExe) { @{ label = 'Portable app'; tone = 'g'; detail = "The zip is unpacked to Program Files with a Start menu shortcut to $($d.EntryExe), and registered in Add/Remove Programs so detection and uninstall work." } } else { @{ label = 'No program found'; tone = 'w'; detail = 'The zip holds no executable that looks like the main program, so it cannot be packaged.' } }) }
                if ($d.InstallerType -eq 'MSIX') { $chips += @{ label = 'All users'; detail = 'MSIX packages are provisioned for every user; existing users get the app at their next sign-in.' } }
                if ($d.InstallerType -eq '7ZipSFX') { $chips += @{ label = 'Check switch'; tone = 'w'; detail = 'This is a self-extracting archive: the silent switch goes to the installer inside it. Confirm it with a local test before deploying.' } }
                $detected = @{
                  summary = (@($d.Version, $d.Publisher) | Where-Object { $_ }) -join ' - '
                  appId = $d.AppID; displayName = $d.DisplayName; registryName = $d.RegistryName
                  version = $d.Version; silentArgs = $d.SilentArgs; installerType = $d.InstallerType; entryExe = $d.EntryExe
                  processesToKill = $d.ProcessesToKill; chips = $chips
                  publisher = $d.Publisher; upgradeCode = $d.UpgradeCode
                }
                $known = Find-KnownApp -UpgradeCode $d.UpgradeCode -Name $d.DisplayName -Publisher $d.Publisher
                if ($known) { $detected.known = $known }
                Send-ToPage $wv 'browse-installer-result' @{ ok = $true; path = $pickedPath; detected = $detected }
                Start-WingetLookupJob -Wv $wv -InstallerPath $pickedPath -Inspection $d -UseWinget (-not $config.DisableReleaseCheck)
              } else {
                Send-ToPage $wv 'browse-installer-result' @{ ok = $false }
              }
            }
            'get-fleet' {
              try {
                Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
              } catch {
                Send-ToPage $wv 'fleet-data' @{ apps = @(); workerUrl = $config.WorkerURL; checkFailed = $true }
                Send-ToPage $wv 'error' @{ message = "Couldn't read the local fleet: $($_.Exception.Message)" }
              }
            }
            'deploy-feedback' {
              if ($msg.payload.outcome -in 'ok', 'failed') { Set-DeployOutcome -AppID ([string]$msg.payload.id) -Outcome $msg.payload.outcome }
            }
            'get-history' {
              $hist = @(Get-DeployHistory)
              [array]::Reverse($hist)
              Send-ToPage $wv 'history-data' @{ events = $hist }
            }
            'build-package' {
              Start-PackageBuildJob -Wv $wv -Config $config -FormData (ConvertTo-HashtableShallow $msg.payload)
            }
            'get-driver-library' {
              $__drivers = @((Get-DriverLibrary).Drivers | ForEach-Object {
                $_.HasFiles = Test-Path -LiteralPath (Join-Path $DriverStoreBase $_.DriverID) -PathType Container
                $_
              })
              Send-ToPage $wv 'driver-library-data' @{ drivers = $__drivers }
            }
            'import-builtin-driver-families' {
              try {
                $result = Import-BuiltInDriverFamilies
                Send-ToPage $wv 'driver-library-data' @{ drivers = @((Get-DriverLibrary).Drivers) }
                Send-ToPage $wv 'builtin-families-imported' @{ ok = $true; added = $result.Added; updated = $result.Updated; total = $result.Total }
              } catch {
                Send-ToPage $wv 'builtin-families-imported' @{ ok = $false; message = $_.Exception.Message }
              }
            }
            'add-driver-to-library' {
              $p = $msg.payload
              try {
                $entry = Add-LibraryDriver -DriverID $p.driverId -DisplayName $p.displayName -SourcePath $p.sourcePath `
                  -InfRelativePath $p.infRelativePath -Manufacturer $p.manufacturer -DriverType $p.driverType `
                  -Architecture $p.architecture -ExpectedPublisher $p.expectedPublisher -Version $p.version `
                  -Models @($p.models | Where-Object { $_ })
                if ($entry) { Send-ToPage $wv 'driver-added' @{ ok = $true; entry = $entry } }
                else { Send-ToPage $wv 'driver-added' @{ ok = $false; message = 'Import failed — check AppUpdater.log for details.' } }
              } catch {
                Send-ToPage $wv 'driver-added' @{ ok = $false; message = $_.Exception.Message }
              }
            }
            'get-config' {
              Send-ToPage $wv 'config-data' @{ orgName = $config.OrgName }
            }
            'set-org-name' {
              $updatedConfig = $config.Clone()
              $updatedConfig.OrgName = $msg.payload.orgName
              if (-not (Save-PersistedConfig -Config $updatedConfig -Path $ConfigFile)) { throw 'Could not save organisation name.' }
              $config.OrgName = $updatedConfig.OrgName
            }
            'winget-prepare' {
              $wid = [string]$msg.payload.id
              $mem = (Get-AppMemory)[$wid]
              $last = if ($mem) { @($mem.builds)[-1] }
              if (-not $last -or -not $mem.keys.wingetId -or -not $last.registered) {
                Send-ToPage $wv 'winget-prepared' @{ ok = $false; id = $wid; message = 'Run a local test of the latest package first.' }
              } else {
                # The wingetcreate arguments stay in this process; the page only gets the preview.
                Start-BackgroundAction -Wv $wv -Roots @('Get-WingetContribution', 'New-WingetSubmission') -Event 'winget-prepared' -OnDone {
                  param($r) if ($r.arguments) { $global:WingetPending[[string]$r.id] = [string[]]$r.arguments; $r.Remove('arguments') }
                } -Variables @{
                  _id = $wid; _wingetId = [string]$mem.keys.wingetId; _version = [string]$last.version; _sha = [string]$last.sha256
                  _registered = (ConvertTo-PlainHashtable $last.registered); _url = [string]$mem.settings.DownloadURL; _out = (Join-Path $TempBase 'winget-submissions')
                  WingetCacheDir = $WingetCacheDir; WingetCacheURL = $WingetCacheURL; WingetSqliteSource = $global:WingetSqliteSource
                } -Script @'
$global:WingetSqliteSource = $WingetSqliteSource
$_result.id = $_id
$c = Get-WingetContribution -Id $_wingetId -Version $_version -Sha256 $_sha -Registered $_registered -DownloadUrl $_url
if (-not $c) { $_result.ok = $true; $_result.nothing = $true; $_result.message = "winget already has what this test verified for $_wingetId."; return }
$submission = New-WingetSubmission -Contribution $c -OutDir $_out
$_result.ok = $true; $_result.kind = $c.Kind; $_result.summary = $c.Summary; $_result.preview = $submission.Preview; $_result.arguments = $submission.Arguments
'@
              }
            }
            'winget-submit' {
              $wid = [string]$msg.payload.id
              $pendingArgs = $global:WingetPending[$wid]
              if (-not $pendingArgs) { Send-ToPage $wv 'winget-submitted' @{ ok = $false; message = 'Prepare the contribution again.' } }
              else {
                Start-BackgroundAction -Wv $wv -Roots @('Get-WingetCreate', 'Invoke-WingetCreate') -Event 'winget-submitted' -TimeoutSeconds 300 -Variables @{
                  _arguments = [string[]]$pendingArgs; _token = [string]$msg.payload.token
                } -Script @'
$exe = Get-WingetCreate
# wingetcreate keeps the token in its own cache, so AppUpdater never stores it; the marker only records that one was given.
# Without a cached token wingetcreate starts an interactive sign-in, which would wait forever in this hidden process.
$marker = Join-Path (Split-Path -Parent $exe) 'token-stored'
if ($_token) {
  $stored = Invoke-WingetCreate -Exe $exe -Arguments @('token', '--store', '--token', $_token)
  if ($stored.ExitCode -ne 0) { throw "wingetcreate could not store the token: $($stored.Output)" }
  Set-Content -LiteralPath $marker -Value (Get-Date -Format 'o')
} elseif (-not (Test-Path -LiteralPath $marker)) {
  $_result.ok = $false; $_result.needsToken = $true; $_result.message = 'Enter a GitHub token (public_repo scope) the first time.'; return
}
$run = Invoke-WingetCreate -Exe $exe -Arguments $_arguments
$_result.ok = [bool]$run.PrUrl; $_result.prUrl = $run.PrUrl
$tail = (@($run.Output -split "`r?`n" | Where-Object { $_.Trim() }) | Select-Object -Last 8) -join "`n"
$_result.message = if ($run.PrUrl) { 'Pull request opened.' } elseif ($run.Output -match '(?i)token|unauthori|credential') { "wingetcreate needs a GitHub token.`n$tail" } else { $tail }
$_result.needsToken = -not $run.PrUrl -and $run.Output -match '(?i)token|unauthori|credential'
'@
              }
            }
            'preflight-preview' {
              # The checks a build runs, worked out in the background as soon as an installer is picked.
              $pf = ConvertTo-HashtableShallow $msg.payload
              $kevFile = Join-Path $KevCacheDir 'kev.json'
              if (-not $config.DisableReleaseCheck -and (Test-Path -LiteralPath $kevFile)) { $pf.KevPath = $kevFile }
              $pf.NvdLookups = [bool]$config.NvdLookups -and -not $config.DisableReleaseCheck
              $pfMemory = try { (Get-AppMemory)[[string]$pf.AppID] } catch { $null }
              Start-BackgroundAction -Wv $wv -Roots @('Get-PreflightFindings') -Event 'preflight-preview-result' -TimeoutSeconds 180 -Variables @{
                _fd = $pf; _history = @(if ($pfMemory) { $pfMemory.builds })
              } -Script @'
$_result.path = [string]$_fd.InstallerPath
$installer = @{}
if ($_fd.InstallerPath -and (Test-Path -LiteralPath $_fd.InstallerPath -PathType Leaf)) {
  $installer.sha256 = (Get-FileHash -LiteralPath $_fd.InstallerPath -Algorithm SHA256).Hash
  try {
    $sig = Get-AuthenticodeSignature -LiteralPath $_fd.InstallerPath
    $installer.status = [string]$sig.Status
    if ($sig.SignerCertificate) { $installer.signer = $sig.SignerCertificate.Subject }
  } catch { $installer.status = '' }
}
$_result.findings = @(Get-PreflightFindings -FormData $_fd -History $_history -Installer $installer)
$_result.ok = $true
'@
            }
            'get-status' {
              $indexFile = Join-Path $WingetCacheDir 'index.db'; $kevFile = Join-Path $KevCacheDir 'kev.json'
              $ageOf = { param($f) if (Test-Path -LiteralPath $f) { [math]::Round(((Get-Date) - (Get-Item -LiteralPath $f).LastWriteTime).TotalHours, 1) } else { $null } }
              Send-ToPage $wv 'status-data' @{ lookups = -not [bool]$config.DisableReleaseCheck; nvd = [bool]$config.NvdLookups; wingetAge = (& $ageOf $indexFile); kevAge = (& $ageOf $kevFile)
                                                connected = [bool]$config.WorkerURL; version = $global:Version }
            }
            'open-link' {
              # Only the pages tags point to; anything else from the page is ignored.
              if ([string]$msg.payload.url -match '^https://github\.com/microsoft/winget-pkgs/(tree|pull)/[A-Za-z0-9./_-]+$') { Start-Process ([string]$msg.payload.url) }
            }
            'open-pr' {
              if ([string]$msg.payload.url -match '^https://github\.com/microsoft/winget-pkgs/pull/\d+$') { Start-Process ([string]$msg.payload.url) }
            }
            'open-status-dashboard' {
              if (Test-SafeHttpsUrl $config.WorkerURL) { Start-Process "$($config.WorkerURL)/status" }
            }
            'open-worker-options' {
              try {
                $rdResult = Invoke-RedeployWorker -Config $config
                $reloaded = Read-PersistedConfig -Path $ConfigFile
                # Assigning $config here would only rebind a handler-local copy.
                if ($reloaded) { $config.Clear(); foreach ($key in @($reloaded.Keys)) { $config[$key] = $reloaded[$key] } }
                # The saved config holds a placeholder; the real token lives in Credential Manager.
                $config.ManifestToken = if ($rdResult -eq 'disconnected' -or $Offline -or $config.OfflineMode) { '' } else { Get-StoredManifestToken }
                Send-ToPage $wv 'config-data' @{ orgName = $config.OrgName }
              } catch {
                Write-AppLog "open-worker-options failed: $($_.Exception.Message)" ERROR
                Send-ToPage $wv 'error' @{ message = "Worker options failed to open: $($_.Exception.Message)" }
              }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'disconnect-worker' {
              $updatedConfig = $config.Clone()
              $updatedConfig.WorkerURL = ''; $updatedConfig.WorkerDevURL = ''; $updatedConfig.ManifestToken = ''
              $updatedConfig.OfflineMode = $true
              if (-not (Save-PersistedConfig -Config $updatedConfig -Path $ConfigFile)) { throw 'Could not save disconnected settings.' }
              foreach ($key in @('WorkerURL','WorkerDevURL','ManifestToken','OfflineMode')) { $config[$key] = $updatedConfig[$key] }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'get-profiles' {
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed }
            }
            'save-profile' {
              $p = $msg.payload
              $ok = Save-PackagingProfile -Profile @{
                Name = $p.Name; OrgName = $p.OrgName
                LogoImagePath = $p.LogoImagePath; BannerImagePath = $p.BannerImagePath
                DefaultTarget = $p.DefaultTarget
              }
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed; saveOk = $ok }
            }
            'delete-profile' {
              Remove-PackagingProfile -Name $msg.payload.name
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed }
            }
            'browse-image' {
              $pickedPath = $null
              if ($env:APPUPDATER_TEST_IMAGE -and (Test-Path -LiteralPath $env:APPUPDATER_TEST_IMAGE -PathType Leaf)) {
                $pickedPath = $env:APPUPDATER_TEST_IMAGE
              } else {
                $ifd = New-Object Microsoft.Win32.OpenFileDialog
                $ifd.Filter = 'Images (*.png;*.jpg;*.jpeg;*.svg)|*.png;*.jpg;*.jpeg;*.svg|All files (*.*)|*.*'
                if ($ifd.ShowDialog($window)) { $pickedPath = $ifd.FileName }
              }
              if ($pickedPath) {
                Send-ToPage $wv 'browse-image-result' @{ ok = $true; field = $msg.payload.field; path = $pickedPath; dataUrl = (Get-ImageDataUrl -Path $pickedPath) }
              } else {
                Send-ToPage $wv 'browse-image-result' @{ ok = $false; field = $msg.payload.field }
              }
            }
            'browse-script' {
              $pickedPath = $null
              if ($env:APPUPDATER_TEST_SCRIPT -and (Test-Path -LiteralPath $env:APPUPDATER_TEST_SCRIPT -PathType Leaf)) {
                $pickedPath = $env:APPUPDATER_TEST_SCRIPT
              } else {
                $sfd = New-Object Microsoft.Win32.OpenFileDialog
                $sfd.Filter = 'PowerShell scripts (*.ps1)|*.ps1'
                if ($sfd.ShowDialog($window)) { $pickedPath = $sfd.FileName }
              }
              if ($pickedPath) { Send-ToPage $wv 'browse-script-result' @{ ok = $true; field = [string]$msg.payload.field; path = $pickedPath } }
            }
            'get-image-preview' {
              Send-ToPage $wv 'image-preview-result' @{ field = $msg.payload.field; dataUrl = (Get-ImageDataUrl -Path $msg.payload.path) }
            }
            'get-psadt-stock-assets' {
              try {
                $bannerPath = Join-Path $PSADTCacheDir 'PSAppDeployToolkit\Assets\Banner.Classic.png'
                $iconPath   = Join-Path $PSADTCacheDir 'PSAppDeployToolkit\Assets\AppIcon.png'
                if ((Test-Path $bannerPath) -and (Test-Path $iconPath)) {
                  Send-ToPage $wv 'psadt-stock-assets' @{ ok = $true; banner = (Get-ImageDataUrl -Path $bannerPath); icon = (Get-ImageDataUrl -Path $iconPath) }
                } else {
                  Send-ToPage $wv 'psadt-stock-assets' @{ ok = $false }
                }
              } catch {
                Send-ToPage $wv 'psadt-stock-assets' @{ ok = $false }
              }
            }
            'mark-deployed' {
              $mdManifest = Get-LocalManifest -XmlFile $ManifestPath
              $mdApp = if ($mdManifest.Ok) { $mdManifest.Apps | Where-Object { $_.ID -eq $msg.payload.id } | Select-Object -First 1 } else { $null }
              Set-DeployStatus -AppID $msg.payload.id -AppName $(if ($mdApp) { $mdApp.DisplayName } else { $msg.payload.id }) -MarkDeployed
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'remove-from-fleet' {
              if (Test-OperationActive) {
                throw 'Wait for the active build or test to finish before removing packages.'
              }
              $rmId = $msg.payload.id
              $rmManifest = Get-LocalManifest -XmlFile $ManifestPath
              $rmApp = if ($rmManifest.Ok) { $rmManifest.Apps | Where-Object { $_.ID -eq $rmId } | Select-Object -First 1 } else { $null }
              $rmName = if ($rmApp) { $rmApp.DisplayName } else { $rmId }
              $rmChoice = Show-WpfDeleteChoice -AppName $rmName -AppID $rmId
              if (-not $rmChoice -or $rmChoice -eq 'cancel') {
                Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $false; cancelled = $true }
              } else {
                $rmReport = $null
                if ($rmChoice -eq 'everything') {
                  $rmReport = Remove-AppLocalArtifacts -AppID $rmId -DisplayName $rmName
                }
                try {
                  if (Test-Path -LiteralPath $ManifestPath) {
                    [xml]$rmXml = Get-Content -LiteralPath $ManifestPath -Raw -Encoding UTF8 -ErrorAction Stop
                    $rmNodes = @($rmXml.AppManifest.App | Where-Object { $_.ID -eq $rmId })
                    foreach ($rmNode in $rmNodes) { $rmXml.AppManifest.RemoveChild($rmNode) | Out-Null }
                    Write-AtomicText -Path $ManifestPath -Text $rmXml.OuterXml
                  }
                  $rmStore = Get-DeployStatusStore
                  if ($rmStore.ContainsKey($rmId)) { $rmStore.Remove($rmId); Save-DeployStatusStore -Store $rmStore }
                  Add-DeployHistoryEvent -AppID $rmId -AppName $rmName -Event ('removed' + $(if ($rmChoice -eq 'everything') { ' (+ local cleanup)' } else { '' }))
                  Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $true; everything = ($rmChoice -eq 'everything') }
                } catch {
                  Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $false; message = $_.Exception.Message }
                }
              }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'test-locally' {
              $store = Get-DeployStatusStore
              $entry = $store[$msg.payload.id]
              if (-not $entry -or -not $entry.outputDir -or -not (Test-Path $entry.outputDir)) {
                Send-ToPage $wv 'test-log' @{ line = 'No output folder on record for this app - rebuild it first.'; done = $true; ok = $false }
              } else {
                Start-LocalTestJob -Wv $wv -AppID $msg.payload.id -OutputDir $entry.outputDir -Target $entry.target -AlsoUninstall:([bool]$msg.payload.alsoUninstall) -SimulateSystem:([bool]$msg.payload.simulateSystem)
              }
            }
            'get-settings' {
              Send-ToPage $wv 'settings-data' @{
                orgName = $config.OrgName
                reduceMotion = [bool]$config.ReduceMotion
                highContrast = [bool]$config.HighContrast
                colorblindSafe = [bool]$config.ColorblindSafe
                releaseCheckEnabled = -not [bool]$config.DisableReleaseCheck
                nvdEnabled = [bool]$config.NvdLookups
                showCloudflareAdvert = -not [bool]$config.HideCloudflareAdvert
                showGettingStarted = -not [bool]$config.HideGettingStarted
                showCloudflareNav = -not [bool]$config.HideCloudflareNav
                onboardingSeen = [bool]$config.OnboardingSeen
                modeExplainerSeen = [bool]$config.ModeExplainerSeen
                version = $global:Version
                newerAvailable = [bool]($global:_relCheck -and $global:_relCheck.Newer -and $global:_relCheck.Latest)
                latestVersion = if ($global:_relCheck) { $global:_relCheck.Latest } else { '' }
                releaseInfo = if ($global:_relCheck -and $global:_relCheck.Newer -and $global:_relCheck.Latest) {
                  "Update available: v$($global:_relCheck.Latest) on GitHub"
                } elseif ($global:_relCheck -and $global:_relCheck.Latest) {
                  "Up to date (latest release: v$($global:_relCheck.Latest))"
                } else { 'Release check pending or offline.' }
              }
            }
            'save-settings' {
              $config.OrgName = $msg.payload.orgName
              $config.ReduceMotion = [bool]$msg.payload.reduceMotion
              $global:ReduceMotion = $config.ReduceMotion
              $config.HighContrast = [bool]$msg.payload.highContrast
              $config.ColorblindSafe = [bool]$msg.payload.colorblindSafe
              $config.DisableReleaseCheck = -not [bool]$msg.payload.releaseCheckEnabled
              $config.NvdLookups = [bool]$msg.payload.nvdEnabled
              $config.HideCloudflareAdvert = -not [bool]$msg.payload.showCloudflareAdvert
              $config.HideGettingStarted = -not [bool]$msg.payload.showGettingStarted
              $config.HideCloudflareNav = -not [bool]$msg.payload.showCloudflareNav
              $ok = Save-PersistedConfig -Config $config
              Send-ToPage $wv 'settings-saved' @{ ok = $ok }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'dismiss-cloudflare-advert' {
              $config.HideCloudflareAdvert = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'dismiss-getting-started' {
              $config.HideGettingStarted = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'mark-onboarding-seen' {
              $config.OnboardingSeen = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'mark-mode-explainer-seen' {
              $config.ModeExplainerSeen = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'reset-onboarding' {
              $config.OnboardingSeen = $false
              $config.ModeExplainerSeen = $false
              [void](Save-PersistedConfig -Config $config)
            }
            'client-error' {
              Write-AppLog "Client-side JS error: $($msg.payload.message) at $($msg.payload.source)`n$($msg.payload.stack)" ERROR
            }
            'open-folder' {
              switch ($msg.payload.which) {
                'output' { try { Start-Process explorer.exe $global:OutputBase } catch { } }
                'cache'  { try { Start-Process explorer.exe $PSADTCacheDir } catch { } }
                'log'    { try { Start-Process notepad.exe $global:LogFile } catch { } }
              }
            }
            'open-github-releases' {
              try { Start-Process 'https://github.com/Lyvvy-xyz/Appupdater/releases' } catch { }
            }
            'drag-window' {
              try {
                $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($window)).Handle
                [AppUpdater.Win32Drag]::ReleaseCapture() | Out-Null
                [AppUpdater.Win32Drag]::SendMessage($hwnd, 0xA1, 0x2, 0) | Out-Null   # WM_NCLBUTTONDOWN, HTCAPTION
              } catch { }
            }
            'minimize-window' {
              $window.WindowState = 'Minimized'
            }
            'close-window' {
              $window.Close()
            }
            'export-recovery-bundle' {
              $pw = Show-WpfPassphrase -Title 'Protect recovery bundle' -Confirm
              if ($pw) {
                $sfd = New-Object Microsoft.Win32.SaveFileDialog
                $sfd.Title = 'Save recovery bundle'
                $sfd.FileName = "AppUpdater-recovery-$(Get-Date -Format 'yyyyMMdd').aurb"
                $sfd.Filter = 'AppUpdater recovery bundle (*.aurb)|*.aurb'
                if ($sfd.ShowDialog($window)) {
                  $json = Export-RecoveryState -Config $config
                  $ok = Protect-RecoveryBundle -PlainJson $json -Passphrase $pw -OutFile $sfd.FileName
                  Send-ToPage $wv 'recovery-export-result' @{ ok = $ok; path = $sfd.FileName }
                }
              }
            }
            'import-recovery-bundle' {
              $ofd2 = New-Object Microsoft.Win32.OpenFileDialog
              $ofd2.Title = 'Select recovery bundle'
              $ofd2.Filter = 'AppUpdater recovery bundle (*.aurb)|*.aurb|All files (*.*)|*.*'
              if ($ofd2.ShowDialog($window)) {
                $pw2 = Show-WpfPassphrase -Title 'Unlock recovery bundle'
                if ($pw2) {
                  try {
                    $json2 = Unprotect-RecoveryBundle -InFile $ofd2.FileName -Passphrase $pw2
                    $newCfg = Import-RecoveryState -StateJson $json2
                    # Later saves write $config back, so it must hold the restored values.
                    $config.Clear(); foreach ($key in @($newCfg.Keys)) { $config[$key] = $newCfg[$key] }
                    Send-ToPage $wv 'recovery-import-result' @{ ok = $true }
                    Send-ToPage $wv 'config-data' @{ orgName = $config.OrgName }
                    Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
                  } catch {
                    Send-ToPage $wv 'recovery-import-result' @{ ok = $false; message = $_.Exception.Message }
                  }
                }
              }
            }
            default {
              throw "Unknown application action: $($msg.action)"
            }
          }
        } catch {
          Send-ToPage $wv 'error' @{ message = $_.Exception.Message }
        }
      }.GetNewClosure())
  $wv.CoreWebView2.NavigateToString($__UiHtml)
} catch {
  $__err = $_.Exception
  $__detail = if ($__err.InnerException) { "$($__err.Message)`n`nInner: $($__err.InnerException.Message)" } else { $__err.ToString() }
  [System.Windows.MessageBox]::Show(
    "The app window failed to start up.`n`n$__detail",
    'AppUpdater - startup error', 'OK', 'Error'
  ) | Out-Null
  $window.Close()
}
})

function Test-OperationActive {
  return (($script:ActiveBuild -and -not $script:ActiveBuild.Finished) -or ($script:ActiveTest -and -not $script:ActiveTest.Finished))
}

function Start-LocalTestJob {
  param($Wv, [string]$AppID, [string]$OutputDir, [string]$Target, [switch]$AlsoUninstall, [switch]$SimulateSystem)

  if ($script:ActiveTest -and -not $script:ActiveTest.Finished) { throw 'A local test is already running.' }
  if ($script:ActiveBuild -and -not $script:ActiveBuild.Finished) { throw 'Wait for the package build to finish before testing.' }

  $tq = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))
  $td = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))

  $rs = [runspacefactory]::CreateRunspace()
  $ps = $null
  try {
  $rs.Open()
  $rs.SessionStateProxy.SetVariable('_tq', $tq)
  $rs.SessionStateProxy.SetVariable('_td', $td)
  $rs.SessionStateProxy.SetVariable('_out', $OutputDir)
  $rs.SessionStateProxy.SetVariable('_appId', $AppID)
  $rs.SessionStateProxy.SetVariable('_target', $Target)
  $rs.SessionStateProxy.SetVariable('_alsoUninstall', [bool]$AlsoUninstall)
  $rs.SessionStateProxy.SetVariable('_simulateSystem', [bool]$SimulateSystem)
  $rs.SessionStateProxy.SetVariable('_epmFn', "function Write-EpmRules {`n$((Get-Item Function:\Write-EpmRules).ScriptBlock)`n}")

  $ps = [powershell]::Create()
  $ps.Runspace = $rs
  [void]$ps.AddScript({
    $ErrorActionPreference = 'Stop'
    function Log($m) { if ($_tq.Count -lt 2000) { $_tq.Enqueue($m) } }
    # $_runAs (@{ User; Password }) runs the scripts as that standard user, as Intune's User install behaviour does;
    # its files go under ProgramData because the user cannot read this account's temp folder.
    $tmpBase = if ($_runAs) { [IO.Directory]::CreateDirectory((Join-Path $env:ProgramData 'AppUpdaterTest')).FullName } else { [System.IO.Path]::GetTempPath() }
    $runAsLabel = if ($_runAs) { $_runAs.User } else { 'SYSTEM' }
    function RunAndLog($exe, $argsList, $label) {
      Log "> $label"
      if ($_simulateSystem -or $_runAs) {
        return Invoke-AsSystemViaTask $exe $argsList $label
      }
      try {
        $p = Start-Process -FilePath $exe -ArgumentList $argsList -PassThru -NoNewWindow
        # Reading Handle keeps ExitCode available after the process exits.
        $null = $p.Handle
        if (-not $p.WaitForExit(600000)) { throw "$label timed out after 10 minutes." }
        $p.Refresh()
        Log "  exit code $($p.ExitCode)"
        return $p.ExitCode
      } finally {
        if ($p) { if (-not $p.HasExited) { $p.Kill() }; $p.Dispose() }
      }
    }
    function RunScriptAndLog($path, $argStr, $label) {
      if (-not (Test-Path -LiteralPath $path)) { throw "Required script missing: $([System.IO.Path]::GetFileName($path))" }
      return RunAndLog 'powershell.exe' "-NoProfile -ExecutionPolicy Bypass -File `"$path`" $argStr" $label
    }

    function Invoke-AsSystemViaTask($exe, $argsList, $label) {
      $taskName = "AppUpdaterLocalTest_$([guid]::NewGuid().ToString('N').Substring(0,8))"
      $outFile = Join-Path $tmpBase "$taskName.out.txt"
      $startedFile = "$outFile.started"
      $resultFile = "$outFile.exit"
      $wrapped = "[IO.File]::WriteAllText('$($startedFile.Replace("'","''"))', 'started'); & '$($exe.Replace("'","''"))' $argsList > '$($outFile.Replace("'","''"))' 2>&1; [IO.File]::WriteAllText('$($resultFile.Replace("'","''"))', [string]`$LASTEXITCODE); exit `$LASTEXITCODE"
      $encodedCommand = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($wrapped))
      $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -WindowStyle Hidden -EncodedCommand $encodedCommand"
      try {
        if ($_runAs) {
          Register-ScheduledTask -TaskName $taskName -Action $action -User $_runAs.User -Password $_runAs.Password -RunLevel Limited -Force -ErrorAction Stop | Out-Null
        } else {
          $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
          Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Force -ErrorAction Stop | Out-Null
        }
        Start-ScheduledTask -TaskName $taskName
        $waited = 0
        do { Start-Sleep -Milliseconds 500; $waited += 500 }
        while (-not (Test-Path -LiteralPath $resultFile) -and $waited -lt 600000)
        if (-not (Test-Path -LiteralPath $resultFile)) { throw "$label did not complete within 10 minutes." }
        $exitCode = [int](Get-Content -LiteralPath $resultFile -Raw -ErrorAction Stop)
        if (Test-Path $outFile) { (Get-Content $outFile -Raw) -split "`n" | Where-Object { $_.Trim() } | ForEach-Object { Log "    [$runAsLabel] $_" } }
        Log "  exit code $exitCode (ran as $runAsLabel)"
        return $exitCode
      } catch {
        Log "  FAILED to run as $($runAsLabel): $($_.Exception.Message)"
        return -1
      } finally {
        Stop-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
        Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $outFile, $startedFile, $resultFile -Force -ErrorAction SilentlyContinue
      }
    }

    function Expand-IntuneWinForTest($IntuneWinPath, $DestDir) {
      Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
      $outerDir = Join-Path ([System.IO.Path]::GetTempPath()) "iwt_outer_$([guid]::NewGuid())"
      $tmpZip = Join-Path ([System.IO.Path]::GetTempPath()) "iwt_content_$([guid]::NewGuid()).zip"
      $inputStream = $outputStream = $cryptoStream = $decryptor = $aes = $reader = $null
      try {
        [System.IO.Compression.ZipFile]::ExtractToDirectory($IntuneWinPath, $outerDir)
        $detXml = Join-Path $outerDir 'IntuneWinPackage\Metadata\Detection.xml'
        if (-not (Test-Path -LiteralPath $detXml)) { throw 'Not a recognized .intunewin file (Detection.xml missing).' }
        [xml]$xml = Get-Content -LiteralPath $detXml -Raw
        $encInfo = $xml.ApplicationInfo.EncryptionInfo
        $encFile = Get-ChildItem (Join-Path $outerDir 'IntuneWinPackage\Contents') -File -ErrorAction Stop | Select-Object -First 1
        $inputStream = [IO.File]::OpenRead($encFile.FullName)
        $reader = [IO.BinaryReader]::new($inputStream)
        $header = $reader.ReadBytes(48)
        if ($header.Length -ne 48 -or $inputStream.Length -le 48) { throw 'Encrypted package is truncated.' }
        $iv = New-Object byte[] 16
        [Array]::Copy($header, 32, $iv, 0, 16)
        $aes = [Security.Cryptography.Aes]::Create()
        $aes.Mode = 'CBC'; $aes.Key = [Convert]::FromBase64String($encInfo.EncryptionKey); $aes.IV = $iv
        $decryptor = $aes.CreateDecryptor()
        $cryptoStream = [Security.Cryptography.CryptoStream]::new($inputStream, $decryptor, [Security.Cryptography.CryptoStreamMode]::Read)
        $outputStream = [IO.File]::Create($tmpZip)
        $cryptoStream.CopyTo($outputStream, 81920)
        $outputStream.Dispose(); $outputStream = $null
        [System.IO.Compression.ZipFile]::ExtractToDirectory($tmpZip, $DestDir)
      } finally {
        foreach ($resource in @($outputStream, $cryptoStream, $decryptor, $reader, $inputStream, $aes)) {
          if ($resource) { $resource.Dispose() }
        }
        Remove-Item -LiteralPath $outerDir -Recurse -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $tmpZip -Force -ErrorAction SilentlyContinue
      }
    }

    function Get-ArpSnapshot {
      $roots = @('Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
                 'Registry::HKEY_LOCAL_MACHINE\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall')
      # S-1-5-18 is SYSTEM's own profile, where per-user installers land when Intune runs them.
      foreach ($hive in @(Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-(18|21-[\d-]+)$' })) {
        $roots += "Registry::HKEY_USERS\$($hive.PSChildName)\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"
      }
      $snapshot = @{}
      foreach ($key in @(Get-ChildItem -Path $roots -ErrorAction SilentlyContinue)) {
        $entry = Get-ItemProperty -LiteralPath $key.PSPath -ErrorAction SilentlyContinue
        if ($entry.DisplayName) { $snapshot[$key.Name] = $entry }
      }
      return $snapshot
    }
    function Write-ArpChanges($Before, $After) {
      $changed = @($After.Keys | Where-Object { -not $Before.ContainsKey($_) -or [string]$Before[$_].DisplayVersion -ne [string]$After[$_].DisplayVersion })
      if (-not $changed.Count) { Log '  Add/Remove Programs: no new or changed entry. The app may not register itself, or the installer did nothing.'; return }
      foreach ($name in $changed) {
        $entry = $After[$name]
        $scope = if ($name -match '^HKEY_USERS\\S-1-5-18\\') { "SYSTEM's profile only" } elseif ($name -match '^HKEY_USERS\\') { 'one user only' } else { 'all users' }
        Log "  Add/Remove Programs: '$($entry.DisplayName)' version '$($entry.DisplayVersion)' - installed for $scope$(if ($entry.QuietUninstallString) { ', has a silent uninstall command' })"
      }
      if (@($changed | Where-Object { $_ -match '^HKEY_USERS\\' }).Count) {
        Log "  WARNING: per-user installer. Deploy it with Intune install behaviour User; run as SYSTEM it only reaches SYSTEM's own profile."
      }
      Log "  Detection matches the 'Registry display name' field; set it to the name above if they differ, then rebuild."
      return @($changed | ForEach-Object { [string]$After[$_].DisplayName })
    }
    function Get-DetectTarget($DetectPath) {
      return [regex]::Match([IO.File]::ReadAllText($DetectPath), "Find-ARPEntry -Target '((?:[^']|'')*)'").Groups[1].Value.Replace("''", "'")
    }
    function Get-RegistrySuggestion($Names, $DetectPath, $Target) {
      # The entry the install added that best fits the name detection, or the Runtime agent, looks for.
      $target = if ($Target) { $Target } else { Get-DetectTarget $DetectPath }
      $wanted = ($target -replace '[^A-Za-z0-9]', '').ToLowerInvariant()
      $fits = @($Names | Where-Object { $n = ($_ -replace '[^A-Za-z0-9]', '').ToLowerInvariant(); $wanted -and $n -and ($n.Contains($wanted) -or $wanted.Contains($n)) })
      if ($fits.Count -eq 1) { return $fits[0] }
      $apps = @($Names | Where-Object { $_ -notmatch 'maintenance|updater?\b|helper|runtime|redistributable' })
      if ($apps.Count -eq 1) { return $apps[0] }
      return ''
    }
    function Get-RegisteredEntry($Snapshot, $DetectPath, $Target) {
      # The Add/Remove Programs entry for the registry name, in Find-ARPEntry's order: exact, normalized, normalized prefix.
      $target = if ($Target) { $Target } else { Get-DetectTarget $DetectPath }
      $norm = { param($n) ([string]$n -replace '[^\p{L}\p{N}]', '').ToLowerInvariant() }
      $wanted = & $norm $target
      if (-not $wanted) { return $null }
      $entries = @($Snapshot.Values)
      return @(@($entries | Where-Object { $_.DisplayName -eq $target }) + @($entries | Where-Object { (& $norm $_.DisplayName) -eq $wanted }) +
        @($entries | Where-Object { $n = & $norm $_.DisplayName; $n -and ($n.StartsWith($wanted) -or $wanted.StartsWith($n)) })) | Select-Object -First 1
    }
    function Complete-InstalledCheck($Snapshot, $DetectPath, $Target) {
      # Offers the registered version as detection's minimum when detect.ps1 has none, and adds the app's updaters to the EPM rules.
      $entry = Get-RegisteredEntry $Snapshot $DetectPath $Target
      if (-not $entry) { return }
      $script:registeredEntry = @{ DisplayName = [string]$entry.DisplayName; DisplayVersion = ([string]$entry.DisplayVersion).Trim()
                                   Publisher = [string]$entry.Publisher; ProductCode = [string]$entry.PSChildName }
      if ([IO.File]::ReadAllText($DetectPath) -match "(?m)^\`$minimum = ''" -and [string]$entry.DisplayVersion -match '\d') { $script:registeredVersion = ([string]$entry.DisplayVersion).Trim() }
      $location = ([string]$entry.InstallLocation).Trim().Trim('"')
      if ($_epmFn -and $location -and (Test-Path -LiteralPath $location -PathType Container)) {
        . ([scriptblock]::Create($_epmFn))
        $exes = @(Get-ChildItem -LiteralPath $location -Filter '*.exe' -File -Recurse -Depth 3 -ErrorAction SilentlyContinue)
        $updaters = @($exes | Where-Object { $_.FullName.Substring($location.Length) -match '(?i)update|upgrade|maintenance|\\gup\.exe$' } | Select-Object -First 10)
        # The main program: the largest executable in the install folder itself that is not a helper.
        $main = @($exes | Where-Object { $_.DirectoryName.TrimEnd('\') -eq $location.TrimEnd('\') -and $_.Name -notmatch '(?i)unins|uninstall|setup|update|helper|crash|report|redist' } |
          Sort-Object Length -Descending | Select-Object -First 1)
        if ($main.Count) { Write-EpmRules -Paths @($main.FullName) -OutputDir $_out -Role 'app' | Out-Null }
        if ($updaters.Count) { Write-EpmRules -Paths @($updaters.FullName) -OutputDir $_out -Role 'updater' | Out-Null }
        if ($main.Count -or $updaters.Count) { Log "  EPM: added $(@($main + $updaters).Count) installed file(s) from $location to EPM-rules.csv: $(@(@($main + $updaters).Name) -join ', ')" }
      }
    }
    $script:suggestion = ''
    $script:registeredVersion = ''
    $script:registeredEntry = $null
    function Stop-OnDetectionFailure($Code, $Names, $DetectPath, $Snapshot) {
      $script:suggestion = Get-RegistrySuggestion $Names $DetectPath
      if ($script:suggestion) { Log "  Suggested registry display name: '$($script:suggestion)'" }
      # Found but below the minimum: the app numbers its versions differently from the installer.
      $minimum = [regex]::Match([IO.File]::ReadAllText($DetectPath), "(?m)^\`$minimum = '([^']*)'").Groups[1].Value
      $entry = if ($minimum -and $Snapshot) { Get-RegisteredEntry $Snapshot $DetectPath }
      if ($entry -and [string]$entry.DisplayVersion -match '\d' -and ([string]$entry.DisplayVersion).Trim() -ne $minimum) {
        $script:registeredVersion = ([string]$entry.DisplayVersion).Trim()
        Log "  The app registered version '$($script:registeredVersion)', which does not meet the minimum '$minimum'. It numbers versions differently from the installer; use '$($script:registeredVersion)' as the minimum."
      }
      throw "Post-install detection failed with exit code $Code."
    }

    try {
      $intuneWinFile = Get-ChildItem $_out -Filter '*.intunewin' -ErrorAction SilentlyContinue | Select-Object -First 1
      $testDir = $_out
      if ($intuneWinFile) {
        Log "Found $($intuneWinFile.Name) - decrypting and extracting for a real test..."
        $testDir = Join-Path $tmpBase "iwt_extracted_$([guid]::NewGuid())"
        try {
          Expand-IntuneWinForTest $intuneWinFile.FullName $testDir
          Log "  Decrypted OK -> testing the actual packaged contents"
        } catch {
          throw "Could not validate the packaged artifact: $($_.Exception.Message)"
        }
      } else {
        Log 'No .intunewin file found in the output folder - testing the loose scripts instead.'
      }

      # Runtime packages carry detection as an Intune sidecar; require it before installing.
      $detect = $null
      foreach ($candidateDir in @($testDir, $_out, (Join-Path (Split-Path $_out -Parent) $_appId))) {
        foreach ($candidateName in @('detect.ps1', "Detect-$_appId.ps1")) {
          $candidate = Join-Path $candidateDir $candidateName
          if (Test-Path -LiteralPath $candidate -PathType Leaf) { $detect = Get-Item -LiteralPath $candidate; break }
        }
        if ($detect) { break }
      }
      if (-not $detect) { throw 'No detection script found; the installation test cannot be verified.' }
      if ($_target -eq 'psadt' -or $_target -eq 'psadt-v3' -or $_target -eq 'psadt-v4' -or $_target -eq 'both') {
        $deployApp = Join-Path $testDir 'Deploy-Application.ps1'
        $deployMode = if ($_simulateSystem) { 'Silent' } else { 'Interactive' }
        $arpBefore = Get-ArpSnapshot
        $installExit = RunScriptAndLog $deployApp "-DeploymentType Install -DeployMode $deployMode" "Install (PSADT, $deployMode)"
        $arpAfter = Get-ArpSnapshot
        $arpNew = Write-ArpChanges $arpBefore $arpAfter
        if ($installExit -notin @(0,3010,1641)) { throw "PSADT installation failed with exit code $installExit." }
        $detected = RunScriptAndLog $detect.FullName '' 'Post-install detection'
        if ($detected -ne 0) { Stop-OnDetectionFailure $detected $arpNew $detect.FullName $arpAfter }
        Complete-InstalledCheck $arpAfter $detect.FullName
        if ($_alsoUninstall) {
          $uninstallExit = RunScriptAndLog $deployApp "-DeploymentType Uninstall -DeployMode $deployMode" "Uninstall (PSADT, $deployMode)"
          if ($uninstallExit -notin @(0,3010,1641)) { throw "PSADT uninstall failed with exit code $uninstallExit." }
          $detected = RunScriptAndLog $detect.FullName '' 'Post-uninstall detection'
          if ($detected -ne 1) { throw "Expected not-installed detection exit code 1 after uninstall, got $detected." }
        }
      } else {
        $install = Get-ChildItem $testDir -Filter 'install.ps1' -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $install) { $install = Get-ChildItem $testDir -Filter "Deploy-$_appId.ps1" -ErrorAction SilentlyContinue | Select-Object -First 1 }
        $uninstall = Get-ChildItem $testDir -Filter 'uninstall.ps1' -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($_alsoUninstall -and -not $uninstall) { throw 'This output has no uninstall script. Disable the uninstall test or build a package that supports it.' }

        if ($detect) {
          $r0 = RunScriptAndLog $detect.FullName '' 'Pre-check (detect.ps1)'
          Log "  --> $(if ($r0 -eq 0) { 'Already detected as installed' } else { 'Not detected (expected before install)' })"
        }
        if ($install) {
          $arpBefore = Get-ArpSnapshot
          $installExit = RunScriptAndLog $install.FullName '' 'Install'
          $arpAfter = Get-ArpSnapshot
          $arpNew = Write-ArpChanges $arpBefore $arpAfter
          if ($installExit -notin @(0,3010,1641)) { throw "Installation failed with exit code $installExit." }
        } else {
          throw 'No install script found in this output folder.'
        }
        if ($detect) {
          $r1 = RunScriptAndLog $detect.FullName '' 'Post-install check (detect.ps1)'
          if ($r1 -ne 0) { Stop-OnDetectionFailure $r1 $arpNew $detect.FullName $arpAfter }
          $agentTarget = $null
          if ($install.Name -like 'Deploy-*') {
            # Runtime detection only confirms the agent, so check the name the agent itself looks for: a name the app does not
            # register makes the agent reinstall it on every run.
            $agentScript = if ($env:ProgramData) { Join-Path $env:ProgramData "AppUpdater\$_appId\$_appId.ps1" }
            $agentTarget = if ($agentScript -and (Test-Path -LiteralPath $agentScript)) { [regex]::Match([IO.File]::ReadAllText($agentScript), "(?m)^\`$RegistryName\s*=\s*'((?:[^']|'')*)'").Groups[1].Value.Replace("''", "'") }
            if ($agentTarget -and -not (Get-RegisteredEntry $arpAfter $null $agentTarget)) {
              $script:suggestion = Get-RegistrySuggestion $arpNew $null $agentTarget
              Log "  The agent looks for '$agentTarget' in Add/Remove Programs, which the app did not register, so it would reinstall the app on every run."
              if ($script:suggestion) { Log "  Suggested registry display name: '$($script:suggestion)'" }
              throw 'The Runtime agent cannot find the installed app by its registry name.'
            }
          }
          Complete-InstalledCheck $arpAfter $detect.FullName $agentTarget
          Log "  --> $(if ($r1 -eq 0) { 'PASS - detected after install' } else { 'FAIL - NOT detected after install (detection rule or install command is wrong)' })"
        } else { throw 'No detection script found in this output folder.' }
        if ($_alsoUninstall) {
          if (-not $uninstall) { throw 'No uninstall script found; uninstall test cannot run.' }
          $uninstallExit = RunScriptAndLog $uninstall.FullName '' 'Uninstall'
          if ($uninstallExit -notin @(0,3010,1641)) { throw "Uninstall failed with exit code $uninstallExit." }
          if ($detect) {
            $r2 = RunScriptAndLog $detect.FullName '' 'Post-uninstall check (detect.ps1)'
            if ($r2 -ne 1) { throw "Expected not-installed detection exit code 1 after uninstall, got $r2." }
            Log "  --> $(if ($r2 -ne 0) { 'PASS - no longer detected' } else { 'FAIL - still detected after uninstall' })"
          }
        }
      }
      if ($script:registeredVersion) { Log "  Detection accepts any version. The app registered version '$($script:registeredVersion)'; rebuild with it as the minimum version so older copies are upgraded." }
      Log '=== Local test complete ==='
      $_td.Add(@{ ok = $true; suggestedDetectVersion = $script:registeredVersion; registered = $script:registeredEntry }) | Out-Null
    } catch {
      Log "ERROR: $($_.Exception.Message)"
      $_td.Add(@{ ok = $false; suggestedRegistryName = $script:suggestion; suggestedDetectVersion = $script:registeredVersion }) | Out-Null
    } finally {
      if ($testDir -and $testDir -ne $_out) { Remove-Item -LiteralPath $testDir -Recurse -Force -ErrorAction SilentlyContinue }
    }
  })
  $handle = $ps.BeginInvoke()
  } catch {
    if ($ps) { $ps.Dispose() }
    $rs.Dispose()
    throw
  }

  $script:ActiveTest = @{ Finished = $false; Started = [Diagnostics.Stopwatch]::StartNew() }
  $job = $script:ActiveTest

  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(150)
  $timer.Add_Tick({
    for ($i = 0; $i -lt 100 -and $tq.Count -gt 0; $i++) { Send-ToPage $Wv 'test-log' @{ line = $tq.Dequeue(); done = $false } }
    if ($job.Started.Elapsed.TotalMinutes -gt 40 -and -not $handle.IsCompleted -and -not $job.StopHandle) { $job.StopHandle = $ps.BeginStop($null, $null) }
    if ($handle.IsCompleted -and $tq.Count -eq 0) {
      $timer.Stop()
      try {
        $ps.EndInvoke($handle) | Out-Null
        if ($td.Count -ne 1) { throw 'Local test ended without a result.' }
        $wingetOffer = $false
        if ($td[0].ok -and $td[0].registered) {
          try { $wingetOffer = [bool](Set-AppMemoryTestResult -AppID $AppID -Registered $td[0].registered) } catch { Write-AppLog "Could not record the test result: $($_.Exception.Message)" WARN }
        }
        Send-ToPage $Wv 'test-log' @{ line = ''; done = $true; ok = $td[0].ok; suggestedRegistryName = [string]$td[0].suggestedRegistryName; suggestedDetectVersion = [string]$td[0].suggestedDetectVersion; wingetOffer = $wingetOffer }
      } catch { Send-ToPage $Wv 'test-log' @{ line = $_.Exception.Message; done = $true; ok = $false } }
      finally { $ps.Dispose(); $rs.Dispose(); $job.Finished = $true }
    }
  }.GetNewClosure())
  $timer.Start()
}

function Start-WingetLookupJob {
  # Background half of installer inspection: counts the files beside the installer and, unless outbound lookups are off, asks winget.
  param($Wv, [string]$InstallerPath, [hashtable]$Inspection, [bool]$UseWinget = $true)
  $functions = foreach ($name in @('Find-WingetInstaller','Invoke-WingetQuery','Get-WingetManifestPath','ConvertFrom-SimpleYaml',
                                   'Select-WingetInstallerEntry','ConvertTo-WingetSilentArgs','ConvertTo-WingetNormalName','ConvertTo-LooseVersion',
                                   'Get-InstallerFolderInfo')) {
    "function $name {`n$((Get-Item "Function:\$name").ScriptBlock)`n}"
  }
  if ($UseWinget -and -not ((Test-Path -LiteralPath (Join-Path $WingetCacheDir 'index.db')) -and (Test-Path -LiteralPath (Join-Path $KevCacheDir 'kev.json')))) { Start-WingetIndexRefresh }
  $result = [hashtable]::Synchronized(@{})
  $rs = [runspacefactory]::CreateRunspace()
  $ps = $null
  try {
    $rs.Open()
    foreach ($vn in @('WingetCacheDir','WingetCacheURL')) { $rs.SessionStateProxy.SetVariable($vn, (Get-Variable $vn -ValueOnly -Scope Script)) }
    $rs.SessionStateProxy.SetVariable('WingetSqliteSource', $global:WingetSqliteSource)
    $rs.SessionStateProxy.SetVariable('_result', $result)
    $rs.SessionStateProxy.SetVariable('_path', $InstallerPath)
    $rs.SessionStateProxy.SetVariable('_inspection', $Inspection)
    $rs.SessionStateProxy.SetVariable('_useWinget', $UseWinget)
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript(($functions -join "`n") + "`n" + {
      $global:WingetSqliteSource = $WingetSqliteSource
      try {
        $f = Get-InstallerFolderInfo -InstallerPath $_path
        $_result.folder = @{ files = $f.Files; bytes = $f.Bytes; isRoot = $f.IsRoot; tooMany = $f.TooMany }
      } catch { $_result.folder = @{ files = 0; bytes = 0; isRoot = $false; tooMany = $true } }
      try {
        if (-not $_useWinget) { $_result.note = 'winget lookups are off (Settings > online lookups)'; return }
        if (-not (Test-Path -LiteralPath (Join-Path $WingetCacheDir 'index.db'))) { $_result.note = 'winget catalogue still downloading - switches are from file inspection'; return }
        $match = Find-WingetInstaller -InstallerPath $_path -ProductCode $_inspection.ProductCode -Name $_inspection.DisplayName `
          -Publisher $_inspection.Publisher -Version $_inspection.Version
        if ($match) { $_result.match = $match } else { $_result.note = 'not in the winget catalogue - switches are from file inspection' }
      } catch { $_result.note = "winget lookup failed: $($_.Exception.Message)" }
    }.ToString())
    $handle = $ps.BeginInvoke()
  } catch {
    if ($ps) { $ps.Dispose() }
    $rs.Dispose()
    Write-AppLog "winget lookup could not start: $($_.Exception.Message)" WARN
    Send-ToPage $Wv 'installer-winget-result' @{ path = $InstallerPath; match = $null; note = 'winget lookup could not start - switches are from file inspection'
                                                 folder = @{ files = 0; bytes = 0; isRoot = $false; tooMany = $true } }
    return
  }
  $started = [Diagnostics.Stopwatch]::StartNew()
  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(250)
  $state = @{ Sent = $false }
  $timer.Add_Tick({
    if (-not $state.Sent) {
      if (-not $handle.IsCompleted -and $started.Elapsed.TotalSeconds -lt 60) { return }
      if (-not $handle.IsCompleted) { $result.note = 'winget lookup timed out - switches are from file inspection'; $ps.BeginStop($null, $null) | Out-Null }
      else { try { $ps.EndInvoke($handle) | Out-Null } catch { $result.note = "winget lookup failed: $($_.Exception.Message)" } }
      $known = if ($result.match -and $result.match.Id) { try { Find-KnownApp -WingetId $result.match.Id } catch { $null } } else { $null }
      Send-ToPage $Wv 'installer-winget-result' @{ path = $InstallerPath; match = $result.match; note = [string]$result.note; folder = $result.folder; known = $known }
      $state.Sent = $true
    }
    # A timed-out lookup keeps ticking until its pipeline has stopped, then releases the runspace.
    if ($ps.InvocationStateInfo.State -notin 'NotStarted', 'Running', 'Stopping') { $timer.Stop(); $ps.Dispose(); $rs.Dispose() }
  }.GetNewClosure())
  $timer.Start()
}

function Send-ToPage {
  param($Wv, [string]$Type, [hashtable]$Payload)
  $json = (@{ type = $Type; payload = $Payload } | ConvertTo-Json -Depth 8 -Compress)
  try {
    if (-not $Wv.CoreWebView2 -or $Wv.Dispatcher.HasShutdownStarted) { throw 'The application view is unavailable.' }
    $Wv.Dispatcher.Invoke([action]{ $Wv.CoreWebView2.PostWebMessageAsJson($json) })
  } catch { Write-AppLog "Could not deliver UI event '$Type': $($_.Exception.Message)" ERROR }
}

function Get-BuildFunctionSource {
  # The named functions and every function they call, as source for a runspace.
  param([string[]]$Roots = @('Invoke-HeadlessPackageBuild', 'Get-PreflightFindings'))
  $pending = [Collections.Generic.Queue[string]]::new()
  foreach ($root in $Roots) { $pending.Enqueue($root) }
  $seen = @{}
  $definitions = [Collections.Generic.List[string]]::new()
  while ($pending.Count -gt 0) {
    $name = $pending.Dequeue()
    if ($seen.ContainsKey($name)) { continue }
    $seen[$name] = $true
    if ($name -like 'Show-Wpf*' -or $name -in @('Write-Host','Write-AppLog','Write-OK','Write-Warn','Write-Fail','Write-Info','Write-Step')) { continue }
    $fn = Get-Item -LiteralPath "Function:\$name" -ErrorAction SilentlyContinue
    if (-not $fn) { continue }
    $definitions.Add("function $name {`n$($fn.ScriptBlock)`n}")
    foreach ($command in $fn.ScriptBlock.Ast.FindAll({ param($node) $node -is [Management.Automation.Language.CommandAst] }, $true)) {
      $dependency = $command.GetCommandName()
      if ($dependency) { $pending.Enqueue($dependency) }
    }
  }
  if (-not $definitions.Count) { throw 'Build engine functions are unavailable.' }
  return $definitions -join "`n"
}

function Start-PackageBuildJob {
  param($Wv, [hashtable]$Config, [hashtable]$FormData)

  if ($script:ActiveBuild -and -not $script:ActiveBuild.Finished) { throw 'A build is already running. Wait for it to finish before starting another.' }
  if ($script:ActiveTest -and -not $script:ActiveTest.Finished) { throw 'Wait for the local test to finish before rebuilding.' }

  $bq = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))
  $bd = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))

  # Get-PackagingProfiles is not loaded in the child runspace.
  $_profile = @{ OrgName = ''; LogoImagePath = ''; BannerImagePath = '' }
  if ($FormData.ProfileName) {
    $_pp = (Get-PackagingProfiles).Profiles | Where-Object { $_.Name -eq $FormData.ProfileName } | Select-Object -First 1
    if ($_pp) {
      if ($_pp.OrgName) { $_profile.OrgName = $_pp.OrgName }
      $_profile.LogoImagePath   = $_pp.LogoImagePath
      $_profile.BannerImagePath = $_pp.BannerImagePath
    }
  }
  if ($FormData.OverrideOrgName)         { $_profile.OrgName = $FormData.OverrideOrgName }
  if ($FormData.OverrideLogoImagePath)   { $_profile.LogoImagePath = $FormData.OverrideLogoImagePath }
  if ($FormData.OverrideBannerImagePath) { $_profile.BannerImagePath = $FormData.OverrideBannerImagePath }

  # Never run $__CoreSrc whole: its single-instance mutex is held by this process, so it would exit.
  $_buildFnSrc = Get-BuildFunctionSource

  $rs = [runspacefactory]::CreateRunspace()
  $ps = $null
  try {
  $rs.Open()
  $rs.SessionStateProxy.SetVariable('_bq', $bq)
  $rs.SessionStateProxy.SetVariable('_bd', $bd)
  $rs.SessionStateProxy.SetVariable('_cfg', $Config.Clone())
  $_fdCopy = $FormData.Clone()
  # The CISA catalogue is read only when online lookups are on; it is downloaded with the winget catalogue.
  $kevFile = Join-Path $KevCacheDir 'kev.json'
  if (-not $Config.DisableReleaseCheck -and (Test-Path -LiteralPath $kevFile)) { $_fdCopy.KevPath = $kevFile }
  $_fdCopy.NvdLookups = [bool]$Config.NvdLookups -and -not $Config.DisableReleaseCheck
  $rs.SessionStateProxy.SetVariable('_fd', $_fdCopy)
  $rs.SessionStateProxy.SetVariable('_profile', $_profile)
  $_memory = try { (Get-AppMemory)[[string]$FormData.AppID] } catch { $null }
  $rs.SessionStateProxy.SetVariable('_history', @(if ($_memory) { $_memory.builds }))
  $rs.SessionStateProxy.SetVariable('_fnSrc', $_buildFnSrc)
  $rs.SessionStateProxy.SetVariable('ArpMatchFnText', $global:ArpMatchFnText)
  $rs.SessionStateProxy.SetVariable('EventSecretB64', $global:EventSecretB64)
  foreach ($vn in @('XmlFile','IntuneWinUtilPath','IntuneWinUtilURL','TempBase','OutputBase',
                     'PSADTCacheDir','PSADTv3URL','PSADTModOnlyURL',
                     'DriverStoreBase','DriverLibraryFile','InstallPrinterScriptSrc','DetectPrinterScriptSrc','UninstallPrinterScriptSrc')) {
    $rs.SessionStateProxy.SetVariable($vn, (Get-Variable $vn -ValueOnly -Scope Script -ErrorAction SilentlyContinue))
  }

  $ps = [powershell]::Create()
  $ps.Runspace = $rs
  [void]$ps.AddScript({
    # $global: vars are not shared across runspaces.
    $global:_DpapiPrefix = 'DPAPI:'
    $global:_CredMgrSentinel = 'CREDMGR'
    $ErrorActionPreference = 'Stop'
    function Write-AppLog { param([string]$Message,[string]$Level='INFO') if ($_bq.Count -lt 2000) { $_bq.Enqueue("log|[$Level] $Message") } }
    function Write-Host   { param([object]$O,[string]$ForegroundColor='Gray',[switch]$NoNewline) if ($_bq.Count -lt 2000) { $_bq.Enqueue("line|$O") } }
    function Write-OK     { param([string]$M) Write-Host "  [OK]  $M" }
    function Write-Warn   { param([string]$M) Write-Host "  [!!]  $M" }
    function Write-Fail   { param([string]$M) throw $M }
    function Write-Info   { param([string]$M) Write-Host "  [--]  $M" }
    function Write-Step   { param([string]$N,[string]$M) $_bq.Enqueue("step|$N|$M") }
    function Show-WpfMsg  { param([string]$Title='',[string]$Message='',[string]$Type='info',[switch]$Confirm,[string]$Detail,[string]$YesLabel,[string]$NoLabel)
      if ($Type -eq 'error') { throw "$Title`: $Message $Detail" }
      Write-Host "[$Title] $Message"
      if ($Confirm) { return $true }
    }
    function Show-WpfAppForm { param([hashtable]$Defaults=@{},[bool]$HasWorker=$false,[string]$OrgName='',[switch]$AmendMode) return $null }
    function Show-WpfPSADTExport { throw 'PSADT tooling is unavailable. Check the dependency cache and retry.' }

    try {
      Invoke-Expression $_fnSrc
      $installer = @{}
      if ($_fd.InstallerPath -and (Test-Path -LiteralPath $_fd.InstallerPath -PathType Leaf)) {
        $installer.sha256 = (Get-FileHash -LiteralPath $_fd.InstallerPath -Algorithm SHA256).Hash
        try {
          $sig = Get-AuthenticodeSignature -LiteralPath $_fd.InstallerPath
          $installer.status = [string]$sig.Status
          if ($sig.SignerCertificate) { $installer.signer = $sig.SignerCertificate.Subject; $installer.thumbprint = $sig.SignerCertificate.Thumbprint }
        } catch { $installer.status = '' }
      }
      $findings = if ($_fd.PackageKind -ne 'Printer') { @(Get-PreflightFindings -FormData $_fd -History $_history -Installer $installer) } else { @() }
      foreach ($finding in $findings) { Write-Host "  [$($finding.level)] $($finding.message)" }
      if (@($findings | Where-Object { $_.level -eq 'red' }).Count -and -not $_fd.OverrideRed) {
        $_bd.Add(@{ ok = $false; blocked = $true; findings = $findings; message = 'Pre-deploy checks stopped this build.' }) | Out-Null
        return
      }
      $result = Invoke-HeadlessPackageBuild -Config $_cfg -FormData $_fd -Profile $_profile
      $_bd.Add(@{ ok = $true; installer = $installer; findings = $findings; path = $result.OutputDir; paths = $result.OutputDirs; warning = $result.SyncWarning; appId = $_fd.AppID; displayName = $_fd.DisplayName; target = $_fd.SimplePkgTarget; profile = $_fd.ProfileName }) | Out-Null
    } catch {
      $_bd.Add(@{ ok = $false; message = $_.Exception.Message }) | Out-Null
    }
  })
  $handle = $ps.BeginInvoke()
  } catch {
    if ($ps) { $ps.Dispose() }
    $rs.Dispose()
    throw
  }
  $script:ActiveBuild = @{ PowerShell = $ps; Handle = $handle; Started = [Diagnostics.Stopwatch]::StartNew(); Id = [guid]::NewGuid().ToString('N') }
  $job = $script:ActiveBuild
  Write-AppLog "Build $($job.Id) started for $($FormData.AppID)" INFO
  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(150)
  $timer.Add_Tick({
    for ($i = 0; $i -lt 100 -and $bq.Count -gt 0; $i++) {
      $line = $bq.Dequeue()
      $parts = $line -split '\|', 2
      switch ($parts[0]) {
        'step' { $step = $parts[1] -split '\|', 2; Send-ToPage $Wv 'build-progress' @{ step = $step[0]; label = $step[1] } }
        default { Send-ToPage $Wv 'build-log' @{ line = $parts[1] } }
      }
    }
    if ($job.Started.Elapsed.TotalMinutes -gt 30 -and -not $handle.IsCompleted -and -not $job.StopHandle) {
      $job.StopHandle = $ps.BeginStop($null, $null)
    }
    if ($handle.IsCompleted -and $bq.Count -eq 0) {
      $timer.Stop()
      try {
        $ps.EndInvoke($handle) | Out-Null
        if ($bd.Count -ne 1) { throw 'Build ended without a result. Check the operation log.' }
        $done = $bd[0]
        if ($done.blocked) {
          Send-ToPage $Wv 'preflight-blocked' @{ findings = @($done.findings) }
          Write-AppLog "Build $($job.Id) stopped by pre-deploy checks" WARN
          return
        }
        if (-not $done.ok) { throw $done.message }
        if ($done.appId) { Set-DeployStatus -AppID $done.appId -AppName $done.displayName -Target $done.target -ProfileName $done.profile -OutputDir $done.path }
        try { Save-AppMemoryBuild -FormData $FormData -Installer $done.installer -OutputDir $done.path -Findings @($done.findings) }
        catch { Write-AppLog "Could not record the build in the app memory: $($_.Exception.Message)" WARN }
        Send-ToPage $Wv 'build-done' @{ path = $done.path; paths = $done.paths; warning = $done.warning; findings = @($done.findings); overridden = [bool]$FormData.OverrideRed }
        Write-AppLog "Build $($job.Id) succeeded in $([math]::Round($job.Started.Elapsed.TotalSeconds, 2))s" INFO
      } catch {
        Write-AppLog "Build $($job.Id) failed after $([math]::Round($job.Started.Elapsed.TotalSeconds, 2))s: $($_.Exception.Message)" ERROR
        Send-ToPage $Wv 'error' @{ message = $_.Exception.Message }
      } finally {
        $ps.Dispose(); $rs.Dispose()
        $job.Finished = $true
      }
    }
  }.GetNewClosure())
  $timer.Start()
}

$window.Add_Closing({
  param($sender, $eventArgs)
  if (($script:ActiveBuild -and -not $script:ActiveBuild.Finished) -or ($script:ActiveTest -and -not $script:ActiveTest.Finished)) {
    $eventArgs.Cancel = $true
    Send-ToPage $wv 'error' @{ message = 'An operation is still running. Wait for it to finish before closing AppUpdater.' }
  }
})
try { $window.ShowDialog() | Out-Null }
finally { $wv.Dispose() }
